pub fn sqlRowClaimForClause(clause: ast.SqlRowClaimClause) db_mod.types.RowClaimRequest {
    return .{
        .mode = clause.mode,
        .wait_policy = clause.wait_policy,
        .skip_locked = clause.wait_policy == .skip_locked,
    };
}

pub fn setSqlRowClaimClause(claim: *db_mod.types.RowClaimRequest, clause: ast.SqlRowClaimClause) void {
    claim.mode = clause.mode;
    claim.wait_policy = clause.wait_policy;
    claim.skip_locked = clause.wait_policy == .skip_locked;
}

pub fn sqlRowClaimModeName(mode: db_mod.types.RowClaimMode) []const u8 {
    return switch (mode) {
        .for_update => "for_update",
        .for_no_key_update => "for_no_key_update",
        .for_share => "for_share",
        .for_key_share => "for_key_share",
    };
}

pub fn sqlRowClaimWaitPolicyName(wait_policy: db_mod.types.RowClaimWaitPolicy) []const u8 {
    return switch (wait_policy) {
        .wait => "wait",
        .nowait => "nowait",
        .skip_locked => "skip_locked",
    };
}

pub fn sqlRowClaimFingerprintName(claim: db_mod.types.RowClaimRequest) []const u8 {
    return switch (claim.mode) {
        .for_update => switch (claim.effectiveWaitPolicy()) {
            .wait => "locked",
            .nowait => "nowait",
            .skip_locked => "skip_locked",
        },
        .for_no_key_update => switch (claim.effectiveWaitPolicy()) {
            .wait => "no_key_update",
            .nowait => "no_key_update_nowait",
            .skip_locked => "no_key_update_skip_locked",
        },
        .for_share => switch (claim.effectiveWaitPolicy()) {
            .wait => "share",
            .nowait => "share_nowait",
            .skip_locked => "share_skip_locked",
        },
        .for_key_share => switch (claim.effectiveWaitPolicy()) {
            .wait => "key_share",
            .nowait => "key_share_nowait",
            .skip_locked => "key_share_skip_locked",
        },
    };
}

pub fn booleanExpressionFromPredicateGroupsAlloc(
    alloc: std.mem.Allocator,
    groups: []db_mod.types.RelationalRowsExpressionPredicateGroup,
) !db_mod.types.RelationalRowsExpression {
    if (groups.len == 0) return error.UnsupportedSqlShape;
    if (groups.len == 1) return try booleanExpressionFromPredicateGroupAlloc(alloc, &groups[0]);

    const operands = try alloc.alloc(db_mod.types.RelationalRowsExpression, groups.len);
    var initialized: usize = 0;
    errdefer {
        for (operands[0..initialized]) |operand| freeExpression(alloc, operand);
        alloc.free(operands);
    }
    for (groups) |*group| {
        operands[initialized] = try booleanExpressionFromPredicateGroupAlloc(alloc, group);
        initialized += 1;
    }
    return .{
        .kind = .bool_or,
        .operands = operands,
    };
}

pub fn booleanExpressionFromPredicateGroupAlloc(
    alloc: std.mem.Allocator,
    group: *db_mod.types.RelationalRowsExpressionPredicateGroup,
) !db_mod.types.RelationalRowsExpression {
    if (group.conditions.len == 0) return try booleanLiteralExpressionAlloc(alloc, true);
    if (group.conditions.len == 1) {
        const conditions = group.conditions;
        const condition = conditions[0];
        @constCast(conditions)[0] = emptyExpressionCondition();
        const expression = try booleanExpressionFromConditionAlloc(alloc, condition);
        group.conditions = &.{};
        alloc.free(conditions);
        return expression;
    }

    const operands = try alloc.alloc(db_mod.types.RelationalRowsExpression, group.conditions.len);
    var initialized: usize = 0;
    errdefer {
        for (operands[0..initialized]) |operand| freeExpression(alloc, operand);
        alloc.free(operands);
    }
    const conditions = group.conditions;
    for (conditions, 0..) |condition, i| {
        @constCast(conditions)[i] = emptyExpressionCondition();
        operands[initialized] = try booleanExpressionFromConditionAlloc(alloc, condition);
        initialized += 1;
    }
    group.conditions = &.{};
    alloc.free(conditions);
    return .{
        .kind = .bool_and,
        .operands = operands,
    };
}

fn emptyExpressionCondition() db_mod.types.RelationalRowsExpressionCondition {
    return .{
        .lhs = .{ .kind = .value },
        .op = .eq,
        .rhs = &.{},
    };
}

pub fn booleanNotExpressionAlloc(
    alloc: std.mem.Allocator,
    operand: db_mod.types.RelationalRowsExpression,
) !db_mod.types.RelationalRowsExpression {
    var operand_transferred = false;
    errdefer if (!operand_transferred) freeExpression(alloc, operand);
    const operands = try alloc.alloc(db_mod.types.RelationalRowsExpression, 1);
    var operands_transferred = false;
    errdefer if (!operands_transferred) alloc.free(operands);
    operands[0] = operand;
    operand_transferred = true;
    operands_transferred = true;
    return .{
        .kind = .bool_not,
        .operands = operands,
    };
}

pub fn booleanExpressionConditionAlloc(
    alloc: std.mem.Allocator,
    expression: db_mod.types.RelationalRowsExpression,
) !db_mod.types.RelationalRowsExpressionCondition {
    var expression_transferred = false;
    errdefer if (!expression_transferred) freeExpression(alloc, expression);
    const rhs = try alloc.alloc(db_mod.types.RelationalRowsExpression, 1);
    var rhs_transferred = false;
    errdefer if (!rhs_transferred) alloc.free(rhs);
    rhs[0] = try booleanLiteralExpressionAlloc(alloc, true);
    var rhs_expression_transferred = false;
    errdefer if (!rhs_expression_transferred) freeExpression(alloc, rhs[0]);
    expression_transferred = true;
    rhs_expression_transferred = true;
    rhs_transferred = true;
    return .{
        .lhs = expression,
        .op = .eq,
        .rhs = rhs,
    };
}

pub fn booleanExpressionFromConditionAlloc(
    alloc: std.mem.Allocator,
    condition: db_mod.types.RelationalRowsExpressionCondition,
) !db_mod.types.RelationalRowsExpression {
    var condition_transferred = false;
    errdefer if (!condition_transferred) freeExpressionCondition(alloc, condition);

    const branches = try alloc.alloc(db_mod.types.RelationalRowsExpressionCaseBranch, 1);
    var branches_transferred = false;
    errdefer if (!branches_transferred) alloc.free(branches);
    const then_expression = try booleanLiteralExpressionAlloc(alloc, true);
    var then_transferred = false;
    errdefer if (!then_transferred) freeExpression(alloc, then_expression);

    const fallback = try alloc.alloc(db_mod.types.RelationalRowsExpression, 1);
    var fallback_transferred = false;
    errdefer if (!fallback_transferred) alloc.free(fallback);
    fallback[0] = try booleanLiteralExpressionAlloc(alloc, false);
    var fallback_expression_transferred = false;
    errdefer if (!fallback_expression_transferred) freeExpression(alloc, fallback[0]);

    branches[0] = .{
        .when = condition,
        .then = then_expression,
    };
    condition_transferred = true;
    then_transferred = true;
    branches_transferred = true;
    fallback_expression_transferred = true;
    fallback_transferred = true;
    return .{
        .kind = .case,
        .case_branches = branches,
        .case_else = fallback,
    };
}

pub fn booleanLiteralExpressionAlloc(
    alloc: std.mem.Allocator,
    value: bool,
) !db_mod.types.RelationalRowsExpression {
    return .{
        .kind = .value,
        .value_json = try alloc.dupe(u8, if (value) "true" else "false"),
    };
}

pub fn appendExpressionConditionGroup(
    alloc: std.mem.Allocator,
    expression_groups: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
    condition: db_mod.types.RelationalRowsExpressionCondition,
) !void {
    var condition_transferred = false;
    errdefer if (!condition_transferred) freeExpressionCondition(alloc, condition);
    const conditions = try alloc.alloc(db_mod.types.RelationalRowsExpressionCondition, 1);
    var conditions_transferred = false;
    errdefer if (!conditions_transferred) alloc.free(conditions);
    conditions[0] = condition;
    condition_transferred = true;
    try expression_groups.append(alloc, .{ .conditions = conditions });
    conditions_transferred = true;
}

pub fn andExpressionPredicateAlternatives(
    alloc: std.mem.Allocator,
    groups: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
    alternatives: []const db_mod.types.RelationalRowsExpressionPredicateGroup,
) !void {
    if (groups.items.len == 0 or alternatives.len == 0) return error.UnsupportedSqlShape;
    var combined = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    var combined_transferred = false;
    errdefer {
        if (!combined_transferred) freeExpressionPredicateGroups(alloc, combined.items);
        combined.deinit(alloc);
    }

    for (groups.items) |base| {
        for (alternatives) |alternative| {
            const conditions = try cloneExpressionConditionsConcatAlloc(alloc, base.conditions, alternative.conditions);
            var conditions_transferred = false;
            errdefer if (!conditions_transferred) {
                freeExpressionConditions(alloc, conditions);
                if (conditions.len > 0) alloc.free(conditions);
            };
            try combined.append(alloc, .{ .conditions = conditions });
            conditions_transferred = true;
        }
    }

    freeExpressionPredicateGroups(alloc, groups.items);
    groups.deinit(alloc);
    groups.* = combined;
    combined_transferred = true;
}

pub fn parseWhereAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    params: []const value_mod.SqlValue,
    schema: runtime_schema.TableSchema,
    type_context: RowExpressionTypeContext,
    field_expression_qualifiers: []const []const u8,
    returning_expression_qualifiers: []const []const u8,
    defer_row_expression_field_validation: bool,
    predicates: *std.ArrayListUnmanaged(runtime_schema.RelationalCheck),
    json_contains: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonContainsPredicate),
    json_path_eq: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonPathEqPredicate),
    json_path_exists: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonPathExistsPredicate),
    array_any: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayAnyPredicate),
    array_contains: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayContainsPredicate),
    array_eq: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayEqPredicate),
    in_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsInPredicate),
    text_patterns: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsTextPatternPredicate),
    or_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsPredicateGroup),
    not_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsPredicateGroup),
    access_or_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsAccessPredicateGroup),
    access_not_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsAccessPredicateGroup),
    expression_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition),
    expression_or_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
    expression_not_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
    expression_array_contains: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionArrayContainsPredicate),
    realtime_ns: u64,
    fixed_binary_hooks: FixedBinaryRowExpressionParserOptions,
    bare_boolean_hooks: BareBooleanWhereExpressionParserOptions,
    expression_alternatives_hooks: ExpressionWhereConditionAlternativesParserOptions,
    expression_condition_hooks: ExpressionWhereConditionsParserOptions,
    generated_expression_ast: ?*const generated_parser.GeneratedSqlExpressionAst,
) !void {
    if (canParseBareBooleanWhereExpression(tokens, pos.*, schema)) {
        try parseBareBooleanWhereExpressionAlloc(alloc, tokens, pos, type_context, expression_predicates, bare_boolean_hooks);
        return;
    }
    if (parser.hasTopLevelOrBeforeTailToken(tokens, pos.*, sqlWhereTailClauseKeywordToken)) {
        if (whereTopLevelOrHasExpressionPredicateStart(tokens, pos.*)) {
            try parseExpressionOrWhereWithGeneratedAlloc(alloc, tokens, pos, params, type_context, defer_row_expression_field_validation, expression_or_predicates, expression_alternatives_hooks, generated_expression_ast);
        } else if (whereTopLevelOrHasAccessPredicate(tokens, pos.*)) {
            try parseAccessOrWhereAlloc(alloc, tokens, pos, params, schema, field_expression_qualifiers, returning_expression_qualifiers, defer_row_expression_field_validation, access_or_predicates, realtime_ns, generated_expression_ast);
        } else {
            try parseScalarOrWhereAlloc(alloc, tokens, pos, params, schema, field_expression_qualifiers, returning_expression_qualifiers, defer_row_expression_field_validation, or_predicates, realtime_ns, generated_expression_ast);
        }
        return;
    }
    if (!canParseAccessNotWhere(tokens, pos.*) and try whereHasArrayOverlapPredicateAlloc(
        alloc,
        tokens,
        pos,
        schema,
        field_expression_qualifiers,
        returning_expression_qualifiers,
        defer_row_expression_field_validation,
    )) {
        try parseAccessOrWhereAlloc(alloc, tokens, pos, params, schema, field_expression_qualifiers, returning_expression_qualifiers, defer_row_expression_field_validation, access_or_predicates, realtime_ns, generated_expression_ast);
        return;
    }
    while (true) {
        if (canParseScalarNotWhere(tokens, pos.*)) {
            const generated_condition_expression = try generatedPredicateExpressionAtStart(pos.*, generated_expression_ast);
            try parseScalarNotWhereAlloc(alloc, tokens, pos, params, schema, field_expression_qualifiers, returning_expression_qualifiers, defer_row_expression_field_validation, not_predicates, realtime_ns, generated_condition_expression);
        } else if (canParseExpressionNotWhere(tokens, pos.*)) {
            try parseExpressionNotWhereWithGeneratedAlloc(alloc, tokens, pos, params, type_context, defer_row_expression_field_validation, expression_not_predicates, expression_alternatives_hooks, generated_expression_ast);
        } else if (canParseAccessNotWhere(tokens, pos.*)) {
            const generated_condition_expression = try generatedPredicateExpressionAtStart(pos.*, generated_expression_ast);
            try parseAccessNotWhereAlloc(alloc, tokens, pos, params, schema, field_expression_qualifiers, returning_expression_qualifiers, defer_row_expression_field_validation, access_not_predicates, realtime_ns, generated_condition_expression);
        } else if (peekStringToArrayFunctionCall(tokens, pos.*)) {
            if (stringToArrayPredicateIsContainment(tokens, pos.*)) {
                try validateGeneratedExpressionPredicateKind(try generatedPredicateExpressionAtStart(pos.*, generated_expression_ast), .contains);
                const predicate = try parseExpressionArrayContainsPredicateAlloc(
                    alloc,
                    tokens,
                    pos,
                    params,
                    type_context,
                    fixed_binary_hooks,
                );
                var predicate_transferred = false;
                errdefer if (!predicate_transferred) freeExpressionArrayContainsOne(alloc, predicate);
                try expression_array_contains.append(alloc, predicate);
                predicate_transferred = true;
            } else {
                try parseExpressionWhereConditionsAlloc(
                    alloc,
                    tokens,
                    pos,
                    params,
                    type_context,
                    defer_row_expression_field_validation,
                    expression_predicates,
                    expression_or_predicates,
                    expression_not_predicates,
                    expression_condition_hooks,
                );
            }
        } else if (canParseBareBooleanWhereExpression(tokens, pos.*, schema)) {
            try parseBareBooleanWhereExpressionAlloc(alloc, tokens, pos, type_context, expression_predicates, bare_boolean_hooks);
        } else if (parenthesizedWhereHasTopLevelOr(tokens, pos.*)) {
            try parseExpressionOrWhereWithGeneratedAlloc(alloc, tokens, pos, params, type_context, defer_row_expression_field_validation, expression_or_predicates, expression_alternatives_hooks, generated_expression_ast);
        } else if (try canParseExpressionWhereCondition(
            alloc,
            tokens,
            pos.*,
            schema,
            field_expression_qualifiers,
            returning_expression_qualifiers,
            defer_row_expression_field_validation,
        )) {
            var expression_condition_hooks_with_generated = expression_condition_hooks;
            expression_condition_hooks_with_generated.generated_expression_ast = try generatedPredicateExpressionAtStart(pos.*, generated_expression_ast);
            try parseExpressionWhereConditionsAlloc(
                alloc,
                tokens,
                pos,
                params,
                type_context,
                defer_row_expression_field_validation,
                expression_predicates,
                expression_or_predicates,
                expression_not_predicates,
                expression_condition_hooks_with_generated,
            );
        } else {
            const generated_atom_expression = try generatedPredicateExpressionAtStart(pos.*, generated_expression_ast);
            try parseWhereAtomAlloc(
                alloc,
                tokens,
                pos,
                params,
                schema,
                field_expression_qualifiers,
                returning_expression_qualifiers,
                defer_row_expression_field_validation,
                predicates,
                json_contains,
                json_path_eq,
                json_path_exists,
                array_any,
                array_contains,
                array_eq,
                in_predicates,
                text_patterns,
                or_predicates,
                false,
                realtime_ns,
                generated_atom_expression,
            );
        }
        if (!parser.matchKeyword(tokens, pos, "and")) break;
    }
}

pub fn parenthesizedWhereHasTopLevelOr(tokens: []const Token, pos: usize) bool {
    if (pos >= tokens.len or tokens[pos].kind != .lparen) return false;
    const close_index = parser.findMatchingRParenIndex(tokens, pos) orelse return false;
    var depth: usize = 0;
    var index = pos + 1;
    while (index < close_index) : (index += 1) {
        switch (tokens[index].kind) {
            .lparen => depth += 1,
            .rparen => if (depth == 0) return false else {
                depth -= 1;
            },
            .identifier => if (depth == 0 and tokens[index].matchesKeywordTag(.@"or")) return true,
            else => {},
        }
    }
    return false;
}

pub fn whereTopLevelOrHasExpressionPredicateStart(tokens: []const Token, pos: usize) bool {
    var depth: usize = 0;
    var index = pos;
    var expect_predicate_start = true;
    while (index < tokens.len) : (index += 1) {
        const token = tokens[index];
        switch (token.kind) {
            .lparen => {
                if (depth == 0 and expect_predicate_start) {
                    const inner = parser.predicateStartIndexAfterOpenParens(tokens, index);
                    if (expressionCanStartAt(tokens, inner) or
                        textPatternSetPredicateCanStartAt(tokens, inner) or
                        jsonKeySetExpressionCanStartAt(tokens, inner) or
                        jsonExtractExpressionPredicateCanStartAt(tokens, inner) or
                        jsonExtractNullTestPredicateCanStartAt(tokens, inner))
                    {
                        return true;
                    }
                }
                depth += 1;
                expect_predicate_start = false;
            },
            .rparen => if (depth > 0) {
                depth -= 1;
            },
            .semicolon => if (depth == 0) return false,
            .identifier => if (depth == 0) {
                if (sqlWhereTailClauseKeywordToken(token)) return false;
                if (token.matchesKeywordTag(.@"and") or token.matchesKeywordTag(.@"or")) {
                    expect_predicate_start = true;
                    continue;
                }
                if (expect_predicate_start and
                    (expressionCanStartAt(tokens, index) or
                        textPatternSetPredicateCanStartAt(tokens, index) or
                        jsonKeySetExpressionCanStartAt(tokens, index) or
                        jsonExtractExpressionPredicateCanStartAt(tokens, index) or
                        jsonExtractNullTestPredicateCanStartAt(tokens, index)))
                {
                    return true;
                }
                expect_predicate_start = false;
            },
            .number, .string, .placeholder, .minus => if (depth == 0) {
                if (expect_predicate_start and
                    (expressionCanStartAt(tokens, index) or
                        textPatternSetPredicateCanStartAt(tokens, index) or
                        jsonKeySetExpressionCanStartAt(tokens, index)))
                {
                    return true;
                }
                expect_predicate_start = false;
            },
            else => if (depth == 0 and expect_predicate_start) {
                expect_predicate_start = false;
            },
        }
    }
    return false;
}

pub fn whereTopLevelOrHasAccessPredicate(tokens: []const Token, pos: usize) bool {
    var depth: usize = 0;
    var index = pos;
    while (index < tokens.len) : (index += 1) {
        const token = tokens[index];
        switch (token.kind) {
            .lparen => depth += 1,
            .rparen => if (depth > 0) {
                depth -= 1;
            },
            .semicolon => if (depth == 0) return false,
            .arrow_text, .arrow_json, .path_arrow_text, .path_arrow_json, .at_contains, .range_overlap, .question => return true,
            .identifier => {
                if (depth == 0 and sqlWhereTailClauseKeywordToken(token)) return false;
                if (token.matchesKeywordTag(.like) or
                    token.matchesKeywordTag(.ilike))
                {
                    return true;
                }
                if (index + 2 < tokens.len and
                    (tokens[index + 1].kind == .eq or tokens[index + 1].kind == .neq) and
                    tokens[index + 2].matchesKeywordTag(.array))
                {
                    return true;
                }
            },
            else => {},
        }
    }
    return false;
}

fn whereHasTopLevelAndBeforeTailToken(tokens: []const Token, pos: usize) bool {
    var depth: usize = 0;
    var index = pos;
    while (index < tokens.len) : (index += 1) {
        const token = tokens[index];
        switch (token.kind) {
            .lparen => depth += 1,
            .rparen => if (depth > 0) {
                depth -= 1;
            },
            .semicolon => if (depth == 0) return false,
            .identifier => if (depth == 0) {
                if (sqlWhereTailClauseKeywordToken(token)) return false;
                if (token.matchesKeywordTag(.@"and")) return true;
            },
            else => {},
        }
    }
    return false;
}

fn generatedSingleWhereAtomExpression(
    tokens: []const Token,
    pos: usize,
    generated_expression_ast: ?*const generated_parser.GeneratedSqlExpressionAst,
) ?*const generated_parser.GeneratedSqlExpressionAst {
    const expression = generated_expression_ast orelse return null;
    const expression_tokens = expression.tokens orelse return null;
    if (expression_tokens.start != pos or whereHasTopLevelAndBeforeTailToken(tokens, pos)) return null;
    return expression;
}

fn generatedPredicateExpressionAtStart(
    pos: usize,
    generated_expression_ast: ?*const generated_parser.GeneratedSqlExpressionAst,
) !?*const generated_parser.GeneratedSqlExpressionAst {
    const expression = generated_expression_ast orelse return null;
    const expression_tokens = expression.tokens orelse return null;
    if (expression_tokens.start == pos) {
        switch (expression.kind) {
            .logical_or, .logical_and, .grouped => {},
            else => return expression,
        }
    }

    switch (expression.kind) {
        .logical_or, .logical_and => {
            const list = expression.boolean_condition_items;
            if (list.count == 0 or list.items.len != list.count or list.expressions.len != list.count) return error.UnsupportedSqlShape;
            for (list.items, 0..) |item, index| {
                if (item.start == pos) return &list.expressions[index];
                if (item.start <= pos and pos < item.end) {
                    if (try generatedPredicateExpressionAtStart(pos, &list.expressions[index])) |child| return child;
                }
            }
            return null;
        },
        .grouped => return try generatedPredicateExpressionAtStart(pos, expression.inner_expression),
        .logical_not => return try generatedPredicateExpressionAtStart(pos, expression.right_expression),
        else => return null,
    }
}

pub fn stringToArrayPredicateIsContainment(tokens: []const Token, pos: usize) bool {
    if (!peekStringToArrayFunctionCall(tokens, pos)) return false;
    var depth: usize = 0;
    var index = pos;
    while (index < tokens.len) : (index += 1) {
        const kind = tokens[index].kind;
        switch (kind) {
            .lparen => depth += 1,
            .rparen => {
                if (depth == 0) return false;
                depth -= 1;
                if (depth == 0) {
                    return index + 1 < tokens.len and tokens[index + 1].kind == .at_contains;
                }
            },
            else => {},
        }
    }
    return false;
}

pub fn valueEqualsAnyArrayPredicateCanStart(tokens: []const Token, pos: usize) bool {
    if (pos >= tokens.len) return false;
    const value_end = switch (tokens[pos].kind) {
        .string, .number, .placeholder => pos + 1,
        .minus => blk: {
            if (pos + 1 >= tokens.len or tokens[pos + 1].kind != .number) return false;
            break :blk pos + 2;
        },
        .identifier => blk: {
            if (!tokens[pos].matchesKeywordTag(.null) and
                !tokens[pos].matchesKeywordTag(.true) and
                !tokens[pos].matchesKeywordTag(.false))
            {
                return false;
            }
            break :blk pos + 1;
        },
        else => return false,
    };
    if (value_end + 3 >= tokens.len) return false;
    return tokens[value_end].kind == .eq and
        tokens[value_end + 1].kind == .identifier and
        (tokens[value_end + 1].matchesKeywordTag(.any) or
            tokens[value_end + 1].matchesKeywordTag(.some)) and
        tokens[value_end + 2].kind == .lparen and
        tokens[value_end + 3].kind == .identifier;
}

pub fn whereHasArrayOverlapPredicateAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    schema: runtime_schema.TableSchema,
    field_expression_qualifiers: []const []const u8,
    returning_expression_qualifiers: []const []const u8,
    defer_row_expression_field_validation: bool,
) !bool {
    const saved_pos = pos.*;
    defer pos.* = saved_pos;

    var depth: usize = 0;
    var index = saved_pos;
    while (index < tokens.len) : (index += 1) {
        const token = tokens[index];
        switch (token.kind) {
            .lparen => depth += 1,
            .rparen => if (depth > 0) {
                depth -= 1;
            },
            .semicolon => if (depth == 0) return false,
            .identifier => {
                if (depth == 0 and sqlWhereTailClauseKeywordToken(token)) return false;
                if (try arrayOverlapPredicateCanStartAtAlloc(
                    alloc,
                    tokens,
                    pos,
                    index,
                    schema,
                    field_expression_qualifiers,
                    returning_expression_qualifiers,
                    defer_row_expression_field_validation,
                )) return true;
            },
            else => {},
        }
    }
    return false;
}

fn arrayOverlapPredicateCanStartAtAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    index: usize,
    schema: runtime_schema.TableSchema,
    field_expression_qualifiers: []const []const u8,
    returning_expression_qualifiers: []const []const u8,
    defer_row_expression_field_validation: bool,
) !bool {
    const saved_pos = pos.*;
    pos.* = index;
    defer pos.* = saved_pos;

    const parsed_field = parseRowExpressionFieldOwnedAlloc(
        alloc,
        tokens,
        pos,
        schema,
        field_expression_qualifiers,
        returning_expression_qualifiers,
        defer_row_expression_field_validation,
    ) catch |err| return switch (err) {
        error.UnsupportedSqlShape, error.InvalidSqlCatalog => false,
        else => err,
    };
    defer alloc.free(parsed_field);
    if (pos.* >= tokens.len or tokens[pos.*].kind != .range_overlap) return false;

    const field = binder.normalizeRowExpressionFieldAlloc(
        alloc,
        schema,
        parsed_field,
        field_expression_qualifiers,
        returning_expression_qualifiers,
        defer_row_expression_field_validation,
    ) catch |err| return switch (err) {
        error.UnsupportedSqlShape, error.InvalidSqlCatalog => false,
        else => err,
    };
    defer alloc.free(field);
    return binder.relationalColumnForField(schema, field, .array) != null;
}

pub fn parseArrayOverlapIntoAccessBranchesAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    params: []const value_mod.SqlValue,
    schema: runtime_schema.TableSchema,
    field_expression_qualifiers: []const []const u8,
    returning_expression_qualifiers: []const []const u8,
    defer_row_expression_field_validation: bool,
    branches: *std.ArrayListUnmanaged(AccessPredicateBranch),
    generated_expression_ast: ?*const generated_parser.GeneratedSqlExpressionAst,
) !bool {
    const saved_pos = pos.*;
    const parsed_field = parseRowExpressionFieldOwnedAlloc(
        alloc,
        tokens,
        pos,
        schema,
        field_expression_qualifiers,
        returning_expression_qualifiers,
        defer_row_expression_field_validation,
    ) catch |err| {
        pos.* = saved_pos;
        return switch (err) {
            error.UnsupportedSqlShape, error.InvalidSqlCatalog => false,
            else => err,
        };
    };
    defer alloc.free(parsed_field);
    if (pos.* >= tokens.len or tokens[pos.*].kind != .range_overlap) {
        pos.* = saved_pos;
        return false;
    }

    const field = binder.normalizeRowExpressionFieldAlloc(
        alloc,
        schema,
        parsed_field,
        field_expression_qualifiers,
        returning_expression_qualifiers,
        defer_row_expression_field_validation,
    ) catch |err| {
        pos.* = saved_pos;
        return switch (err) {
            error.UnsupportedSqlShape, error.InvalidSqlCatalog => false,
            else => err,
        };
    };
    defer alloc.free(field);
    const column = binder.relationalColumnForField(schema, field, .array) orelse {
        pos.* = saved_pos;
        return false;
    };
    _ = parser.matchToken(tokens, pos, .range_overlap);
    try validateGeneratedExpressionPredicateKind(generated_expression_ast, .overlaps);
    const values_json = try value_mod.parseArrayPredicateValueAlloc(alloc, tokens, pos, params);
    defer alloc.free(values_json);
    try value_mod.validateSqlArrayValueJson(alloc, column, values_json);
    try expandArrayOverlapValuesIntoAccessBranches(alloc, branches, field, values_json);
    return true;
}

pub fn parseExpressionArrayContainsPredicateAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    params: []const value_mod.SqlValue,
    type_context: RowExpressionTypeContext,
    hooks: FixedBinaryRowExpressionParserOptions,
) !db_mod.types.RelationalRowsExpressionArrayContainsPredicate {
    const expression = try parseStringToArrayRowExpressionAlloc(alloc, tokens, pos, type_context, hooks);
    var expression_transferred = false;
    errdefer if (!expression_transferred) freeExpression(alloc, expression);
    try parser.expectToken(tokens, pos, .at_contains);
    const value_json = if (parser.peekKeyword(tokens, pos.*, "array"))
        try value_mod.parseSqlArrayConstructorJsonAlloc(alloc, tokens, pos, params)
    else
        try value_mod.parseRequiredJsonDocumentValueAlloc(alloc, tokens, pos, params);
    var value_transferred = false;
    errdefer if (!value_transferred) alloc.free(value_json);
    try value_mod.validateJsonStringArray(alloc, value_json);

    expression_transferred = true;
    value_transferred = true;
    return .{
        .expression = expression,
        .value_json = value_json,
    };
}

pub fn parseValueEqualsAnyArrayPredicateAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    params: []const value_mod.SqlValue,
    schema: runtime_schema.TableSchema,
    field_expression_qualifiers: []const []const u8,
    returning_expression_qualifiers: []const []const u8,
    defer_row_expression_field_validation: bool,
    array_any: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayAnyPredicate),
) !bool {
    if (!valueEqualsAnyArrayPredicateCanStart(tokens, pos.*)) return false;

    const value_json = try value_mod.parseJsonValueAlloc(alloc, tokens, pos, params);
    var value_transferred = false;
    errdefer if (!value_transferred) alloc.free(value_json);
    try parser.expectToken(tokens, pos, .eq);
    if (!matchAnyOrSomeKeyword(tokens, pos)) return error.UnsupportedSqlShape;
    try parser.expectToken(tokens, pos, .lparen);
    const parsed_field = try parseRowExpressionFieldOwnedAlloc(
        alloc,
        tokens,
        pos,
        schema,
        field_expression_qualifiers,
        returning_expression_qualifiers,
        defer_row_expression_field_validation,
    );
    defer alloc.free(parsed_field);
    const field = try binder.normalizeRowExpressionFieldAlloc(
        alloc,
        schema,
        parsed_field,
        field_expression_qualifiers,
        returning_expression_qualifiers,
        defer_row_expression_field_validation,
    );
    var field_transferred = false;
    errdefer if (!field_transferred) alloc.free(field);
    const column = binder.relationalColumnForField(schema, field, .array) orelse return error.InvalidSqlCatalog;
    try value_mod.validateSqlArrayElementValueJson(alloc, column, value_json);
    try parser.expectToken(tokens, pos, .rparen);
    try array_any.append(alloc, .{
        .field = field,
        .value_json = value_json,
    });
    field_transferred = true;
    value_transferred = true;
    return true;
}

pub fn parseScalarNotWhereAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    params: []const value_mod.SqlValue,
    schema: runtime_schema.TableSchema,
    field_expression_qualifiers: []const []const u8,
    returning_expression_qualifiers: []const []const u8,
    defer_row_expression_field_validation: bool,
    not_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsPredicateGroup),
    realtime_ns: u64,
    generated_expression_ast: ?*const generated_parser.GeneratedSqlExpressionAst,
) !void {
    if (generated_expression_ast) |expression| {
        if (expression.kind != .logical_not) return error.UnsupportedSqlShape;
    }
    try parser.expectKeyword(tokens, pos, "not");
    try parser.expectToken(tokens, pos, .lparen);
    while (true) {
        var branch = std.ArrayListUnmanaged(runtime_schema.RelationalCheck).empty;
        errdefer {
            freeRelationalChecks(alloc, branch.items);
            branch.deinit(alloc);
        }
        while (true) {
            const generated_condition_expression = try generatedPredicateExpressionAtStart(pos.*, generated_expression_ast);
            const predicate = try parseScalarWherePredicateAlloc(
                alloc,
                tokens,
                pos,
                schema,
                field_expression_qualifiers,
                returning_expression_qualifiers,
                defer_row_expression_field_validation,
                params,
                realtime_ns,
                generated_condition_expression,
            );
            var predicate_transferred = false;
            errdefer if (!predicate_transferred) plan_mod.freeRelationalCheck(alloc, predicate);
            try branch.append(alloc, predicate);
            predicate_transferred = true;
            if (!parser.matchKeyword(tokens, pos, "and")) break;
        }
        if (branch.items.len == 0) return error.UnsupportedSqlShape;

        const predicates = try branch.toOwnedSlice(alloc);
        branch = .empty;
        var predicates_transferred = false;
        errdefer if (!predicates_transferred) {
            freeRelationalChecks(alloc, predicates);
            if (predicates.len > 0) alloc.free(predicates);
        };
        try not_predicates.append(alloc, .{ .predicates = predicates });
        predicates_transferred = true;
        branch.deinit(alloc);

        if (!parser.matchKeyword(tokens, pos, "or")) break;
    }
    try parser.expectToken(tokens, pos, .rparen);
}

pub fn parseScalarOrWhereAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    params: []const value_mod.SqlValue,
    schema: runtime_schema.TableSchema,
    field_expression_qualifiers: []const []const u8,
    returning_expression_qualifiers: []const []const u8,
    defer_row_expression_field_validation: bool,
    or_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsPredicateGroup),
    realtime_ns: u64,
    generated_expression_ast: ?*const generated_parser.GeneratedSqlExpressionAst,
) !void {
    while (true) {
        const parenthesized = parser.matchToken(tokens, pos, .lparen) != null;
        var branches = std.ArrayListUnmanaged(ScalarOrCheckBranch).empty;
        errdefer freeScalarOrCheckBranches(alloc, &branches);
        try branches.append(alloc, .empty);

        while (true) {
            const generated_condition_expression = try generatedPredicateExpressionAtStart(pos.*, generated_expression_ast);
            if (try parseScalarBooleanIsNotIntoOrBranchesAlloc(
                alloc,
                tokens,
                pos,
                schema,
                field_expression_qualifiers,
                returning_expression_qualifiers,
                defer_row_expression_field_validation,
                &branches,
                generated_condition_expression,
            )) {
                // Expanded as native OR branches.
            } else if (!(try parseScalarWhereSetIntoOrBranchesAlloc(
                alloc,
                tokens,
                pos,
                params,
                schema,
                field_expression_qualifiers,
                returning_expression_qualifiers,
                defer_row_expression_field_validation,
                &branches,
                generated_condition_expression,
            ))) {
                const predicate = try parseScalarWherePredicateAlloc(
                    alloc,
                    tokens,
                    pos,
                    schema,
                    field_expression_qualifiers,
                    returning_expression_qualifiers,
                    defer_row_expression_field_validation,
                    params,
                    realtime_ns,
                    generated_condition_expression,
                );
                defer plan_mod.freeRelationalCheck(alloc, predicate);
                try appendRelationalCheckCloneToScalarOrBranches(alloc, &branches, predicate);
            }
            if (!parser.matchKeyword(tokens, pos, "and")) break;
        }

        if (branches.items.len == 0) return error.UnsupportedSqlShape;
        if (parenthesized) try parser.expectToken(tokens, pos, .rparen);
        for (branches.items) |*branch| {
            if (branch.items.len == 0) return error.UnsupportedSqlShape;
            const predicates = try branch.toOwnedSlice(alloc);
            branch.* = .empty;
            var predicates_transferred = false;
            errdefer if (!predicates_transferred) {
                freeRelationalChecks(alloc, predicates);
                if (predicates.len > 0) alloc.free(predicates);
            };
            try or_predicates.append(alloc, .{ .predicates = predicates });
            predicates_transferred = true;
        }
        branches.deinit(alloc);

        if (!parser.matchKeyword(tokens, pos, "or")) break;
    }
}

pub fn parseScalarBooleanIsNotIntoOrBranchesAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    schema: runtime_schema.TableSchema,
    field_expression_qualifiers: []const []const u8,
    returning_expression_qualifiers: []const []const u8,
    defer_row_expression_field_validation: bool,
    branches: *std.ArrayListUnmanaged(ScalarOrCheckBranch),
    generated_expression_ast: ?*const generated_parser.GeneratedSqlExpressionAst,
) !bool {
    const saved_pos = pos.*;
    const parsed_field = parseRowExpressionFieldOwnedAlloc(
        alloc,
        tokens,
        pos,
        schema,
        field_expression_qualifiers,
        returning_expression_qualifiers,
        defer_row_expression_field_validation,
    ) catch |err| {
        pos.* = saved_pos;
        return switch (err) {
            error.UnsupportedSqlShape => false,
            else => err,
        };
    };
    defer alloc.free(parsed_field);
    if (!parser.matchKeywordTag(tokens, pos, .is)) {
        pos.* = saved_pos;
        return false;
    }
    if (!parser.matchKeywordTag(tokens, pos, .not)) {
        pos.* = saved_pos;
        return false;
    }
    if (!(parser.peekKeywordTag(tokens, pos.*, .true) or parser.peekKeywordTag(tokens, pos.*, .false))) {
        pos.* = saved_pos;
        return false;
    }

    const field = try binder.normalizeRowExpressionFieldAlloc(
        alloc,
        schema,
        parsed_field,
        field_expression_qualifiers,
        returning_expression_qualifiers,
        defer_row_expression_field_validation,
    );
    defer alloc.free(field);
    const column = binder.relationalColumnForField(schema, field, .boolean) orelse return error.InvalidSqlCatalog;
    const value = (try value_mod.parseSqlBooleanIsValue(tokens, pos, column)) orelse return error.UnsupportedSqlShape;
    const expected_kind: generated_parser.GeneratedSqlExpressionKind = if (value) .is_not_true else .is_not_false;
    try validateGeneratedExpressionPredicateKind(generated_expression_ast, expected_kind);
    try expandBooleanIsNotIntoOrBranches(alloc, branches, field, value);
    return true;
}

pub fn parseScalarWhereSetIntoOrBranchesAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    params: []const value_mod.SqlValue,
    schema: runtime_schema.TableSchema,
    field_expression_qualifiers: []const []const u8,
    returning_expression_qualifiers: []const []const u8,
    defer_row_expression_field_validation: bool,
    branches: *std.ArrayListUnmanaged(ScalarOrCheckBranch),
    generated_expression_ast: ?*const generated_parser.GeneratedSqlExpressionAst,
) !bool {
    if (!peekSimpleScalarSetPredicate(tokens, pos.*)) return false;

    const field = try parseRowExpressionFieldOwnedAlloc(
        alloc,
        tokens,
        pos,
        schema,
        field_expression_qualifiers,
        returning_expression_qualifiers,
        defer_row_expression_field_validation,
    );
    defer alloc.free(field);
    const column = binder.relationalColumnForField(schema, field, null) orelse return error.InvalidSqlCatalog;
    if (column.field_type == .array or column.field_type == .json) return error.UnsupportedSqlShape;

    if (parser.matchKeyword(tokens, pos, "not")) {
        try parser.expectKeyword(tokens, pos, "in");
        try validateGeneratedExpressionPredicateKind(generated_expression_ast, .not_in_list);
        const values_json = try value_mod.parseSqlInValuesJsonAlloc(alloc, tokens, pos, params);
        defer alloc.free(values_json);
        try appendScalarValuesJsonToOrBranches(alloc, branches, field, values_json, .ne);
        return true;
    }
    if (parser.matchKeyword(tokens, pos, "in")) {
        try validateGeneratedExpressionPredicateKind(generated_expression_ast, .in_list);
        const values_json = try value_mod.parseSqlInValuesJsonAlloc(alloc, tokens, pos, params);
        defer alloc.free(values_json);
        try expandScalarValuesJsonIntoOrBranches(alloc, branches, field, values_json, .eq);
        return true;
    }

    const op = try parseComparisonOp(tokens, pos);
    if (op == .eq and matchAnyOrSomeKeyword(tokens, pos)) {
        try validateGeneratedQuantifiedPredicateExpression(generated_expression_ast);
        try parser.expectToken(tokens, pos, .lparen);
        const values_json = try value_mod.parseJsonArrayValueAlloc(alloc, tokens, pos, params);
        defer alloc.free(values_json);
        try parser.expectToken(tokens, pos, .rparen);
        try expandScalarValuesJsonIntoOrBranches(alloc, branches, field, values_json, .eq);
        return true;
    }
    if (op == .ne and matchAnyOrSomeKeyword(tokens, pos)) {
        try validateGeneratedQuantifiedPredicateExpression(generated_expression_ast);
        try parser.expectToken(tokens, pos, .lparen);
        const values_json = try value_mod.parseJsonArrayValueAlloc(alloc, tokens, pos, params);
        defer alloc.free(values_json);
        try parser.expectToken(tokens, pos, .rparen);
        try expandScalarValuesJsonIntoOrBranches(alloc, branches, field, values_json, .ne);
        return true;
    }
    if (op == .eq and parser.matchKeyword(tokens, pos, "all")) {
        try validateGeneratedQuantifiedPredicateExpression(generated_expression_ast);
        try parser.expectToken(tokens, pos, .lparen);
        const values_json = try value_mod.parseJsonArrayValueAlloc(alloc, tokens, pos, params);
        defer alloc.free(values_json);
        try parser.expectToken(tokens, pos, .rparen);
        try appendScalarValuesJsonToOrBranches(alloc, branches, field, values_json, .eq);
        return true;
    }
    if (op == .ne and parser.matchKeyword(tokens, pos, "all")) {
        try validateGeneratedQuantifiedPredicateExpression(generated_expression_ast);
        try parser.expectToken(tokens, pos, .lparen);
        const values_json = try value_mod.parseJsonArrayValueAlloc(alloc, tokens, pos, params);
        defer alloc.free(values_json);
        try parser.expectToken(tokens, pos, .rparen);
        try appendScalarValuesJsonToOrBranches(alloc, branches, field, values_json, .ne);
        return true;
    }
    return error.UnsupportedSqlShape;
}

pub fn parseExpressionNotWhereAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    params: []const value_mod.SqlValue,
    type_context: RowExpressionTypeContext,
    defer_row_expression_field_validation: bool,
    expression_not_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
    hooks: ExpressionWhereConditionAlternativesParserOptions,
) !void {
    return try parseExpressionNotWhereWithGeneratedAlloc(
        alloc,
        tokens,
        pos,
        params,
        type_context,
        defer_row_expression_field_validation,
        expression_not_predicates,
        hooks,
        null,
    );
}

pub fn parseExpressionNotWhereWithGeneratedAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    params: []const value_mod.SqlValue,
    type_context: RowExpressionTypeContext,
    defer_row_expression_field_validation: bool,
    expression_not_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
    hooks: ExpressionWhereConditionAlternativesParserOptions,
    generated_expression_ast: ?*const generated_parser.GeneratedSqlExpressionAst,
) !void {
    if (generated_expression_ast) |expression| {
        if (expression.kind != .logical_not) return error.UnsupportedSqlShape;
    }
    try parser.expectKeyword(tokens, pos, "not");
    try parser.expectToken(tokens, pos, .lparen);
    while (true) {
        var groups = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
        var groups_transferred = false;
        defer groups.deinit(alloc);
        errdefer {
            if (!groups_transferred) freeExpressionPredicateGroups(alloc, groups.items);
        }
        try groups.append(alloc, .{ .conditions = &.{} });

        while (true) {
            var alternatives = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
            defer alternatives.deinit(alloc);
            errdefer freeExpressionPredicateGroups(alloc, alternatives.items);
            var hooks_with_generated = hooks;
            if (generated_expression_ast != null) {
                hooks_with_generated.generated_expression_ast = try generatedPredicateExpressionAtStart(pos.*, generated_expression_ast);
            }
            try parseExpressionWhereConditionAlternativesAlloc(
                alloc,
                tokens,
                pos,
                params,
                type_context,
                defer_row_expression_field_validation,
                &alternatives,
                hooks_with_generated,
            );
            try andExpressionPredicateAlternatives(alloc, &groups, alternatives.items);
            freeExpressionPredicateGroups(alloc, alternatives.items);
            if (!parser.matchKeyword(tokens, pos, "and")) break;
        }
        if (groups.items.len == 0) return error.UnsupportedSqlShape;
        try expression_not_predicates.appendSlice(alloc, groups.items);
        groups_transferred = true;

        if (!parser.matchKeyword(tokens, pos, "or")) break;
    }
    try parser.expectToken(tokens, pos, .rparen);
}

pub fn parseExpressionOrWhereAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    params: []const value_mod.SqlValue,
    type_context: RowExpressionTypeContext,
    defer_row_expression_field_validation: bool,
    expression_or_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
