pub fn buildBooleanExpressionProjectionFromOwnedExpressionAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    type_context: RowExpressionTypeContext,
    expression: db_mod.types.RelationalRowsExpression,
