pub fn parseAggregateHavingAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    params: []const value_mod.SqlValue,
    schema: runtime_schema.TableSchema,
    type_context: RowExpressionTypeContext,
    predicates: *std.ArrayListUnmanaged(runtime_schema.RelationalCheck),
    expressions: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition),
    any_groups: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
    not_groups: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
    group_fields: []const []const u8,
    group_expressions: []const db_mod.types.RelationalRowsExpressionProjection,
    aggregations: []const db_mod.types.RelationalRowsAggregateSpec,
    output_field_options: AggregateOutputFieldParserOptions,
    field_condition_options: AggregateOutputFieldExpressionConditionParserOptions,
    expression_condition_options: AggregateOutputExpressionConditionParserOptions,
    bare_boolean_options: BareBooleanAggregateHavingExpressionParserOptions,
    generated_expression_ast: ?*const generated_parser.GeneratedSqlExpressionAst,
) !void {
    if (try canParseBareBooleanAggregateHavingExpression(alloc, tokens, pos.*, schema, type_context, group_fields, group_expressions, aggregations)) {
        try parseBareBooleanAggregateHavingExpression(alloc, tokens, pos, schema, type_context, expressions, group_fields, group_expressions, aggregations, bare_boolean_options);
        return;
    }
    if (parser.hasTopLevelOrBeforeTailToken(tokens, pos.*, sqlWhereTailClauseKeywordToken) or aggregateHavingHasBooleanIsNot(tokens, pos.*)) {
        try parseAggregateHavingOrGroupsAlloc(alloc, tokens, pos, schema, type_context, any_groups, group_fields, group_expressions, aggregations, field_condition_options, expression_condition_options, generated_expression_ast);
        return;
    }
    while (true) {
        if (canParseAggregateHavingNot(tokens, pos.*)) {
            const generated_condition_expression = try generatedPredicateExpressionAtStart(pos.*, generated_expression_ast);
            try parseAggregateHavingNotGroupAlloc(alloc, tokens, pos, schema, type_context, not_groups, group_fields, group_expressions, aggregations, field_condition_options, expression_condition_options, generated_condition_expression);
        } else if (value_mod.matchStandaloneSqlBooleanLiteral(tokens, pos)) |enabled| {
            if (!enabled) try appendBooleanConstantExpressionCondition(alloc, expressions, false);
        } else if (peekAggregateHavingExpression(tokens, pos.*)) {
            var expression_options_with_generated = expression_condition_options;
            expression_options_with_generated.generated_expression_ast = try generatedPredicateExpressionAtStart(pos.*, generated_expression_ast);
            const condition = try parseAggregateOutputExpressionConditionAlloc(alloc, tokens, pos, schema, type_context, group_fields, group_expressions, aggregations, expression_options_with_generated);
            var condition_transferred = false;
            errdefer if (!condition_transferred) freeExpressionCondition(alloc, condition);
            try expressions.append(alloc, condition);
            condition_transferred = true;
        } else {
            const generated_condition_expression = try generatedPredicateExpressionAtStart(pos.*, generated_expression_ast);
            const field = try parseAggregateOutputFieldAlloc(alloc, tokens, pos, group_fields, group_expressions, aggregations, output_field_options);
            var field_transferred = false;
            errdefer if (!field_transferred) alloc.free(field);
            if (!aggregateOutputFieldIsUnique(group_fields, group_expressions, aggregations, field)) return error.UnsupportedSqlShape;
            const column = try aggregateOutputColumnForFieldAlloc(alloc, schema, type_context, group_fields, group_expressions, aggregations, field);
            const op: runtime_schema.RelationalCheckOp = if (try parseExpressionIsTailIf(tokens, pos, .{
                .allow_boolean_unknown = true,
                .allow_boolean_literal = true,
            })) |is_tail| blk: {
                switch (is_tail.kind) {
                    .distinct_comparison, .null_test => {},
                    .boolean_unknown => {
                        try validateGeneratedExpressionPredicateKind(generated_condition_expression, generatedIsTailExpressionKind(is_tail));
                        if (column.field_type != .boolean) return error.InvalidSqlCatalog;
                        break :blk is_tail.op;
                    },
                    .boolean_literal => {
                        try validateGeneratedExpressionPredicateKind(generated_condition_expression, generatedIsTailExpressionKind(is_tail));
                        if (column.field_type != .boolean) return error.InvalidSqlCatalog;
                        const value_json = try alloc.dupe(u8, value_mod.booleanJson(is_tail.boolean_value));
                        var value_transferred = false;
                        errdefer if (!value_transferred) alloc.free(value_json);
                        try predicates.append(alloc, .{
                            .name = "",
                            .field = field,
                            .op = .eq,
                            .value_json = value_json,
                        });
                        field_transferred = true;
                        value_transferred = true;
                        if (!parser.matchKeyword(tokens, pos, "and")) break;
                        continue;
                    },
                }
                break :blk is_tail.op;
            } else try parseComparisonOp(tokens, pos);
            try validateGeneratedExpressionPredicateKind(generated_condition_expression, generatedComparisonExpressionKindForOp(op));
            const value_json = switch (op) {
                .is_null, .is_not_null => null,
                else => try value_mod.parseJsonValueAlloc(alloc, tokens, pos, params),
            };
            var value_transferred = false;
            errdefer if (!value_transferred) if (value_json) |json| alloc.free(json);
            try predicates.append(alloc, .{
                .name = "",
                .field = field,
                .op = op,
                .value_json = value_json,
            });
            field_transferred = true;
            value_transferred = true;
        }
        if (!parser.matchKeyword(tokens, pos, "and")) break;
    }
}

pub fn aggregateHavingHasBooleanIsNot(tokens: []const Token, pos: usize) bool {
    var depth: usize = 0;
    var i = pos;
    while (i + 2 < tokens.len) : (i += 1) {
        const token = tokens[i];
        switch (token.kind) {
            .lparen => depth += 1,
            .rparen => {
                if (depth == 0) return false;
                depth -= 1;
            },
            .identifier => {
                if (depth == 0 and (token.matchesKeywordTag(.order) or
                    token.matchesKeywordTag(.limit) or
                    token.matchesKeywordTag(.offset) or
                    token.matchesKeywordTag(.fetch)))
                {
                    return false;
                }
                if (token.matchesKeywordTag(.is) and
                    tokens[i + 1].matchesKeywordTag(.not) and
                    (tokens[i + 2].matchesKeywordTag(.true) or
                        tokens[i + 2].matchesKeywordTag(.false)))
                {
                    return true;
                }
            },
            else => {},
        }
    }
    return false;
}

pub fn canParseAggregateHavingNot(tokens: []const Token, pos: usize) bool {
    return parser.peekKeywordTag(tokens, pos, .not) and pos + 1 < tokens.len and tokens[pos + 1].kind == .lparen;
}

pub fn matchBooleanGroupOpen(tokens: []const Token, pos: *usize) bool {
    if (!parser.peekKind(tokens, pos.*, .lparen)) return false;
    if (peekParenthesizedExpressionCondition(tokens, pos.*)) return false;
    _ = parser.matchToken(tokens, pos, .lparen) orelse unreachable;
    return true;
}

pub fn peekParenthesizedExpressionCondition(tokens: []const Token, pos: usize) bool {
    if (!parser.peekKind(tokens, pos, .lparen)) return false;
    var depth: usize = 0;
    var i = pos;
    while (i < tokens.len) : (i += 1) {
        const token = tokens[i];
        switch (token.kind) {
            .lparen => depth += 1,
            .rparen => {
                if (depth == 0) return false;
                depth -= 1;
                if (depth == 0) {
                    if (i + 1 >= tokens.len) return false;
                    const next = tokens[i + 1];
                    return switch (next.kind) {
                        .eq, .neq, .gt, .gte, .lt, .lte => true,
                        .identifier => next.matchesKeywordTag(.is),
                        else => false,
                    };
                }
            },
            else => {},
        }
    }
    return false;
}

pub fn peekStandaloneAggregateGroupIdentifier(tokens: []const Token, pos: usize) bool {
    if (!parser.peekKind(tokens, pos, .identifier)) return false;
    if (pos + 1 >= tokens.len) return true;
    return switch (tokens[pos + 1].kind) {
        .lparen, .arrow_json, .arrow_text, .path_arrow_json, .path_arrow_text, .plus, .minus, .star, .slash, .percent, .pipe_concat => false,
        else => true,
    };
}

pub fn appendAggregateGroupByFieldOrAlias(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    group_by: *std.ArrayListUnmanaged([]const u8),
    group_expressions: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionProjection),
    select: plan_mod.AggregateSelectList,
    raw_field: []const u8,
    field_expression_qualifiers: []const []const u8,
    returning_expression_qualifiers: []const []const u8,
    defer_row_expression_field_validation: bool,
) !void {
    var raw_owned = true;
    defer if (raw_owned) alloc.free(raw_field);

    const normalized_field: ?[]const u8 = binder.normalizeRowExpressionFieldAlloc(alloc, schema, raw_field, field_expression_qualifiers, returning_expression_qualifiers, defer_row_expression_field_validation) catch |err| switch (err) {
        error.InvalidSqlCatalog => null,
        else => return err,
    };
    if (normalized_field) |field| {
        var field_owned = true;
        errdefer if (field_owned) alloc.free(field);
        if (binder.relationalColumnForField(schema, field, null) != null) {
            try group_by.append(alloc, field);
            field_owned = false;
            raw_owned = false;
            alloc.free(raw_field);
            return;
        }
        alloc.free(field);
        field_owned = false;
    }

    for (select.group_expressions) |projection| {
        if (std.mem.eql(u8, projection.output, raw_field)) {
            try group_expressions.append(alloc, try plan_mod.cloneExpressionProjection(alloc, projection));
            return;
        }
    }
    return error.InvalidSqlCatalog;
}

pub fn appendAggregateGroupByOrdinal(
    alloc: std.mem.Allocator,
    group_by: *std.ArrayListUnmanaged([]const u8),
    group_expressions: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionProjection),
    select: plan_mod.AggregateSelectList,
    ordinal: u32,
) !void {
    if (ordinal == 0) return error.UnsupportedSqlShape;
    const index: usize = @intCast(ordinal - 1);
    if (index >= select.outputs.len) return error.UnsupportedSqlShape;
    const output = select.outputs[index];
    switch (output.kind) {
        .group_field => try group_by.append(alloc, try alloc.dupe(u8, select.group_fields[output.index])),
        .group_expression => try group_expressions.append(alloc, try plan_mod.cloneExpressionProjection(alloc, select.group_expressions[output.index])),
        .aggregation => return error.UnsupportedSqlShape,
    }
}

pub fn parseAggregateGroupByAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    params: []const value_mod.SqlValue,
    schema: runtime_schema.TableSchema,
    function_bindings: SqlFunctionBindings,
    type_context: RowExpressionTypeContext,
    field_expression_qualifiers: []const []const u8,
    returning_expression_qualifiers: []const []const u8,
    defer_row_expression_field_validation: bool,
    field_source: db_mod.types.RelationalRowsExpressionFieldSource,
    group_by: *std.ArrayListUnmanaged([]const u8),
    group_expressions: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionProjection),
    select: plan_mod.AggregateSelectList,
    select_item_options: SelectItemParserOptions,
    generated_read_ast: ?*const generated_parser.GeneratedSqlReadAst,
) !void {
    while (true) {
        const item_start = pos.*;
        const generated_expression = try generatedGroupExpressionAtItemStart(item_start, generated_read_ast);
        if (generated_expression == null and generated_read_ast != null) return error.UnsupportedSqlShape;
        if (parser.matchToken(tokens, pos, .number)) |token| {
            try validateGeneratedSimpleGroupExpression(generated_expression);
            const ordinal = std.fmt.parseInt(u32, token.text, 10) catch return error.UnsupportedSqlShape;
            try appendAggregateGroupByOrdinal(alloc, group_by, group_expressions, select, ordinal);
        } else if (peekStandaloneAggregateGroupIdentifier(tokens, pos.*)) {
            try validateGeneratedSimpleGroupExpression(generated_expression);
            const raw_field = try parseRowExpressionFieldOwnedAlloc(
                alloc,
                tokens,
                pos,
                schema,
                field_expression_qualifiers,
                returning_expression_qualifiers,
                defer_row_expression_field_validation,
            );
            try appendAggregateGroupByFieldOrAlias(
                alloc,
                schema,
                group_by,
                group_expressions,
                select,
                raw_field,
                field_expression_qualifiers,
                returning_expression_qualifiers,
                defer_row_expression_field_validation,
            );
        } else {
            var item_options = select_item_options;
            item_options.generated_expression_ast = generated_expression;
            const item = try parseSelectItemAlloc(
                alloc,
                tokens,
                pos,
                params,
                schema,
                function_bindings,
                field_expression_qualifiers,
                returning_expression_qualifiers,
                defer_row_expression_field_validation,
                field_source,
                type_context,
                item_options,
            );
            var item_transferred = false;
            errdefer if (!item_transferred) plan_mod.freeSelectItem(alloc, item);
            switch (item) {
                .field => |field| try group_by.append(alloc, field),
                .expression => |projection| try group_expressions.append(alloc, projection),
                else => return error.UnsupportedSqlShape,
            }
            item_transferred = true;
        }
        if (parser.matchToken(tokens, pos, .comma) == null) break;
    }
}

pub fn parseAggregateOrderByAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    schema: runtime_schema.TableSchema,
    type_context: RowExpressionTypeContext,
    order_by: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsQueryOrder),
    group_fields: []const []const u8,
    group_expressions: []const db_mod.types.RelationalRowsExpressionProjection,
    aggregations: []const db_mod.types.RelationalRowsAggregateSpec,
    field_options: AggregateOutputFieldParserOptions,
    order_expression_options: OutputOrderExpressionParserOptions,
) !void {
    while (true) {
        const item_start = pos.*;
        const generated_expression = try generatedOrderExpressionAtItemStart(item_start, order_expression_options.generated_read_ast);
        if (generated_expression == null and order_expression_options.generated_read_ast != null) return error.UnsupportedSqlShape;
        var item_order_expression_options = order_expression_options;
        item_order_expression_options.order_expression_hooks.generated_expression_ast = generated_expression;
        var order = if (parser.matchToken(tokens, pos, .number)) |token| blk: {
            try validateGeneratedSimpleOrderExpression(generated_expression);
            const ordinal = std.fmt.parseInt(u32, token.text, 10) catch return error.UnsupportedSqlShape;
            break :blk db_mod.types.RelationalRowsQueryOrder{ .field = try aggregateOutputFieldByOrdinalAlloc(alloc, group_fields, group_expressions, aggregations, ordinal) };
        } else if (peekAggregateOutputOrderExpression(tokens, pos.*)) blk: {
            break :blk try parseAggregateOutputOrderExpressionAlloc(alloc, tokens, pos, schema, type_context, group_fields, group_expressions, aggregations, item_order_expression_options);
        } else blk: {
            try validateGeneratedSimpleOrderExpression(generated_expression);
            const field = try parseAggregateOutputFieldAlloc(alloc, tokens, pos, group_fields, group_expressions, aggregations, field_options);
            if (!aggregateOutputFieldIsUnique(group_fields, group_expressions, aggregations, field)) {
                alloc.free(field);
                return error.UnsupportedSqlShape;
            }
            break :blk db_mod.types.RelationalRowsQueryOrder{ .field = field };
        };
        var order_transferred = false;
        errdefer if (!order_transferred) {
            if (order.field.len > 0) alloc.free(order.field);
            if (order.expression) |expression| freeExpression(alloc, expression);
        };
        const explicit_nulls_first = try parseOrderModifiers(tokens, pos, &order);
        try appendOrderWithNullPlacement(alloc, order_by, order, explicit_nulls_first);
        order_transferred = true;
        if (parser.matchToken(tokens, pos, .comma) == null) break;
    }
}

pub fn parseWindowOutputOrderByAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    schema: runtime_schema.TableSchema,
    type_context: RowExpressionTypeContext,
    order_by: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsQueryOrder),
    select: plan_mod.WindowSelectList,
    options: OutputOrderExpressionParserOptions,
) !void {
    while (true) {
        const item_start = pos.*;
        const generated_expression = try generatedOrderExpressionAtItemStart(item_start, options.generated_read_ast);
        if (generated_expression == null and options.generated_read_ast != null) return error.UnsupportedSqlShape;
        var item_options = options;
        item_options.order_expression_hooks.generated_expression_ast = generated_expression;
        var order = if (parser.matchToken(tokens, pos, .number)) |token| blk: {
            try validateGeneratedSimpleOrderExpression(generated_expression);
            const ordinal = std.fmt.parseInt(u32, token.text, 10) catch return error.UnsupportedSqlShape;
            const field = try windowOutputFieldByOrdinalAlloc(alloc, select, ordinal);
            if (!windowOutputFieldIsUnique(select.fields, select.windows, field)) {
                alloc.free(field);
                return error.UnsupportedSqlShape;
            }
            break :blk db_mod.types.RelationalRowsQueryOrder{ .field = field };
        } else if (peekWindowOutputOrderExpression(tokens, pos.*)) blk: {
            break :blk try parseWindowOutputOrderExpressionAlloc(alloc, tokens, pos, schema, type_context, select, item_options);
        } else blk: {
            try validateGeneratedSimpleOrderExpression(generated_expression);
            const field = try parseIdentifierOwnedAlloc(alloc, tokens, pos);
            if (!windowOutputFieldIsUnique(select.fields, select.windows, field)) {
                alloc.free(field);
                return error.UnsupportedSqlShape;
            }
            break :blk db_mod.types.RelationalRowsQueryOrder{ .field = field };
        };
        var order_transferred = false;
        errdefer if (!order_transferred) {
            if (order.field.len > 0) alloc.free(order.field);
            if (order.expression) |expression| freeExpression(alloc, expression);
        };
        const explicit_nulls_first = try parseOrderModifiers(tokens, pos, &order);
        try appendOrderWithNullPlacement(alloc, order_by, order, explicit_nulls_first);
        order_transferred = true;
        if (parser.matchToken(tokens, pos, .comma) == null) break;
    }
}

pub fn parseJoinOrderByAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    schema: runtime_schema.TableSchema,
    order_by: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsQueryOrder),
    select: []const db_mod.types.RelationalRowsJoinProjection,
    options: OutputOrderExpressionParserOptions,
) !void {
    while (true) {
        const item_start = pos.*;
        const generated_expression = try generatedOrderExpressionAtItemStart(item_start, options.generated_read_ast);
        if (generated_expression == null and options.generated_read_ast != null) return error.UnsupportedSqlShape;
        var item_options = options;
        item_options.order_expression_hooks.generated_expression_ast = generated_expression;
        var order = if (parser.matchToken(tokens, pos, .number)) |token| blk: {
            try validateGeneratedSimpleOrderExpression(generated_expression);
            const ordinal = std.fmt.parseInt(u32, token.text, 10) catch return error.UnsupportedSqlShape;
            const field = try joinOutputFieldByOrdinalAlloc(alloc, select, ordinal);
            if (!joinProjectionOutputIsUnique(select, field)) {
                alloc.free(field);
                return error.UnsupportedSqlShape;
            }
            break :blk db_mod.types.RelationalRowsQueryOrder{ .field = field };
        } else if (peekAggregateOutputOrderExpression(tokens, pos.*)) blk: {
            break :blk try parseJoinOutputOrderExpressionAlloc(alloc, tokens, pos, schema, select, item_options);
        } else blk: {
            try validateGeneratedSimpleOrderExpression(generated_expression);
            const field = try parseIdentifierOwnedAlloc(alloc, tokens, pos);
            if (!joinProjectionOutputIsUnique(select, field)) {
                alloc.free(field);
                return error.UnsupportedSqlShape;
            }
            break :blk db_mod.types.RelationalRowsQueryOrder{ .field = field };
        };
        var order_transferred = false;
        errdefer if (!order_transferred) {
            if (order.field.len > 0) alloc.free(order.field);
            if (order.expression) |expression| freeExpression(alloc, expression);
        };
        const explicit_nulls_first = try parseOrderModifiers(tokens, pos, &order);
        try appendOrderWithNullPlacement(alloc, order_by, order, explicit_nulls_first);
        order_transferred = true;
        if (parser.matchToken(tokens, pos, .comma) == null) break;
    }
}

pub fn parseTargetOrderByAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    schema: runtime_schema.TableSchema,
    order_by: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsQueryOrder),
    target_alias: []const u8,
) !void {
    while (true) {
        const field = if (parser.peekKind(tokens, pos.*, .identifier) and identifierContainsQualifier(tokens[pos.*].text)) blk: {
            const source = try plan_mod.parseQualifiedFieldAlloc(alloc, tokens, pos);
            defer plan_mod.freeQualifiedField(alloc, source);
            if (!std.mem.eql(u8, source.qualifier, target_alias)) return error.UnsupportedSqlShape;
            break :blk try alloc.dupe(u8, source.field);
        } else try parseIdentifierOwnedAlloc(alloc, tokens, pos);
        var field_transferred = false;
        errdefer if (!field_transferred) alloc.free(field);
        if (binder.relationalColumnForField(schema, field, null) == null) return error.InvalidSqlCatalog;
        var order: db_mod.types.RelationalRowsQueryOrder = .{ .field = field };
        const explicit_nulls_first = try parseOrderModifiers(tokens, pos, &order);
        try appendOrderWithNullPlacement(alloc, order_by, order, explicit_nulls_first);
        field_transferred = true;
        if (parser.matchToken(tokens, pos, .comma) == null) break;
    }
}

pub fn expressionOrderCount(order_by: []const db_mod.types.RelationalRowsQueryOrder) usize {
    var count: usize = 0;
    for (order_by) |order| {
        if (order.expression != null) count += 1;
    }
    return count;
}

pub fn validateDistinctOnOrder(
    distinct_on: []const db_mod.types.RelationalRowsExpression,
    order_by: []const db_mod.types.RelationalRowsQueryOrder,
) !void {
    if (order_by.len < distinct_on.len) return error.UnsupportedSqlShape;
    for (distinct_on, 0..) |expression, i| {
        const order = order_by[i];
        if (order.expression) |order_expression| {
            if (!relationalRowsExpressionEqual(order_expression, expression)) return error.UnsupportedSqlShape;
        } else {
            if (expression.kind != .field or expression.field_source != .row or !std.mem.eql(u8, order.field, expression.field)) return error.UnsupportedSqlShape;
        }
    }
}

pub fn parseOptionalDistinctOnAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    type_context: RowExpressionTypeContext,
    row_expression_hooks: RowExpressionParserHooks,
    arithmetic_hooks: ArithmeticExpressionParserHooks,
    variadic_hooks: VariadicRowExpressionParserHooks,
) ![]const db_mod.types.RelationalRowsExpression {
    if (!parser.matchKeyword(tokens, pos, "distinct")) return &.{};
    if (!parser.matchKeyword(tokens, pos, "on")) return error.UnsupportedSqlShape;
    try parser.expectToken(tokens, pos, .lparen);
    var expressions = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpression).empty;
    errdefer {
        freeExpressionSlice(alloc, expressions.items);
        expressions.deinit(alloc);
    }
    while (true) {
        const expression = try parseRowExpressionAlloc(
            alloc,
            tokens,
            pos,
            type_context,
            row_expression_hooks,
            arithmetic_hooks,
            variadic_hooks,
        );
        var expression_transferred = false;
        errdefer if (!expression_transferred) freeExpression(alloc, expression);
        _ = try type_context.rowExpressionOutputType(expression);
        try expressions.append(alloc, expression);
        expression_transferred = true;
        if (parser.matchToken(tokens, pos, .comma) == null) break;
    }
    try parser.expectToken(tokens, pos, .rparen);
    if (expressions.items.len == 0) return error.UnsupportedSqlShape;
    return try expressions.toOwnedSlice(alloc);
}

pub fn parseOptionalSystemTimeAsOfSequence(tokens: []const Token, pos: *usize) !?u64 {
    const checkpoint = pos.*;
    if (!parser.matchKeyword(tokens, pos, "for")) return null;
    if (!parser.matchKeyword(tokens, pos, "system_time")) {
        pos.* = checkpoint;
        return null;
    }
    try parser.expectKeyword(tokens, pos, "as");
    try parser.expectKeyword(tokens, pos, "of");
    const token = parser.matchToken(tokens, pos, .number) orelse return error.UnsupportedSqlShape;
    if (std.mem.indexOfAny(u8, token.text, ".eE+-") != null) return error.UnsupportedSqlShape;
    return std.fmt.parseUnsigned(u64, token.text, 10) catch return error.UnsupportedSqlShape;
}

pub fn parseOrderModifiers(
    tokens: []const Token,
    pos: *usize,
    order: *db_mod.types.RelationalRowsQueryOrder,
) !?bool {
    order.direction = if (parser.matchKeyword(tokens, pos, "using"))
        try parseOrderUsingDirection(tokens, pos)
    else if (parser.matchKeyword(tokens, pos, "desc"))
        .desc
    else blk: {
        _ = parser.matchKeyword(tokens, pos, "asc");
        break :blk .asc;
    };
    return if (parser.matchKeyword(tokens, pos, "nulls")) blk: {
        if (parser.matchKeyword(tokens, pos, "first")) break :blk true;
        try parser.expectKeyword(tokens, pos, "last");
        break :blk false;
    } else null;
}

pub fn parseOrderUsingDirection(
    tokens: []const Token,
    pos: *usize,
) !db_mod.types.RelationalRowsQueryOrderDirection {
    if (parser.matchToken(tokens, pos, .lt) != null or parser.matchToken(tokens, pos, .lte) != null) return .asc;
    if (parser.matchToken(tokens, pos, .gt) != null or parser.matchToken(tokens, pos, .gte) != null) return .desc;
    return error.UnsupportedSqlShape;
}

pub fn appendOrderWithNullPlacement(
    alloc: std.mem.Allocator,
    order_by: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsQueryOrder),
    order: db_mod.types.RelationalRowsQueryOrder,
    explicit_nulls_first: ?bool,
) !void {
    if (explicit_nulls_first) |nulls_first| {
        if (order.null_test != null) return error.UnsupportedSqlShape;
        var null_order = try cloneOrderForNullTestAlloc(alloc, order);
        var null_order_transferred = false;
        errdefer if (!null_order_transferred) {
            if (null_order.field.len > 0) alloc.free(null_order.field);
            if (null_order.expression) |expression| freeExpression(alloc, expression);
        };
        null_order.direction = if (nulls_first) .desc else .asc;
        null_order.null_test = .is_null;
        try order_by.append(alloc, null_order);
        null_order_transferred = true;
    }
    try order_by.append(alloc, order);
}

pub fn cloneOrderForNullTestAlloc(
    alloc: std.mem.Allocator,
    order: db_mod.types.RelationalRowsQueryOrder,
) !db_mod.types.RelationalRowsQueryOrder {
    if (order.expression) |expression| {
        return .{ .expression = try cloneExpressionAlloc(alloc, expression) };
    }
    if (order.field.len == 0) return error.UnsupportedSqlShape;
    return .{ .field = try alloc.dupe(u8, order.field) };
}

pub fn selectOutputOrderByRefAlloc(
    alloc: std.mem.Allocator,
    select: plan_mod.SelectList,
    output: ast.SelectOutputRef,
) !db_mod.types.RelationalRowsQueryOrder {
    return switch (output.kind) {
        .field => .{ .field = try alloc.dupe(u8, select.fields[output.index]) },
        .json_extract => .{ .expression = try expressionFromJsonExtractProjectionAlloc(alloc, select.json_extract[output.index]) },
        .array_length => .{ .expression = try expressionFromArrayLengthProjectionAlloc(alloc, select.array_length[output.index]) },
        .coalesce => .{ .expression = try expressionFromCoalesceProjectionAlloc(alloc, select.coalesce[output.index]) },
        .field_alias => .{ .field = try alloc.dupe(u8, select.field_aliases[output.index].field) },
        .expression => blk: {
            const expression = select.expressions[output.index].expression;
            if (expression.kind == .field) break :blk .{ .field = try alloc.dupe(u8, expression.field) };
            break :blk .{ .expression = try cloneExpressionAlloc(alloc, expression) };
        },
    };
}

pub fn selectOutputOrderByOrdinalAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    select: plan_mod.SelectList,
    ordinal: u32,
) !db_mod.types.RelationalRowsQueryOrder {
    if (ordinal == 0) return error.UnsupportedSqlShape;
    var index: usize = @intCast(ordinal - 1);
    if (select.select_all) {
        if (index < schema.relational_columns.len) {
            return .{ .field = try alloc.dupe(u8, schema.relational_columns[index].name) };
        }
        index -= schema.relational_columns.len;
    }
    if (index >= select.outputs.len) return error.UnsupportedSqlShape;
    return try selectOutputOrderByRefAlloc(alloc, select, select.outputs[index]);
}

fn aggregateSpecNameCollision(
    name: []const u8,
    group_fields: []const []const u8,
    group_expressions: []const db_mod.types.RelationalRowsExpressionProjection,
    aggregations: []const db_mod.types.RelationalRowsAggregateSpec,
) bool {
    for (group_fields) |field| {
        if (std.mem.eql(u8, field, name)) return true;
    }
    for (group_expressions) |projection| {
        if (std.mem.eql(u8, projection.output, name)) return true;
    }
    for (aggregations) |aggregation| {
        if (std.mem.eql(u8, aggregation.name, name)) return true;
    }
    return false;
}

fn aggregateSpecNameCollidesWithGroupOutput(
    name: []const u8,
    group_fields: []const []const u8,
    group_expressions: []const db_mod.types.RelationalRowsExpressionProjection,
) bool {
    for (group_fields) |field| {
        if (std.mem.eql(u8, field, name)) return true;
    }
    for (group_expressions) |projection| {
        if (std.mem.eql(u8, projection.output, name)) return true;
    }
    return false;
}

fn allocateDisambiguatedAggregateSpecNameAlloc(
    alloc: std.mem.Allocator,
    name: []const u8,
    group_fields: []const []const u8,
    group_expressions: []const db_mod.types.RelationalRowsExpressionProjection,
    aggregations: []const db_mod.types.RelationalRowsAggregateSpec,
) !?[]const u8 {
    if (!aggregateSpecNameCollision(name, group_fields, group_expressions, aggregations)) return null;

    var suffix: usize = 2;
    while (true) : (suffix += 1) {
        const candidate = try std.fmt.allocPrint(alloc, "{s}_{d}", .{ name, suffix });
        if (!aggregateSpecNameCollision(candidate, group_fields, group_expressions, aggregations)) return candidate;
        alloc.free(candidate);
    }
}

fn aggregateSpecWithName(
    spec: db_mod.types.RelationalRowsAggregateSpec,
    name: []const u8,
) db_mod.types.RelationalRowsAggregateSpec {
    return .{
        .name = name,
        .op = spec.op,
        .field = spec.field,
        .expression = spec.expression,
        .distinct = spec.distinct,
        .distinct_max_items = spec.distinct_max_items,
        .percentile = spec.percentile,
        .percentiles = spec.percentiles,
        .percentile_max_items = spec.percentile_max_items,
        .percentile_order = spec.percentile_order,
        .array_max_items = spec.array_max_items,
        .array_order_by = spec.array_order_by,
        .string_delimiter = spec.string_delimiter,
        .filter_predicates = spec.filter_predicates,
        .filter_array_any = spec.filter_array_any,
        .filter_array_contains = spec.filter_array_contains,
        .filter_array_eq = spec.filter_array_eq,
        .filter_in_predicates = spec.filter_in_predicates,
        .filter_json_contains = spec.filter_json_contains,
        .filter_json_path_eq = spec.filter_json_path_eq,
        .filter_json_path_exists = spec.filter_json_path_exists,
        .filter_text_patterns = spec.filter_text_patterns,
        .filter_expressions = spec.filter_expressions,
        .filter_expression_array_contains = spec.filter_expression_array_contains,
        .filter_any = spec.filter_any,
        .filter_not = spec.filter_not,
    };
}

pub fn parseAggregateSelectListAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    params: []const value_mod.SqlValue,
    schema: runtime_schema.TableSchema,
    function_bindings: SqlFunctionBindings,
    type_context: RowExpressionTypeContext,
    field_expression_qualifiers: []const []const u8,
    returning_expression_qualifiers: []const []const u8,
    defer_row_expression_field_validation: bool,
    field_source: db_mod.types.RelationalRowsExpressionFieldSource,
    generated_read_ast: ?*const generated_parser.GeneratedSqlReadAst,
    aggregate_spec_options: AggregateSpecParserOptions,
    select_item_options: SelectItemParserOptions,
) !plan_mod.AggregateSelectList {
    var group_fields = std.ArrayListUnmanaged([]const u8).empty;
    errdefer {
        for (group_fields.items) |field| alloc.free(field);
        group_fields.deinit(alloc);
    }
    var group_expressions = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionProjection).empty;
    errdefer {
        for (group_expressions.items) |projection| freeExpressionProjection(alloc, projection);
        group_expressions.deinit(alloc);
    }
    var aggregations = std.ArrayListUnmanaged(db_mod.types.RelationalRowsAggregateSpec).empty;
    errdefer {
        plan_mod.freeAggregateSpecs(alloc, aggregations.items);
        aggregations.deinit(alloc);
    }
    var outputs = std.ArrayListUnmanaged(plan_mod.AggregateSelectOutputRef).empty;
    errdefer outputs.deinit(alloc);

    while (true) {
        if (nextIsAggregateFunction(tokens, pos.*)) {
            const item_start = pos.*;
            const generated_expression = try generatedProjectionExpressionAtItemStart(item_start, generated_read_ast);
            if (generated_expression == null and generated_read_ast != null) return error.UnsupportedSqlShape;
            var spec_options = aggregate_spec_options;
            spec_options.generated_expression_ast = generated_expression;
            const parsed_spec = try parseAggregateSpecAlloc(
                alloc,
                tokens,
                pos,
                params,
                schema,
                type_context,
                field_expression_qualifiers,
                returning_expression_qualifiers,
                defer_row_expression_field_validation,
                spec_options,
            );
            var parsed_spec_transferred = false;
            errdefer if (!parsed_spec_transferred) plan_mod.freeAggregateSpec(alloc, parsed_spec);
            const maybe_spec_name = try allocateDisambiguatedAggregateSpecNameAlloc(
                alloc,
                parsed_spec.name,
                group_fields.items,
                group_expressions.items,
                aggregations.items,
            );
            var spec_name_transferred = false;
            errdefer if (!spec_name_transferred) {
                if (maybe_spec_name) |spec_name| alloc.free(spec_name);
            };
            const spec = if (maybe_spec_name) |spec_name| aggregateSpecWithName(parsed_spec, spec_name) else parsed_spec;
            parsed_spec_transferred = true;
            if (maybe_spec_name != null) {
                alloc.free(parsed_spec.name);
                spec_name_transferred = true;
            }
            var spec_transferred = false;
            errdefer if (!spec_transferred) plan_mod.freeAggregateSpec(alloc, spec);
            try outputs.append(alloc, .{ .kind = .aggregation, .index = aggregations.items.len });
            try aggregations.append(alloc, spec);
            spec_transferred = true;
        } else {
            const item_start = pos.*;
            const generated_expression = try generatedProjectionExpressionAtItemStart(item_start, generated_read_ast);
            if (generated_expression == null and generated_read_ast != null) return error.UnsupportedSqlShape;
            var item_options = select_item_options;
            item_options.generated_expression_ast = generated_expression;
            const item = try parseSelectItemAlloc(
                alloc,
                tokens,
                pos,
                params,
                schema,
                function_bindings,
                field_expression_qualifiers,
                returning_expression_qualifiers,
                defer_row_expression_field_validation,
                field_source,
                type_context,
                item_options,
            );
            var item_transferred = false;
            errdefer if (!item_transferred) plan_mod.freeSelectItem(alloc, item);
            switch (item) {
                .field => |field| {
                    try outputs.append(alloc, .{ .kind = .group_field, .index = group_fields.items.len });
                    try group_fields.append(alloc, field);
                },
                .expression => |projection_value| {
                    item_transferred = true;
                    const projection = projection_value;
                    var projection_transferred = false;
                    errdefer if (!projection_transferred) freeExpressionProjection(alloc, projection);
                    try outputs.append(alloc, .{ .kind = .group_expression, .index = group_expressions.items.len });
                    try group_expressions.append(alloc, projection);
                    projection_transferred = true;
                },
                else => return error.UnsupportedSqlShape,
            }
            item_transferred = true;
        }
        if (parser.matchToken(tokens, pos, .comma) == null) break;
    }
    try validateAggregateSelectListOutputs(group_fields.items, group_expressions.items, aggregations.items);

    const owned_group_fields = try group_fields.toOwnedSlice(alloc);
    var group_fields_transferred = false;
    errdefer if (!group_fields_transferred) strings.freeStringSlice(alloc, owned_group_fields);
    const owned_group_expressions = try group_expressions.toOwnedSlice(alloc);
    var group_expressions_transferred = false;
    errdefer if (!group_expressions_transferred) {
        freeExpressionProjections(alloc, owned_group_expressions);
        if (owned_group_expressions.len > 0) alloc.free(owned_group_expressions);
    };
    const owned_aggregations = try aggregations.toOwnedSlice(alloc);
    var aggregations_transferred = false;
    errdefer if (!aggregations_transferred) {
        plan_mod.freeAggregateSpecs(alloc, owned_aggregations);
        if (owned_aggregations.len > 0) alloc.free(owned_aggregations);
    };
    const owned_outputs = try outputs.toOwnedSlice(alloc);
    var outputs_transferred = false;
    errdefer if (!outputs_transferred and owned_outputs.len > 0) alloc.free(owned_outputs);

    group_fields_transferred = true;
    group_expressions_transferred = true;
    aggregations_transferred = true;
    outputs_transferred = true;
    return .{
        .group_fields = owned_group_fields,
        .group_expressions = owned_group_expressions,
        .aggregations = owned_aggregations,
        .outputs = owned_outputs,
    };
}

pub fn parseSelectOutputOrderByNameMaybeAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    select: plan_mod.SelectList,
) !?db_mod.types.RelationalRowsQueryOrder {
    if (!parser.peekKind(tokens, pos.*, .identifier)) return null;
    if (pos.* + 1 < tokens.len) {
        switch (tokens[pos.* + 1].kind) {
            .lparen, .arrow_json, .arrow_text, .path_arrow_json, .path_arrow_text, .plus, .minus, .star, .slash, .percent, .pipe_concat => return null,
            else => {},
        }
    }

    const name = tokens[pos.*].text;
    const output = (try plan_mod.selectOutputByName(name, select)) orelse return null;
    pos.* += 1;
    return try selectOutputOrderByRefAlloc(alloc, select, output);
}

pub fn parseOrderByAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    order_by: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsQueryOrder),
    options: OrderByParserOptions,
) !void {
    return try parseOrderByWithExpressionHooksAlloc(
        alloc,
        tokens,
        pos,
        order_by,
        options.schema,
        options.function_bindings,
        options.field_expression_qualifiers,
        options.returning_expression_qualifiers,
        options.defer_row_expression_field_validation,
        options.type_context,
        options.order_expression_hooks,
        options.generated_read_ast,
    );
}

pub fn parseOrderByWithExpressionHooksAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    order_by: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsQueryOrder),
    schema: runtime_schema.TableSchema,
    function_bindings: SqlFunctionBindings,
    field_expression_qualifiers: []const []const u8,
    returning_expression_qualifiers: []const []const u8,
    defer_row_expression_field_validation: bool,
    type_context: RowExpressionTypeContext,
    hooks: OrderExpressionParserOptions,
    generated_read_ast: ?*const generated_parser.GeneratedSqlReadAst,
) !void {
    while (true) {
        const item_start = pos.*;
        const generated_expression = try generatedOrderExpressionAtItemStart(item_start, generated_read_ast);
        if (generated_expression == null and generated_read_ast != null) return error.UnsupportedSqlShape;
        var item_hooks = hooks;
        item_hooks.generated_expression_ast = generated_expression;
        var order = try parseOrderExpressionAlloc(
            alloc,
            tokens,
            pos,
            schema,
            function_bindings,
            field_expression_qualifiers,
            returning_expression_qualifiers,
            defer_row_expression_field_validation,
            type_context,
            item_hooks,
        );
        var order_transferred = false;
        errdefer if (!order_transferred) {
            if (order.field.len > 0) alloc.free(order.field);
            if (order.expression) |expression| freeExpression(alloc, expression);
        };
        const explicit_nulls_first = try parseOrderModifiers(tokens, pos, &order);
        try appendOrderWithNullPlacement(alloc, order_by, order, explicit_nulls_first);
        order_transferred = true;
        if (parser.matchToken(tokens, pos, .comma) == null) break;
    }
}

pub fn parseSelectOutputOrderByAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    order_by: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsQueryOrder),
    select: plan_mod.SelectList,
    options: OrderByParserOptions,
) !void {
    while (true) {
        const item_start = pos.*;
        const generated_expression = try generatedOrderExpressionAtItemStart(item_start, options.generated_read_ast);
        if (generated_expression == null and options.generated_read_ast != null) return error.UnsupportedSqlShape;
        var order_expression_hooks = options.order_expression_hooks;
        order_expression_hooks.generated_expression_ast = generated_expression;
        var order = if (parser.matchToken(tokens, pos, .number)) |token| blk: {
            try validateGeneratedSimpleOrderExpression(generated_expression);
            const ordinal = std.fmt.parseInt(u32, token.text, 10) catch return error.UnsupportedSqlShape;
            break :blk try selectOutputOrderByOrdinalAlloc(alloc, options.schema, select, ordinal);
        } else if (try parseSelectOutputOrderByNameMaybeAlloc(alloc, tokens, pos, select)) |named_order| blk: {
            try validateGeneratedSimpleOrderExpression(generated_expression);
            break :blk named_order;
        } else try parseOrderExpressionAlloc(
            alloc,
            tokens,
            pos,
            options.schema,
            options.function_bindings,
            options.field_expression_qualifiers,
            options.returning_expression_qualifiers,
            options.defer_row_expression_field_validation,
            options.type_context,
            order_expression_hooks,
        );
        var order_transferred = false;
        errdefer if (!order_transferred) {
            if (order.field.len > 0) alloc.free(order.field);
            if (order.expression) |expression| freeExpression(alloc, expression);
        };
        const explicit_nulls_first = try parseOrderModifiers(tokens, pos, &order);
        try appendOrderWithNullPlacement(alloc, order_by, order, explicit_nulls_first);
        order_transferred = true;
        if (parser.matchToken(tokens, pos, .comma) == null) break;
    }
}

pub fn expressionFromJsonExtractProjectionAlloc(
    alloc: std.mem.Allocator,
    projection: db_mod.types.RelationalRowsJsonExtractProjection,
) anyerror!db_mod.types.RelationalRowsExpression {
    const operands = try alloc.alloc(db_mod.types.RelationalRowsExpression, 1);
    var operands_transferred = false;
    errdefer if (!operands_transferred) alloc.free(operands);
    operands[0] = .{ .kind = .field, .field = try alloc.dupe(u8, projection.field) };
    var operand_transferred = false;
    errdefer if (!operand_transferred) freeExpression(alloc, operands[0]);
    const path = try alloc.dupe(u8, projection.path);
    var path_transferred = false;
    errdefer if (!path_transferred) alloc.free(path);
    operands_transferred = true;
    operand_transferred = true;
    path_transferred = true;
    return .{
        .kind = .json_extract,
        .json_path = path,
        .json_as_text = projection.as_text,
        .operands = operands,
    };
}

pub fn expressionFromArrayLengthProjectionAlloc(
    alloc: std.mem.Allocator,
    projection: db_mod.types.RelationalRowsArrayLengthProjection,
) !db_mod.types.RelationalRowsExpression {
    const operands = try alloc.alloc(db_mod.types.RelationalRowsExpression, 1);
    var operands_transferred = false;
    errdefer if (!operands_transferred) alloc.free(operands);
    operands[0] = .{ .kind = .field, .field = try alloc.dupe(u8, projection.field) };
    var operand_transferred = false;
    errdefer if (!operand_transferred) freeExpression(alloc, operands[0]);
    operands_transferred = true;
    operand_transferred = true;
    return .{
        .kind = .array_length,
        .operands = operands,
    };
}

pub fn expressionFromCoalesceProjectionAlloc(
    alloc: std.mem.Allocator,
    projection: db_mod.types.RelationalRowsCoalesceProjection,
) !db_mod.types.RelationalRowsExpression {
    var expression_projection = try plan_mod.expressionProjectionFromCoalesceAlloc(alloc, projection);
    alloc.free(expression_projection.output);
    expression_projection.output = "";
    return expression_projection.expression;
}

pub fn aggregateFilterExpressionCount(aggregations: []const db_mod.types.RelationalRowsAggregateSpec) usize {
    var count: usize = 0;
    for (aggregations) |aggregation| {
        count += aggregation.filter_expressions.len;
    }
    return count;
}

pub fn aggregateFilterExpressionArrayCount(aggregations: []const db_mod.types.RelationalRowsAggregateSpec) usize {
    var count: usize = 0;
    for (aggregations) |aggregation| {
        count += aggregation.filter_expression_array_contains.len;
    }
    return count;
}

pub fn aggregateFilterJsonAccessCount(aggregations: []const db_mod.types.RelationalRowsAggregateSpec) usize {
    var count: usize = 0;
    for (aggregations) |aggregation| {
        count += aggregation.filter_json_contains.len +
            aggregation.filter_json_path_eq.len +
            aggregation.filter_json_path_exists.len;
    }
    return count;
}

pub fn aggregateFilterStructuredAccessCount(aggregations: []const db_mod.types.RelationalRowsAggregateSpec) usize {
    var count: usize = 0;
    for (aggregations) |aggregation| {
        count += aggregation.filter_array_any.len +
            aggregation.filter_array_contains.len +
            aggregation.filter_array_eq.len +
            aggregation.filter_in_predicates.len +
            aggregation.filter_text_patterns.len;
    }
    return count;
}

pub fn aggregateFilterGroupCount(aggregations: []const db_mod.types.RelationalRowsAggregateSpec) usize {
    var count: usize = 0;
    for (aggregations) |aggregation| {
        count += aggregation.filter_any.len + aggregation.filter_not.len;
    }
    return count;
}

pub fn aggregateInputExpressionCount(aggregations: []const db_mod.types.RelationalRowsAggregateSpec) usize {
    var count: usize = 0;
    for (aggregations) |aggregation| {
        if (aggregation.expression != null) count += 1;
    }
    return count;
}

pub fn aggregateDescendingPercentileCount(aggregations: []const db_mod.types.RelationalRowsAggregateSpec) usize {
    var count: usize = 0;
    for (aggregations) |aggregation| {
        if (isSqlPercentileAggregateOp(aggregation.op) and aggregation.percentile_order == .desc) count += 1;
    }
    return count;
}

pub fn aggregatePercentileArrayCount(aggregations: []const db_mod.types.RelationalRowsAggregateSpec) usize {
    var count: usize = 0;
    for (aggregations) |aggregation| {
        if (isSqlPercentileAggregateOp(aggregation.op) and aggregation.percentiles.len > 0) count += 1;
    }
    return count;
}

pub fn aggregateModeCount(aggregations: []const db_mod.types.RelationalRowsAggregateSpec) usize {
    var count: usize = 0;
    for (aggregations) |aggregation| {
        if (aggregation.op == .mode) count += 1;
    }
    return count;
}

pub fn windowFunctionRequiresOrder(function: db_mod.types.RelationalRowsWindowFunction) bool {
    return switch (function) {
        .count, .sum, .avg, .min, .max, .bool_or, .bool_and => false,
        .row_number, .rank, .dense_rank, .percent_rank, .cume_dist, .ntile, .lag, .lead, .first_value, .last_value, .nth_value => true,
    };
}

pub fn windowFunctionName(function: db_mod.types.RelationalRowsWindowFunction) []const u8 {
    return switch (function) {
        .row_number => "row_number",
        .rank => "rank",
        .dense_rank => "dense_rank",
        .percent_rank => "percent_rank",
        .cume_dist => "cume_dist",
        .ntile => "ntile",
        .lag => "lag",
        .lead => "lead",
        .first_value => "first_value",
        .last_value => "last_value",
        .nth_value => "nth_value",
        .count => "count",
        .sum => "sum",
        .avg => "avg",
        .min => "min",
        .max => "max",
        .bool_or => "bool_or",
        .bool_and => "bool_and",
    };
}

pub fn windowFunctionSupportsFilter(function: db_mod.types.RelationalRowsWindowFunction) bool {
    return switch (function) {
        .count, .sum, .avg, .min, .max, .bool_or, .bool_and => true,
        else => false,
    };
}

pub fn parseWindowFunction(
    tokens: []const Token,
    pos: *usize,
) !db_mod.types.RelationalRowsWindowFunction {
    if (parser.matchKeyword(tokens, pos, "row_number")) return .row_number;
    if (parser.matchKeyword(tokens, pos, "rank")) return .rank;
    if (parser.matchKeyword(tokens, pos, "dense_rank")) return .dense_rank;
    if (parser.matchKeyword(tokens, pos, "percent_rank")) return .percent_rank;
    if (parser.matchKeyword(tokens, pos, "cume_dist")) return .cume_dist;
    if (parser.matchKeyword(tokens, pos, "ntile")) return .ntile;
    if (parser.matchKeyword(tokens, pos, "lag")) return .lag;
    if (parser.matchKeyword(tokens, pos, "lead")) return .lead;
    if (parser.matchKeyword(tokens, pos, "first_value")) return .first_value;
    if (parser.matchKeyword(tokens, pos, "last_value")) return .last_value;
    if (parser.matchKeyword(tokens, pos, "nth_value")) return .nth_value;
    if (parser.matchKeyword(tokens, pos, "count")) return .count;
    if (parser.matchKeyword(tokens, pos, "sum")) return .sum;
    if (parser.matchKeyword(tokens, pos, "avg")) return .avg;
    if (parser.matchKeyword(tokens, pos, "min")) return .min;
    if (parser.matchKeyword(tokens, pos, "max")) return .max;
    if (parser.matchKeyword(tokens, pos, "bool_or")) return .bool_or;
    if (parser.matchKeyword(tokens, pos, "bool_and")) return .bool_and;
    return error.UnsupportedSqlShape;
}

pub fn parseOptionalWindowFrame(
    tokens: []const Token,
    pos: *usize,
    params: []const value_mod.SqlValue,
) !?db_mod.types.RelationalRowsWindowFrame {
    const unit: db_mod.types.RelationalRowsWindowFrameUnit = if (parser.matchKeyword(tokens, pos, "rows"))
        .rows
    else if (parser.matchKeyword(tokens, pos, "range"))
        .range
    else
        return null;
    const start, const end = if (parser.matchKeyword(tokens, pos, "between")) blk: {
        const parsed_start = try parseWindowFrameBound(tokens, pos, params);
        try parser.expectKeyword(tokens, pos, "and");
        const parsed_end = try parseWindowFrameBound(tokens, pos, params);
        break :blk .{ parsed_start, parsed_end };
    } else blk: {
        const parsed_start = try parseWindowFrameBound(tokens, pos, params);
        break :blk .{ parsed_start, plan_mod.ParsedWindowFrameBound{ .bound = .current_row } };
    };
    const frame = db_mod.types.RelationalRowsWindowFrame{
        .unit = unit,
        .start = start.bound,
        .start_offset = start.offset,
        .end = end.bound,
        .end_offset = end.offset,
    };
    try validateWindowFrame(frame);
    return frame;
}

pub fn parseWindowFrameBound(
    tokens: []const Token,
    pos: *usize,
    params: []const value_mod.SqlValue,
) !plan_mod.ParsedWindowFrameBound {
    if (parser.matchKeyword(tokens, pos, "unbounded")) {
        if (parser.matchKeyword(tokens, pos, "preceding")) return .{ .bound = .unbounded_preceding };
        if (parser.matchKeyword(tokens, pos, "following")) return .{ .bound = .unbounded_following };
        return error.UnsupportedSqlShape;
    }
    if (parser.matchKeyword(tokens, pos, "current")) {
        try parser.expectKeyword(tokens, pos, "row");
        return .{ .bound = .current_row };
    }
    const offset = try value_mod.parseSqlU32Value(tokens, pos, params);
    if (offset == 0) return error.UnsupportedSqlShape;
    if (parser.matchKeyword(tokens, pos, "preceding")) return .{ .bound = .offset_preceding, .offset = offset };
    if (parser.matchKeyword(tokens, pos, "following")) return .{ .bound = .offset_following, .offset = offset };
    return error.UnsupportedSqlShape;
}

pub fn parseWindowPartitionByAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    partition_by: *std.ArrayListUnmanaged([]const u8),
    options: WindowDefinitionParserOptions,
) !void {
    while (true) {
        const parsed_field = try parseRowExpressionFieldOwnedAlloc(
            alloc,
            tokens,
            pos,
            options.schema,
            options.field_expression_qualifiers,
            options.returning_expression_qualifiers,
            options.defer_row_expression_field_validation,
        );
        defer alloc.free(parsed_field);
        const field = try binder.normalizeRowExpressionFieldAlloc(alloc, options.schema, parsed_field, options.field_expression_qualifiers, options.returning_expression_qualifiers, options.defer_row_expression_field_validation);
        var field_transferred = false;
        errdefer if (!field_transferred) alloc.free(field);
        if (binder.relationalColumnForField(options.schema, field, null) == null) return error.InvalidSqlCatalog;
        try partition_by.append(alloc, field);
        field_transferred = true;
        if (parser.matchToken(tokens, pos, .comma) == null) break;
        if (parser.peekKeyword(tokens, pos.*, "order")) return error.UnsupportedSqlShape;
    }
}

pub fn parseWindowDefinitionAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    params: []const value_mod.SqlValue,
    options: WindowDefinitionParserOptions,
) !plan_mod.NamedWindowDefinition {
    var partition_by = std.ArrayListUnmanaged([]const u8).empty;
    errdefer {
        for (partition_by.items) |field| alloc.free(field);
        partition_by.deinit(alloc);
    }
    if (parser.matchKeyword(tokens, pos, "partition")) {
        try parser.expectKeyword(tokens, pos, "by");
        try parseWindowPartitionByAlloc(
            alloc,
            tokens,
            pos,
            &partition_by,
            options,
        );
    }

    var order_by = std.ArrayListUnmanaged(db_mod.types.RelationalRowsQueryOrder).empty;
    errdefer {
        freeOrderBy(alloc, order_by.items);
        order_by.deinit(alloc);
    }
    if (parser.matchKeyword(tokens, pos, "order")) {
        try parser.expectKeyword(tokens, pos, "by");
        try parseOrderByAlloc(
            alloc,
            tokens,
            pos,
            &order_by,
            .{
                .schema = options.schema,
                .function_bindings = options.function_bindings,
                .field_expression_qualifiers = options.field_expression_qualifiers,
                .returning_expression_qualifiers = options.returning_expression_qualifiers,
                .defer_row_expression_field_validation = options.defer_row_expression_field_validation,
                .type_context = options.type_context,
                .order_expression_hooks = options.order_expression_hooks,
            },
        );
        if (order_by.items.len == 0) return error.UnsupportedSqlShape;
    }

    const frame = try parseOptionalWindowFrame(tokens, pos, params);
    if (frame != null and order_by.items.len == 0) return error.UnsupportedSqlShape;
    if (frame) |parsed_frame| try validateWindowFrameForOrder(options.schema, options.type_context, parsed_frame, order_by.items);

    const owned_partition_by = try partition_by.toOwnedSlice(alloc);
    var partition_transferred = false;
    errdefer if (!partition_transferred) strings.freeStringSlice(alloc, owned_partition_by);
    const owned_order_by = try order_by.toOwnedSlice(alloc);
    var order_transferred = false;
    errdefer if (!order_transferred) {
        freeOrderBy(alloc, owned_order_by);
        if (owned_order_by.len > 0) alloc.free(owned_order_by);
    };

    partition_transferred = true;
    order_transferred = true;
    return .{
        .partition_by = owned_partition_by,
        .order_by = owned_order_by,
        .frame = frame,
    };
}

pub fn parseNamedWindowSpecsAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    params: []const value_mod.SqlValue,
    window_definition_options: WindowDefinitionParserOptions,
) ![]const plan_mod.NamedWindowSpec {
    var specs = std.ArrayListUnmanaged(plan_mod.NamedWindowSpec).empty;
    errdefer {
        for (specs.items) |spec| plan_mod.freeNamedWindowSpec(alloc, spec);
        specs.deinit(alloc);
    }

    while (true) {
        const spec = try parseNamedWindowSpecAlloc(
            alloc,
            tokens,
            pos,
            params,
            specs.items,
            window_definition_options,
        );
        var spec_transferred = false;
        errdefer if (!spec_transferred) plan_mod.freeNamedWindowSpec(alloc, spec);
        try specs.append(alloc, spec);
        spec_transferred = true;
        if (parser.matchToken(tokens, pos, .comma) == null) break;
    }
    if (!parser.atEnd(tokens, pos.*)) return error.UnsupportedSqlShape;
    return try specs.toOwnedSlice(alloc);
}

pub fn parseTopLevelNamedWindowSpecsAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: usize,
    params: []const value_mod.SqlValue,
    window_definition_options: WindowDefinitionParserOptions,
) ![]const plan_mod.NamedWindowSpec {
    const start = topLevelWindowClauseStart(tokens, pos) orelse return &.{};
    const end = topLevelWindowClauseEnd(tokens, start + 1);
    var window_pos: usize = 0;
    return try parseNamedWindowSpecsAlloc(
        alloc,
        tokens[start + 1 .. end],
        &window_pos,
        params,
        window_definition_options,
    );
}

pub fn parseNamedWindowSpecAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    params: []const value_mod.SqlValue,
    existing: []const plan_mod.NamedWindowSpec,
    window_definition_options: WindowDefinitionParserOptions,
) !plan_mod.NamedWindowSpec {
    const name = try parseIdentifierOwnedAlloc(alloc, tokens, pos);
    var name_transferred = false;
    errdefer if (!name_transferred) alloc.free(name);
    for (existing) |spec| {
        if (std.ascii.eqlIgnoreCase(spec.name, name)) return error.UnsupportedSqlShape;
    }

    try parser.expectKeyword(tokens, pos, "as");
    try parser.expectToken(tokens, pos, .lparen);
    const definition = try parseWindowDefinitionAlloc(
        alloc,
        tokens,
        pos,
        params,
        window_definition_options,
    );
    var definition_transferred = false;
    errdefer if (!definition_transferred) plan_mod.freeNamedWindowDefinition(alloc, definition);
    try parser.expectToken(tokens, pos, .rparen);

    name_transferred = true;
    definition_transferred = true;
    return .{
        .name = name,
        .partition_by = definition.partition_by,
        .order_by = definition.order_by,
        .frame = definition.frame,
    };
}

pub fn parseWindowDefinitionReferenceAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    params: []const value_mod.SqlValue,
    named_window_specs: []const plan_mod.NamedWindowSpec,
    window_definition_options: WindowDefinitionParserOptions,
) !plan_mod.NamedWindowDefinition {
    if (parser.matchToken(tokens, pos, .lparen) != null) {
        const definition = try parseWindowDefinitionAlloc(
            alloc,
            tokens,
            pos,
            params,
            window_definition_options,
        );
        errdefer plan_mod.freeNamedWindowDefinition(alloc, definition);
        try parser.expectToken(tokens, pos, .rparen);
        return definition;
    }

    const name = try parseIdentifierOwnedAlloc(alloc, tokens, pos);
    defer alloc.free(name);
    for (named_window_specs) |spec| {
        if (std.ascii.eqlIgnoreCase(spec.name, name)) {
            return try plan_mod.cloneNamedWindowDefinitionAlloc(alloc, spec);
        }
    }
    return error.UnsupportedSqlShape;
}

pub fn topLevelWindowClauseStart(tokens: []const Token, pos: usize) ?usize {
    var depth: usize = 0;
    var i = pos;
    while (i < tokens.len) : (i += 1) {
        const token = tokens[i];
        switch (token.kind) {
            .lparen => depth += 1,
            .rparen => if (depth > 0) {
                depth -= 1;
            },
            .identifier => if (depth == 0 and token.matchesKeywordTag(.window)) return i,
            .semicolon => if (depth == 0) return null,
            else => {},
        }
    }
    return null;
}

pub fn topLevelWindowClauseEnd(tokens: []const Token, start: usize) usize {
    return parser.findTopLevelTailIndexToken(tokens, start, sqlWindowTailClauseKeywordToken);
}

pub fn parseWindowSpecAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    params: []const value_mod.SqlValue,
    schema: runtime_schema.TableSchema,
    field_expression_qualifiers: []const []const u8,
    returning_expression_qualifiers: []const []const u8,
    defer_row_expression_field_validation: bool,
    type_context: RowExpressionTypeContext,
    named_window_specs: []const plan_mod.NamedWindowSpec,
    window_definition_options: WindowDefinitionParserOptions,
    options: WindowSpecParserOptions,
) !db_mod.types.RelationalRowsWindowSpec {
    const function = try parseWindowFunction(tokens, pos);
    try parser.expectToken(tokens, pos, .lparen);
    const value_expression: ?db_mod.types.RelationalRowsExpression = switch (function) {
        .row_number, .rank, .dense_rank, .percent_rank, .cume_dist, .ntile => null,
        .lag, .lead, .first_value, .last_value, .nth_value => try parseRowExpressionAlloc(alloc, tokens, pos, type_context, options.row_expression_hooks, options.arithmetic_hooks, options.variadic_hooks),
        .count => if (parser.matchToken(tokens, pos, .star) != null) null else try parseRowExpressionAlloc(alloc, tokens, pos, type_context, options.row_expression_hooks, options.arithmetic_hooks, options.variadic_hooks),
        .sum, .avg, .min, .max => try parseRowExpressionAlloc(alloc, tokens, pos, type_context, options.row_expression_hooks, options.arithmetic_hooks, options.variadic_hooks),
        .bool_or, .bool_and => try parseBooleanRowExpressionAlloc(alloc, tokens, pos, type_context, options.boolean_hooks),
    };
    var value_expression_transferred = false;
    errdefer if (!value_expression_transferred) if (value_expression) |expression| freeExpression(alloc, expression);
    if (value_expression) |expression| {
        switch (function) {
            .sum, .avg => try type_context.validateNumericRowExpression(expression),
            .min, .max => try validateAggregateMinMaxRowExpression(type_context, expression),
            .bool_or, .bool_and => try type_context.validateBooleanRowExpression(expression),
            else => {},
        }
    }

    const offset: u32 = switch (function) {
        .row_number, .rank, .dense_rank, .percent_rank, .cume_dist, .first_value, .last_value, .count, .sum, .avg, .min, .max, .bool_or, .bool_and => 1,
        .ntile => blk: {
            const parsed_offset = try value_mod.parseSqlU32Value(tokens, pos, params);
            if (parsed_offset == 0) return error.UnsupportedSqlShape;
            break :blk parsed_offset;
        },
        .nth_value => blk: {
            if (parser.matchToken(tokens, pos, .comma) == null) return error.UnsupportedSqlShape;
            const parsed_offset = try value_mod.parseSqlU32Value(tokens, pos, params);
            if (parsed_offset == 0) return error.UnsupportedSqlShape;
            break :blk parsed_offset;
        },
        .lag, .lead => if (parser.matchToken(tokens, pos, .comma) != null) blk: {
            const parsed_offset = try value_mod.parseSqlU32Value(tokens, pos, params);
            if (parsed_offset == 0) return error.UnsupportedSqlShape;
            break :blk parsed_offset;
        } else 1,
    };

    const default_json: []const u8 = switch (function) {
        .row_number, .rank, .dense_rank, .percent_rank, .cume_dist, .ntile, .first_value, .last_value, .nth_value, .count, .sum, .avg, .min, .max, .bool_or, .bool_and => &.{},
        .lag, .lead => if (parser.matchToken(tokens, pos, .comma) != null)
            try value_mod.parseJsonValueAlloc(alloc, tokens, pos, params)
        else
            &.{},
    };
    var default_transferred = false;
    errdefer if (!default_transferred) if (default_json.len > 0) alloc.free(default_json);
    try parser.expectToken(tokens, pos, .rparen);
    const generated_filter_expression: ?*const generated_parser.GeneratedSqlExpressionAst = if (parser.peekKeyword(tokens, pos.*, "filter")) blk: {
        const generated_expression = options.generated_expression_ast orelse break :blk null;
        break :blk generated_expression.filter_expression;
    } else null;
    const filter = try parseAggregateFilterAlloc(
        alloc,
        tokens,
        pos,
        schema,
        field_expression_qualifiers,
        returning_expression_qualifiers,
        defer_row_expression_field_validation,
        params,
        type_context,
        options.expression_alternatives,
        options.expression_conditions,
        options.fixed_binary,
        options.realtime_ns,
        generated_filter_expression,
    );
    var filter_transferred = false;
    errdefer if (!filter_transferred) freeAggregateFilter(alloc, filter);
    if (!windowFunctionSupportsFilter(function) and !aggregateFilterIsEmpty(filter)) return error.UnsupportedSqlShape;
    try parser.expectKeyword(tokens, pos, "over");
    const over_start = pos.* - 1;

    const definition = try parseWindowDefinitionReferenceAlloc(
        alloc,
        tokens,
        pos,
        params,
        named_window_specs,
        window_definition_options,
    );
    var definition_transferred = false;
    errdefer if (!definition_transferred) plan_mod.freeNamedWindowDefinition(alloc, definition);
    if (definition.order_by.len == 0 and windowFunctionRequiresOrder(function)) return error.UnsupportedSqlShape;
    try validateGeneratedWindowOverClauseForSpec(tokens, over_start, pos.*, options.generated_expression_ast);

    const output = try grammar.parseProjectionOutputOwnedAlloc(alloc, tokens, pos, windowFunctionName(function));
    var output_transferred = false;
    errdefer if (!output_transferred) alloc.free(output);

    output_transferred = true;
    definition_transferred = true;
    value_expression_transferred = true;
    default_transferred = true;
    filter_transferred = true;
    return .{
        .output = output,
        .function = function,
        .partition_by = definition.partition_by,
        .order_by = definition.order_by,
        .value_expression = value_expression,
        .offset = offset,
        .default_json = default_json,
        .frame = definition.frame,
        .filter_predicates = filter.predicates,
        .filter_array_any = filter.array_any,
        .filter_array_contains = filter.array_contains,
        .filter_array_eq = filter.array_eq,
        .filter_in_predicates = filter.in_predicates,
        .filter_json_contains = filter.json_contains,
        .filter_json_path_eq = filter.json_path_eq,
        .filter_json_path_exists = filter.json_path_exists,
        .filter_text_patterns = filter.text_patterns,
        .filter_expressions = filter.expressions,
        .filter_expression_array_contains = filter.expression_array_contains,
        .filter_any = filter.any_groups,
        .filter_not = filter.not_groups,
    };
}

pub fn windowOutputType(
    function: db_mod.types.RelationalRowsWindowFunction,
    value_type: ?runtime_schema.AntflyType,
) !runtime_schema.AntflyType {
    return switch (function) {
        .row_number, .rank, .dense_rank, .percent_rank, .cume_dist, .ntile, .count, .sum, .avg => .numeric,
        .lag, .lead, .first_value, .last_value, .nth_value, .min, .max => value_type orelse error.UnsupportedSqlShape,
        .bool_or, .bool_and => .boolean,
    };
}

pub fn aggregateOutputProjectedType(
    aggregation: db_mod.types.RelationalRowsAggregateSpec,
    input_type: ?runtime_schema.AntflyType,
) !ProjectedColumnType {
    return switch (aggregation.op) {
        .array_agg => .{
            .field_type = .array,
            .array_item_type = input_type orelse return error.UnsupportedSqlShape,
        },
        .string_agg => .{ .field_type = .keyword },
        .percentile_cont, .percentile_disc => .{
            .field_type = if (aggregation.percentiles.len > 0) .array else .numeric,
            .array_item_type = if (aggregation.percentiles.len > 0) .numeric else null,
        },
        .count, .sum, .avg => .{ .field_type = .numeric },
        .min, .max, .mode => .{ .field_type = input_type orelse return error.UnsupportedSqlShape },
        .bool_or, .bool_and => .{ .field_type = .boolean },
    };
}

pub fn sqlExpressionIsInterval(expression: db_mod.types.RelationalRowsExpression) bool {
    return expression.kind == .interval_ns or expression.kind == .interval_months;
}

pub fn sqlExpressionContainsInterval(expression: db_mod.types.RelationalRowsExpression) bool {
    if (sqlExpressionIsInterval(expression)) return true;
    for (expression.operands) |operand| {
        if (sqlExpressionContainsInterval(operand)) return true;
    }
    return false;
}

pub fn aggregateFilterIsEmpty(filter: AggregateFilter) bool {
    return filter.predicates.len == 0 and
        filter.array_any.len == 0 and
        filter.array_contains.len == 0 and
        filter.array_eq.len == 0 and
        filter.in_predicates.len == 0 and
        filter.json_contains.len == 0 and
        filter.json_path_eq.len == 0 and
        filter.json_path_exists.len == 0 and
        filter.text_patterns.len == 0 and
        filter.expressions.len == 0 and
        filter.expression_array_contains.len == 0 and
        filter.any_groups.len == 0 and
        filter.not_groups.len == 0;
}

pub fn freeAggregateFilter(alloc: std.mem.Allocator, filter: AggregateFilter) void {
    freeRelationalChecks(alloc, filter.predicates);
    if (filter.predicates.len > 0) alloc.free(filter.predicates);
    freeArrayAny(alloc, filter.array_any);
    if (filter.array_any.len > 0) alloc.free(filter.array_any);
    freeArrayContains(alloc, filter.array_contains);
    if (filter.array_contains.len > 0) alloc.free(filter.array_contains);
    freeArrayEq(alloc, filter.array_eq);
    if (filter.array_eq.len > 0) alloc.free(filter.array_eq);
    freeInPredicates(alloc, filter.in_predicates);
    if (filter.in_predicates.len > 0) alloc.free(filter.in_predicates);
    freeJsonContains(alloc, filter.json_contains);
    if (filter.json_contains.len > 0) alloc.free(filter.json_contains);
    freeJsonPathEq(alloc, filter.json_path_eq);
    if (filter.json_path_eq.len > 0) alloc.free(filter.json_path_eq);
    freeJsonPathExists(alloc, filter.json_path_exists);
    if (filter.json_path_exists.len > 0) alloc.free(filter.json_path_exists);
    freeTextPatterns(alloc, filter.text_patterns);
    if (filter.text_patterns.len > 0) alloc.free(filter.text_patterns);
    freeExpressionConditions(alloc, filter.expressions);
    if (filter.expressions.len > 0) alloc.free(filter.expressions);
    freeExpressionArrayContains(alloc, filter.expression_array_contains);
    if (filter.expression_array_contains.len > 0) alloc.free(filter.expression_array_contains);
    freeExpressionPredicateGroups(alloc, filter.any_groups);
    if (filter.any_groups.len > 0) alloc.free(filter.any_groups);
    freeExpressionPredicateGroups(alloc, filter.not_groups);
    if (filter.not_groups.len > 0) alloc.free(filter.not_groups);
}

pub fn validateWindowFrame(frame: db_mod.types.RelationalRowsWindowFrame) !void {
    try validateWindowFrameBoundOffset(frame.start, frame.start_offset);
    try validateWindowFrameBoundOffset(frame.end, frame.end_offset);
    if (frame.start == .unbounded_following or frame.end == .unbounded_preceding) return error.UnsupportedSqlShape;
    if (windowFrameBoundOrdinal(frame.start, frame.start_offset) > windowFrameBoundOrdinal(frame.end, frame.end_offset)) return error.UnsupportedSqlShape;
}

pub fn validateWindowFrameForOrder(
    schema: runtime_schema.TableSchema,
    type_context: RowExpressionTypeContext,
    frame: db_mod.types.RelationalRowsWindowFrame,
    order_by: []const db_mod.types.RelationalRowsQueryOrder,
) !void {
    if (frame.unit != .range) return;
    if (frame.start != .offset_preceding and frame.start != .offset_following and frame.end != .offset_preceding and frame.end != .offset_following) return;
    if (order_by.len == 0) return error.UnsupportedSqlShape;
    const order = order_by[0];
    if (order.null_test != null) return error.UnsupportedSqlShape;
    if (order.expression) |expression| {
        try type_context.validateNumericOrDatetimeRowExpression(expression);
        return;
    }
    if (order.field.len == 0) return error.UnsupportedSqlShape;
    const column = binder.relationalColumnForField(schema, order.field, null) orelse return error.InvalidSqlCatalog;
    if (column.field_type != .numeric and column.field_type != .datetime) return error.UnsupportedSqlShape;
}

pub fn validateWindowFrameBoundOffset(
    bound: db_mod.types.RelationalRowsWindowFrameBound,
    offset: u32,
) !void {
    switch (bound) {
        .offset_preceding, .offset_following => {
            if (offset == 0) return error.UnsupportedSqlShape;
        },
        else => if (offset != 0) return error.UnsupportedSqlShape,
    }
}

pub fn windowFrameBoundOrdinal(bound: db_mod.types.RelationalRowsWindowFrameBound, offset: u32) i64 {
    return switch (bound) {
        .unbounded_preceding => std.math.minInt(i64),
        .offset_preceding => -@as(i64, @intCast(offset)),
        .current_row => 0,
        .offset_following => @as(i64, @intCast(offset)),
        .unbounded_following => std.math.maxInt(i64),
    };
}

pub fn windowValueExpressionCount(windows: []const db_mod.types.RelationalRowsWindowSpec) usize {
    var count: usize = 0;
    for (windows) |window| {
        if (window.value_expression != null) count += 1;
    }
    return count;
}

pub fn windowDefaultCount(windows: []const db_mod.types.RelationalRowsWindowSpec) usize {
    var count: usize = 0;
    for (windows) |window| {
        if (window.default_json.len > 0) count += 1;
    }
    return count;
}

pub fn windowFilterPredicateCount(windows: []const db_mod.types.RelationalRowsWindowSpec) usize {
    var count: usize = 0;
    for (windows) |window| {
        count += window.filter_predicates.len;
    }
    return count;
}

pub fn windowFilterExpressionCount(windows: []const db_mod.types.RelationalRowsWindowSpec) usize {
    var count: usize = 0;
    for (windows) |window| {
        count += window.filter_expressions.len;
    }
    return count;
}

pub fn windowFilterAccessCount(windows: []const db_mod.types.RelationalRowsWindowSpec) usize {
    var count: usize = 0;
    for (windows) |window| {
        count += window.filter_array_any.len +
            window.filter_array_contains.len +
            window.filter_array_eq.len +
            window.filter_in_predicates.len +
            window.filter_json_contains.len +
            window.filter_json_path_eq.len +
            window.filter_json_path_exists.len +
            window.filter_text_patterns.len +
            window.filter_expression_array_contains.len;
    }
    return count;
}

pub fn windowFilterGroupCount(windows: []const db_mod.types.RelationalRowsWindowSpec) usize {
    var count: usize = 0;
    for (windows) |window| {
        count += window.filter_any.len + window.filter_not.len;
    }
    return count;
}

pub fn windowFrameSignature(windows: []const db_mod.types.RelationalRowsWindowSpec) u64 {
    var signature: u64 = 0;
    for (windows) |window| {
        if (window.frame) |frame| {
            signature = signature *% 131 +% 17;
            signature = signature *% 131 +% windowFrameUnitCode(frame.unit);
            signature = signature *% 131 +% windowFrameBoundCode(frame.start);
            signature = signature *% 131 +% @as(u64, @intCast(frame.start_offset));
            signature = signature *% 131 +% windowFrameBoundCode(frame.end);
            signature = signature *% 131 +% @as(u64, @intCast(frame.end_offset));
        } else {
            signature = signature *% 131;
        }
    }
    return signature;
}

fn windowFrameUnitCode(unit: db_mod.types.RelationalRowsWindowFrameUnit) u64 {
    return switch (unit) {
        .rows => 1,
        .range => 2,
    };
}

fn windowFrameBoundCode(bound: db_mod.types.RelationalRowsWindowFrameBound) u64 {
    return switch (bound) {
        .unbounded_preceding => 1,
        .offset_preceding => 2,
        .current_row => 3,
        .offset_following => 4,
        .unbounded_following => 5,
    };
}

pub fn joinProjectionOutputIsUnique(select: []const db_mod.types.RelationalRowsJoinProjection, field: []const u8) bool {
    var matches: usize = 0;
    for (select) |projection| {
        if (std.mem.eql(u8, projection.output, field)) matches += 1;
    }
    return matches == 1;
}

pub fn joinOutputFieldByOrdinalAlloc(
    alloc: std.mem.Allocator,
    select: []const db_mod.types.RelationalRowsJoinProjection,
    ordinal: u32,
) ![]const u8 {
    if (ordinal == 0) return error.UnsupportedSqlShape;
    const index: usize = @intCast(ordinal - 1);
    if (index >= select.len) return error.UnsupportedSqlShape;
    return try alloc.dupe(u8, select[index].output);
}

pub fn joinOutputColumnsAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    select: []const db_mod.types.RelationalRowsJoinProjection,
) ![]runtime_schema.RelationalColumn {
    if (select.len == 0) return &.{};
    const out = try alloc.alloc(runtime_schema.RelationalColumn, select.len);
    var initialized: usize = 0;
    errdefer alloc.free(out);
    for (select) |projection| {
        if (aggregateOutputColumnExists(out[0..initialized], projection.output)) return error.UnsupportedSqlShape;
        const column = binder.relationalColumnForField(schema, projection.field, null) orelse return error.InvalidSqlCatalog;
        out[initialized] = .{
            .name = projection.output,
            .path = projection.output,
            .field_type = column.field_type,
            .array_item_type = column.array_item_type,
            .nullable = true,
        };
        initialized += 1;
    }
    return out;
}

pub fn identifierContainsQualifier(identifier: []const u8) bool {
    const dot = std.mem.indexOfScalar(u8, identifier, '.') orelse return false;
    return dot > 0 and dot + 1 < identifier.len;
}

pub fn tailMentionsAnyQualifierBeforeClose(
    tokens: []const Token,
    pos: usize,
    qualifiers: []const []const u8,
) bool {
    var depth: usize = 0;
    var i = pos;
    while (i < tokens.len) : (i += 1) {
        const token = tokens[i];
        switch (token.kind) {
            .lparen => depth += 1,
            .rparen => {
                if (depth == 0) return false;
                depth -= 1;
            },
            .identifier => {
                const dot = std.mem.indexOfScalar(u8, token.text, '.') orelse continue;
                const qualifier = token.text[0..dot];
                for (qualifiers) |candidate| {
                    if (std.mem.eql(u8, qualifier, candidate)) return true;
                }
            },
            else => {},
        }
    }
    return false;
}

fn optionalStringEqual(lhs: ?[]const u8, rhs: ?[]const u8) bool {
    if (lhs == null or rhs == null) return lhs == null and rhs == null;
    return std.mem.eql(u8, lhs.?, rhs.?);
}

fn floatSlicesEqual(lhs: []const f64, rhs: []const f64) bool {
    if (lhs.len != rhs.len) return false;
    for (lhs, rhs) |left, right| {
        if (left != right) return false;
    }
    return true;
}

fn orderByEqual(lhs: []const db_mod.types.RelationalRowsQueryOrder, rhs: []const db_mod.types.RelationalRowsQueryOrder) bool {
    if (lhs.len != rhs.len) return false;
    for (lhs, rhs) |lhs_order, rhs_order| {
        if (lhs_order.direction != rhs_order.direction or
            lhs_order.null_test != rhs_order.null_test or
            !std.mem.eql(u8, lhs_order.field, rhs_order.field) or
            !relationalRowsExpressionOptionalEqual(lhs_order.expression, rhs_order.expression))
        {
            return false;
        }
    }
    return true;
}

fn relationalChecksEqual(lhs: []const runtime_schema.RelationalCheck, rhs: []const runtime_schema.RelationalCheck) bool {
    if (lhs.len != rhs.len) return false;
    for (lhs, rhs) |lhs_check, rhs_check| {
        if (!std.mem.eql(u8, lhs_check.name, rhs_check.name) or
            !std.mem.eql(u8, lhs_check.field, rhs_check.field) or
            lhs_check.op != rhs_check.op or
            !optionalStringEqual(lhs_check.value_json, rhs_check.value_json))
        {
            return false;
        }
    }
    return true;
}

fn structuredValuePredicatesEqual(lhs: anytype, rhs: @TypeOf(lhs)) bool {
    if (lhs.len != rhs.len) return false;
    for (lhs, rhs) |lhs_predicate, rhs_predicate| {
        if (!std.mem.eql(u8, lhs_predicate.field, rhs_predicate.field) or
            !std.mem.eql(u8, lhs_predicate.value_json, rhs_predicate.value_json))
        {
            return false;
        }
    }
    return true;
}

