}

pub fn parseOrderExpressionWithSelectSchemaAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    schema: runtime_schema.TableSchema,
    function_bindings: SqlFunctionBindings,
    context_hooks: SelectParserContextHooks,
