pub const SelectItemStart = enum {
    pipe_concat,
    unary_negative,
    boolean_not,
    extension_function,
    routine_expression,
    uuid_v4,
    now,
    current_date,
    typed_datetime_literal,
    json_extract_path,
    json_typeof,
    json_array_length,
    json_build_object,
    convert_from,
    to_jsonb,
    array_length,
    array_position,
    array_element_transform,
    array_to_string,
    string_to_array,
    coalesce,
    case_fold,
    replace,
    regexp_replace,
    regexp_substr,
    regexp_match,
    regexp_count,
    regexp_instr,
    translate,
    concat,
    nullif,
    text_length,
    ascii,
    chr,
    substring,
    overlay,
    split_part,
    strpos,
    left_right,
    pad,
    repeat,
    reverse,
    md5,
    starts_with,
    ends_with,
    date_trunc,
    date_bin,
    date_part,
    abs,
    round,
    trunc,
    floor,
    ceil,
    sqrt,
    sign,
    mod,
    power,
    greatest_least,
    case,
    cast,
    parenthesized,
};

pub const SelectFieldItemParserOptions = struct {
    type_context: RowExpressionTypeContext,
    arithmetic_hooks: ArithmeticExpressionParserHooks,
    boolean_hooks: BooleanExpressionParserHooks,
};

pub const SelectItemParserOptions = struct {
    expression: ExpressionProjectionParserOptions,
    json_value_expression: JsonValueExpressionProjectionParserOptions,
    select_field: SelectFieldItemParserOptions,
    extension_function: ExtensionFunctionRowExpressionParserOptions,
    routine_expression: RoutineExpressionRowExpressionParserOptions,
    generated_expression_ast: ?*const generated_parser.GeneratedSqlExpressionAst = null,
};

pub const SelectListParserOptions = struct {
    params: []const value_mod.SqlValue = &.{},
    output_schema: runtime_schema.TableSchema,
    select_item_schema: runtime_schema.TableSchema,
    function_bindings: SqlFunctionBindings = .{},
    type_context: RowExpressionTypeContext,
    field_expression_qualifiers: []const []const u8 = &.{},
    returning_expression_qualifiers: []const []const u8 = &.{},
    defer_row_expression_field_validation: bool = false,
    field_source: db_mod.types.RelationalRowsExpressionFieldSource = .row,
    select_item_options: SelectItemParserOptions,
    generated_read_ast: ?*const generated_parser.GeneratedSqlReadAst = null,
};

pub const ReturningSelectItemParserOptions = struct {
    params: []const value_mod.SqlValue = &.{},
    function_bindings: SqlFunctionBindings = .{},
    field_source: db_mod.types.RelationalRowsExpressionFieldSource,
    context_hooks: SelectParserContextHooks,
    select_item_options: SelectItemParserOptions,
};

pub fn parseReturningSelectItemWithQualifiersAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    returning_qualifiers: []const []const u8,
    options: ReturningSelectItemParserOptions,
) !plan_mod.SelectItem {
    const previous_context = options.context_hooks.get_context(options.context_hooks.ptr);
    var context = previous_context;
    context.field_expression_qualifiers = returning_qualifiers;
    context.returning_expression_qualifiers = returning_qualifiers;
    options.context_hooks.set_context(options.context_hooks.ptr, context);
    defer options.context_hooks.set_context(options.context_hooks.ptr, previous_context);

    const current_context = options.context_hooks.get_context(options.context_hooks.ptr);
    return try parseSelectItemAlloc(
        alloc,
        tokens,
        pos,
        options.params,
        current_context.schema,
        options.function_bindings,
        current_context.field_expression_qualifiers,
        current_context.returning_expression_qualifiers,
        current_context.defer_row_expression_field_validation,
        options.field_source,
        options.context_hooks.row_expression_type_context(options.context_hooks.ptr),
        options.select_item_options,
    );
}

pub const JoinedReturningSelectItemParserOptions = struct {
    params: []const value_mod.SqlValue = &.{},
    function_bindings: SqlFunctionBindings = .{},
    field_source: db_mod.types.RelationalRowsExpressionFieldSource,
    select_context_hooks: SelectParserContextHooks,
    joined_context_hooks: JoinedExpressionParserContextHooks,
    select_item_options: SelectItemParserOptions,
};

pub fn parseJoinedReturningSelectItemWithQualifiersAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    source_alias: []const u8,
    returning_qualifiers: []const []const u8,
    options: JoinedReturningSelectItemParserOptions,
) !plan_mod.SelectItem {
    const previous_select_context = options.select_context_hooks.get_context(options.select_context_hooks.ptr);
    const previous_joined_context = options.joined_context_hooks.get_context(options.joined_context_hooks.ptr);
    const source_qualifiers = [_][]const u8{source_alias};

    var select_context = previous_select_context;
    select_context.field_expression_qualifiers = returning_qualifiers;
    select_context.returning_expression_qualifiers = returning_qualifiers;
    select_context.defer_row_expression_field_validation = true;
    options.select_context_hooks.set_context(options.select_context_hooks.ptr, select_context);
    defer options.select_context_hooks.set_context(options.select_context_hooks.ptr, previous_select_context);

    var joined_context = previous_joined_context;
    joined_context.joined_target_expression_qualifiers = returning_qualifiers;
    joined_context.joined_source_expression_qualifiers = source_qualifiers[0..];
    joined_context.defer_row_expression_field_validation = true;
    options.joined_context_hooks.set_context(options.joined_context_hooks.ptr, joined_context);
    defer options.joined_context_hooks.set_context(options.joined_context_hooks.ptr, previous_joined_context);

    const current_context = options.select_context_hooks.get_context(options.select_context_hooks.ptr);
    return try parseSelectItemAlloc(
        alloc,
        tokens,
        pos,
        options.params,
        current_context.schema,
        options.function_bindings,
        current_context.field_expression_qualifiers,
        current_context.returning_expression_qualifiers,
        current_context.defer_row_expression_field_validation,
        options.field_source,
        options.select_context_hooks.row_expression_type_context(options.select_context_hooks.ptr),
        options.select_item_options,
    );
}

pub const WindowSelectListParserOptions = struct {
    params: []const value_mod.SqlValue = &.{},
    schema: runtime_schema.TableSchema,
    type_context: RowExpressionTypeContext,
    field_expression_qualifiers: []const []const u8 = &.{},
    returning_expression_qualifiers: []const []const u8 = &.{},
    defer_row_expression_field_validation: bool = false,
    named_window_specs: []const plan_mod.NamedWindowSpec = &.{},
    function_bindings: SqlFunctionBindings = .{},
    order_expression_hooks: OrderExpressionParserOptions,
    window_definition_options: WindowDefinitionParserOptions,
    window_spec_options: WindowSpecParserOptions,
    generated_read_ast: ?*const generated_parser.GeneratedSqlReadAst = null,
};

pub fn selectItemStartAt(tokens: []const Token, pos: usize) ?SelectItemStart {
    if (rowExpressionHasTopLevelPipeConcat(tokens, pos)) return .pipe_concat;
    if (peekUnaryNegativeExpressionSyntax(tokens, pos)) return .unary_negative;
    if (peekBooleanNotExpressionSyntax(tokens, pos)) return .boolean_not;
    if (peekFunctionCallTokenIf(tokens, pos, sqlTokenIsUuidV4Function)) return .uuid_v4;
    if (peekSqlNowExpressionSyntax(tokens, pos)) return .now;
    if (peekSqlCurrentDateExpressionSyntax(tokens, pos)) return .current_date;
    if (peekSqlTypedDatetimeLiteral(tokens, pos)) return .typed_datetime_literal;
    if (peekFunctionCallTokenIf(tokens, pos, sqlTokenIsJsonExtractPathFunction)) return .json_extract_path;
    if (peekFunctionCallTokenIf(tokens, pos, sqlTokenIsJsonTypeofFunction)) return .json_typeof;
    if (peekFunctionCallTokenIf(tokens, pos, sqlTokenIsJsonArrayLengthFunction)) return .json_array_length;
    if (peekFunctionCallTokenIf(tokens, pos, sqlTokenIsJsonBuildObjectFunction)) return .json_build_object;
    if (value_mod.peekConvertFromFunctionCall(tokens, pos)) return .convert_from;
    if (value_mod.peekToJsonbFunctionCall(tokens, pos)) return .to_jsonb;
    if (functionCallStartsAtTokenIf(tokens, pos, sqlTokenIsArrayLengthFunction)) return .array_length;
    if (functionCallStartsAtTokenIf(tokens, pos, sqlTokenIsArrayPositionFunction)) return .array_position;
    if (peekArrayElementTransformFunctionCall(tokens, pos)) return .array_element_transform;
    if (peekArrayToStringFunctionCall(tokens, pos)) return .array_to_string;
    if (peekStringToArrayFunctionCall(tokens, pos)) return .string_to_array;
    if (peekCoalesceFunctionCall(tokens, pos)) return .coalesce;
    if (peekCaseFoldFunctionCall(tokens, pos)) return .case_fold;
    if (peekReplaceFunctionCall(tokens, pos)) return .replace;
    if (peekRegexpReplaceFunctionCall(tokens, pos)) return .regexp_replace;
    if (peekFunctionCallTokenIf(tokens, pos, sqlTokenIsRegexpSubstrFunction)) return .regexp_substr;
    if (peekFunctionCallTokenIf(tokens, pos, sqlTokenIsRegexpMatchFunction)) return .regexp_match;
    if (peekFunctionCallTokenIf(tokens, pos, sqlTokenIsRegexpCountFunction)) return .regexp_count;
    if (peekFunctionCallTokenIf(tokens, pos, sqlTokenIsRegexpInstrFunction)) return .regexp_instr;
    if (peekFunctionCallTokenIf(tokens, pos, sqlTokenIsTranslateFunction)) return .translate;
    if (peekConcatFunctionCall(tokens, pos)) return .concat;
    if (peekNullifFunctionCall(tokens, pos)) return .nullif;
    if (peekTextLengthFunctionKeyword(tokens, pos)) return .text_length;
    if (peekFunctionCallTokenIf(tokens, pos, sqlTokenIsAsciiFunction)) return .ascii;
    if (peekFunctionCallTokenIf(tokens, pos, sqlTokenIsChrFunction)) return .chr;
    if (peekSubstringFunctionKeyword(tokens, pos)) return .substring;
    if (peekFunctionCallTokenIf(tokens, pos, sqlTokenIsOverlayFunction)) return .overlay;
    if (peekSplitPartFunctionKeyword(tokens, pos)) return .split_part;
    if (peekStrposFunctionKeyword(tokens, pos) or peekPositionFunctionSyntax(tokens, pos)) return .strpos;
    if (peekFunctionCallTokenIf(tokens, pos, sqlTokenIsLeftRightFunction)) return .left_right;
    if (peekFunctionCallTokenIf(tokens, pos, sqlTokenIsPadFunction)) return .pad;
    if (peekFunctionCallTokenIf(tokens, pos, sqlTokenIsRepeatFunction)) return .repeat;
    if (peekFunctionCallTokenIf(tokens, pos, sqlTokenIsReverseFunction)) return .reverse;
    if (peekFunctionCallTokenIf(tokens, pos, sqlTokenIsMd5Function)) return .md5;
    if (peekFunctionCallTokenIf(tokens, pos, sqlTokenIsStartsWithFunction)) return .starts_with;
    if (peekFunctionCallTokenIf(tokens, pos, sqlTokenIsEndsWithFunction)) return .ends_with;
    if (peekFunctionCallTokenIf(tokens, pos, sqlTokenIsDateTruncFunction)) return .date_trunc;
    if (peekFunctionCallTokenIf(tokens, pos, sqlTokenIsDateBinFunction)) return .date_bin;
    if (peekFunctionCallTokenIf(tokens, pos, sqlTokenIsDatePartFunction)) return .date_part;
    if (peekFixedUnaryFunctionCall(tokens, pos, .abs)) return .abs;
    if (peekFixedUnaryFunctionCall(tokens, pos, .round)) return .round;
    if (peekFixedUnaryFunctionCall(tokens, pos, .trunc)) return .trunc;
    if (peekFixedUnaryFunctionCall(tokens, pos, .floor)) return .floor;
    if (peekFixedUnaryFunctionCall(tokens, pos, .ceil)) return .ceil;
    if (peekFixedUnaryFunctionCall(tokens, pos, .sqrt)) return .sqrt;
    if (peekFixedUnaryFunctionCall(tokens, pos, .sign)) return .sign;
    if (peekFixedBinaryFunctionCall(tokens, pos, .mod)) return .mod;
    if (peekFixedBinaryFunctionCall(tokens, pos, .power)) return .power;
    if (peekGreatestLeastFunctionCall(tokens, pos)) return .greatest_least;
    if (peekCaseExpressionSyntax(tokens, pos)) return .case;
    if (peekCastExpressionSyntax(tokens, pos)) return .cast;
    if (peekParenthesizedExpressionSyntax(tokens, pos)) return .parenthesized;
    return null;
}

pub fn selectItemStartWithFunctionBindingsAt(tokens: []const Token, pos: usize, bindings: SqlFunctionBindings) ?SelectItemStart {
    if (selectItemStartAt(tokens, pos)) |start| return start;
    if (peekExtensionFunctionCall(tokens, pos, bindings.extension_functions)) return .extension_function;
    if (peekRoutineExpressionCall(tokens, pos, bindings.routine_expressions)) return .routine_expression;
    return null;
}

pub fn parseSelectListAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    options: SelectListParserOptions,
) !plan_mod.SelectList {
    var select_all = false;
    var fields = std.ArrayListUnmanaged([]const u8).empty;
    errdefer {
        for (fields.items) |field| alloc.free(field);
        fields.deinit(alloc);
    }
    var json_extract = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonExtractProjection).empty;
    errdefer {
        for (json_extract.items) |projection| {
            alloc.free(projection.output);
            alloc.free(projection.field);
            alloc.free(projection.path);
        }
        json_extract.deinit(alloc);
    }
    var array_length = std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayLengthProjection).empty;
    errdefer {
        for (array_length.items) |projection| {
            alloc.free(projection.output);
            alloc.free(projection.field);
        }
        array_length.deinit(alloc);
    }
    var coalesce = std.ArrayListUnmanaged(db_mod.types.RelationalRowsCoalesceProjection).empty;
    errdefer {
        for (coalesce.items) |projection| plan_mod.freeCoalesceProjection(alloc, projection);
        coalesce.deinit(alloc);
    }
    var expressions = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionProjection).empty;
    errdefer {
        for (expressions.items) |projection| freeExpressionProjection(alloc, projection);
        expressions.deinit(alloc);
    }
    var field_aliases = std.ArrayListUnmanaged(db_mod.types.RelationalRowsFieldAliasProjection).empty;
    errdefer {
        for (field_aliases.items) |projection| {
            alloc.free(projection.output);
            alloc.free(projection.field);
        }
        field_aliases.deinit(alloc);
    }
    var outputs = std.ArrayListUnmanaged(ast.SelectOutputRef).empty;
    errdefer outputs.deinit(alloc);

    while (true) {
        if (parser.matchToken(tokens, pos, .star) != null) {
            if (select_all or
                fields.items.len != 0 or
                json_extract.items.len != 0 or
                array_length.items.len != 0 or
                coalesce.items.len != 0 or
                field_aliases.items.len != 0 or
                expressions.items.len != 0) return error.UnsupportedSqlShape;
            select_all = true;
            if (parser.matchToken(tokens, pos, .comma) == null) break;
            continue;
        }

        const item_start = pos.*;
        const generated_expression = try generatedProjectionExpressionAtItemStart(item_start, options.generated_read_ast);
        if (generated_expression == null and options.generated_read_ast != null) return error.UnsupportedSqlShape;
        var select_item_options = options.select_item_options;
        select_item_options.generated_expression_ast = generated_expression;
        const item = try parseSelectItemAlloc(
            alloc,
            tokens,
            pos,
            options.params,
            options.select_item_schema,
            options.function_bindings,
            options.field_expression_qualifiers,
            options.returning_expression_qualifiers,
            options.defer_row_expression_field_validation,
            options.field_source,
            options.type_context,
            select_item_options,
        );
        var item_transferred = false;
        errdefer if (!item_transferred) plan_mod.freeSelectItem(alloc, item);
        switch (item) {
            .field => |field| {
                item_transferred = true;
                var field_transferred = false;
                errdefer if (!field_transferred) alloc.free(field);
                if (select_all) {
                    var output: []const u8 = try alloc.dupe(u8, field);
                    var output_transferred = false;
                    errdefer if (!output_transferred) alloc.free(output);
                    try disambiguateSelectProjectionOutputIfNeededAlloc(
                        alloc,
                        options.output_schema,
                        select_all,
                        fields.items,
                        json_extract.items,
                        array_length.items,
                        coalesce.items,
                        field_aliases.items,
                        expressions.items,
                        &output,
                    );
                    try outputs.append(alloc, .{ .kind = .field_alias, .index = field_aliases.items.len });
                    try field_aliases.append(alloc, .{ .field = field, .output = output });
                    field_transferred = true;
                    output_transferred = true;
                } else {
                    try outputs.append(alloc, .{ .kind = .field, .index = fields.items.len });
                    try fields.append(alloc, field);
                    field_transferred = true;
                }
            },
            .json_extract => |projection_value| {
                item_transferred = true;
                var projection = projection_value;
                var projection_transferred = false;
                errdefer if (!projection_transferred) {
                    alloc.free(projection.output);
                    alloc.free(projection.field);
                    alloc.free(projection.path);
                };
                try disambiguateSelectProjectionOutputIfNeededAlloc(
                    alloc,
                    options.output_schema,
                    select_all,
                    fields.items,
                    json_extract.items,
                    array_length.items,
                    coalesce.items,
                    field_aliases.items,
                    expressions.items,
                    &projection.output,
                );
                try outputs.append(alloc, .{ .kind = .json_extract, .index = json_extract.items.len });
                try json_extract.append(alloc, projection);
                projection_transferred = true;
            },
            .array_length => |projection_value| {
                item_transferred = true;
                var projection = projection_value;
                var projection_transferred = false;
                errdefer if (!projection_transferred) {
                    alloc.free(projection.output);
                    alloc.free(projection.field);
                };
                try disambiguateSelectProjectionOutputIfNeededAlloc(
                    alloc,
                    options.output_schema,
                    select_all,
                    fields.items,
                    json_extract.items,
                    array_length.items,
                    coalesce.items,
                    field_aliases.items,
                    expressions.items,
                    &projection.output,
                );
                try outputs.append(alloc, .{ .kind = .array_length, .index = array_length.items.len });
                try array_length.append(alloc, projection);
                projection_transferred = true;
            },
            .coalesce => |projection_value| {
                item_transferred = true;
                var projection = projection_value;
                var projection_transferred = false;
                errdefer if (!projection_transferred) plan_mod.freeCoalesceProjection(alloc, projection);
                try disambiguateSelectProjectionOutputIfNeededAlloc(
                    alloc,
                    options.output_schema,
                    select_all,
                    fields.items,
                    json_extract.items,
                    array_length.items,
                    coalesce.items,
                    field_aliases.items,
                    expressions.items,
                    &projection.output,
                );
                const expression_projection = try plan_mod.expressionProjectionFromCoalesceAlloc(alloc, projection);
                var expression_projection_transferred = false;
                errdefer if (!expression_projection_transferred) freeExpressionProjection(alloc, expression_projection);
                try outputs.append(alloc, .{ .kind = .coalesce, .index = coalesce.items.len });
                try expressions.append(alloc, expression_projection);
                expression_projection_transferred = true;
                try coalesce.append(alloc, projection);
                projection_transferred = true;
            },
            .expression => |projection_value| {
                item_transferred = true;
                var projection = projection_value;
                var projection_transferred = false;
                errdefer if (!projection_transferred) freeExpressionProjection(alloc, projection);
                try disambiguateSelectProjectionOutputIfNeededAlloc(
                    alloc,
                    options.output_schema,
                    select_all,
                    fields.items,
                    json_extract.items,
                    array_length.items,
                    coalesce.items,
                    field_aliases.items,
                    expressions.items,
                    &projection.output,
                );
                try outputs.append(alloc, .{ .kind = .expression, .index = expressions.items.len });
                try expressions.append(alloc, projection);
                projection_transferred = true;
            },
            .field_alias => |projection_value| {
                item_transferred = true;
                var projection = projection_value;
                var projection_transferred = false;
                errdefer if (!projection_transferred) {
                    alloc.free(projection.output);
                    alloc.free(projection.field);
                };
                try disambiguateSelectProjectionOutputIfNeededAlloc(
                    alloc,
                    options.output_schema,
                    select_all,
                    fields.items,
                    json_extract.items,
                    array_length.items,
                    coalesce.items,
                    field_aliases.items,
                    expressions.items,
                    &projection.output,
                );
                try outputs.append(alloc, .{ .kind = .field_alias, .index = field_aliases.items.len });
                try field_aliases.append(alloc, projection);
                projection_transferred = true;
            },
        }
        item_transferred = true;
        if (parser.matchToken(tokens, pos, .comma) == null) break;
    }

    try validateSelectListOutputs(
        options.output_schema,
        select_all,
        fields.items,
        json_extract.items,
        array_length.items,
        coalesce.items,
        field_aliases.items,
        expressions.items,
    );

    const owned_fields = try fields.toOwnedSlice(alloc);
    var fields_transferred = false;
    errdefer if (!fields_transferred) strings.freeStringSlice(alloc, owned_fields);
    const owned_json_extract = try json_extract.toOwnedSlice(alloc);
    var json_extract_transferred = false;
    errdefer if (!json_extract_transferred) plan_mod.freeJsonExtract(alloc, owned_json_extract);
    const owned_array_length = try array_length.toOwnedSlice(alloc);
    var array_length_transferred = false;
    errdefer if (!array_length_transferred) plan_mod.freeArrayLengthProjections(alloc, owned_array_length);
    const owned_coalesce = try coalesce.toOwnedSlice(alloc);
    var coalesce_transferred = false;
    errdefer if (!coalesce_transferred) plan_mod.freeCoalesceProjections(alloc, owned_coalesce);
    const owned_field_aliases = try field_aliases.toOwnedSlice(alloc);
    var field_aliases_transferred = false;
    errdefer if (!field_aliases_transferred) plan_mod.freeFieldAliasProjections(alloc, owned_field_aliases);
    const owned_expressions = try expressions.toOwnedSlice(alloc);
    var expressions_transferred = false;
    errdefer if (!expressions_transferred) freeExpressionProjections(alloc, owned_expressions);
    const owned_outputs = try outputs.toOwnedSlice(alloc);

    fields_transferred = true;
    json_extract_transferred = true;
    array_length_transferred = true;
    coalesce_transferred = true;
    field_aliases_transferred = true;
    expressions_transferred = true;
    return .{
        .fields = owned_fields,
        .json_extract = owned_json_extract,
        .array_length = owned_array_length,
        .coalesce = owned_coalesce,
        .field_aliases = owned_field_aliases,
        .expressions = owned_expressions,
        .outputs = owned_outputs,
        .select_all = select_all,
    };
}

fn windowSpecOutputCollision(
    output: []const u8,
    fields: []const []const u8,
    windows: []const db_mod.types.RelationalRowsWindowSpec,
) bool {
    for (fields) |field| {
        if (std.mem.eql(u8, field, output)) return true;
    }
    for (windows) |window| {
        if (std.mem.eql(u8, window.output, output)) return true;
    }
    return false;
}

fn allocateDisambiguatedWindowSpecOutputAlloc(
    alloc: std.mem.Allocator,
    output: []const u8,
    fields: []const []const u8,
    windows: []const db_mod.types.RelationalRowsWindowSpec,
) !?[]const u8 {
    if (!windowSpecOutputCollision(output, fields, windows)) return null;

    var suffix: usize = 2;
    while (true) : (suffix += 1) {
        const candidate = try std.fmt.allocPrint(alloc, "{s}_{d}", .{ output, suffix });
        if (!windowSpecOutputCollision(candidate, fields, windows)) return candidate;
        alloc.free(candidate);
    }
}

fn windowSpecWithOutput(
    spec: db_mod.types.RelationalRowsWindowSpec,
    output: []const u8,
) db_mod.types.RelationalRowsWindowSpec {
    return .{
        .output = output,
        .function = spec.function,
        .partition_by = spec.partition_by,
        .order_by = spec.order_by,
        .value_expression = spec.value_expression,
        .offset = spec.offset,
        .default_json = spec.default_json,
        .frame = spec.frame,
        .filter_predicates = spec.filter_predicates,
        .filter_array_any = spec.filter_array_any,
        .filter_array_contains = spec.filter_array_contains,
        .filter_array_eq = spec.filter_array_eq,
        .filter_in_predicates = spec.filter_in_predicates,
        .filter_json_contains = spec.filter_json_contains,
        .filter_json_path_eq = spec.filter_json_path_eq,
        .filter_json_path_exists = spec.filter_json_path_exists,
        .filter_text_patterns = spec.filter_text_patterns,
        .filter_expressions = spec.filter_expressions,
        .filter_expression_array_contains = spec.filter_expression_array_contains,
        .filter_any = spec.filter_any,
        .filter_not = spec.filter_not,
    };
}

pub fn parseWindowSelectListAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    options: WindowSelectListParserOptions,
) !plan_mod.WindowSelectList {
    if (parser.matchToken(tokens, pos, .star) != null) return error.UnsupportedSqlShape;

    var fields = std.ArrayListUnmanaged([]const u8).empty;
    errdefer {
        for (fields.items) |field| alloc.free(field);
        fields.deinit(alloc);
    }
    var windows = std.ArrayListUnmanaged(db_mod.types.RelationalRowsWindowSpec).empty;
    errdefer {
        plan_mod.freeWindowSpecs(alloc, windows.items);
        windows.deinit(alloc);
    }
    var outputs = std.ArrayListUnmanaged(plan_mod.WindowSelectOutputRef).empty;
    errdefer outputs.deinit(alloc);

    while (true) {
        if (peekWindowFunction(tokens, pos.*)) {
            const item_start = pos.*;
            const generated_expression = try generatedProjectionExpressionAtItemStart(item_start, options.generated_read_ast);
            if (generated_expression == null and options.generated_read_ast != null) return error.UnsupportedSqlShape;
            var window_spec_options = options.window_spec_options;
            window_spec_options.generated_expression_ast = generated_expression;
            const parsed_spec = try parseWindowSpecAlloc(
                alloc,
                tokens,
                pos,
                options.params,
                options.schema,
                options.field_expression_qualifiers,
                options.returning_expression_qualifiers,
                options.defer_row_expression_field_validation,
                options.type_context,
                options.named_window_specs,
                options.window_definition_options,
                window_spec_options,
            );
            var parsed_spec_transferred = false;
            errdefer if (!parsed_spec_transferred) plan_mod.freeWindowSpec(alloc, parsed_spec);
            const maybe_output = try allocateDisambiguatedWindowSpecOutputAlloc(
                alloc,
                parsed_spec.output,
                fields.items,
                windows.items,
            );
            var output_transferred = false;
            errdefer if (!output_transferred) {
                if (maybe_output) |output| alloc.free(output);
            };
            const spec = if (maybe_output) |output| windowSpecWithOutput(parsed_spec, output) else parsed_spec;
            parsed_spec_transferred = true;
            if (maybe_output != null) {
                alloc.free(parsed_spec.output);
                output_transferred = true;
            }
            var spec_transferred = false;
            errdefer if (!spec_transferred) plan_mod.freeWindowSpec(alloc, spec);
            try outputs.append(alloc, .{ .kind = .window, .index = windows.items.len });
            try windows.append(alloc, spec);
            spec_transferred = true;
        } else {
            const item_start = pos.*;
            const generated_expression = try generatedProjectionExpressionAtItemStart(item_start, options.generated_read_ast);
            if (generated_expression == null and options.generated_read_ast != null) return error.UnsupportedSqlShape;
            if (generated_expression) |expression| {
                if (expression.kind != .token_range) return error.UnsupportedSqlShape;
            }
            const parsed_field = try parseRowExpressionFieldOwnedAlloc(
                alloc,
                tokens,
                pos,
                options.schema,
                options.field_expression_qualifiers,
                options.returning_expression_qualifiers,
                options.defer_row_expression_field_validation,
            );
            defer alloc.free(parsed_field);
            const field = try binder.normalizeRowExpressionFieldAlloc(
                alloc,
                options.schema,
                parsed_field,
                options.field_expression_qualifiers,
                options.returning_expression_qualifiers,
                options.defer_row_expression_field_validation,
            );
            var field_transferred = false;
            errdefer if (!field_transferred) alloc.free(field);
            if (peekUnsupportedSimpleFieldTail(tokens, pos.*)) return error.UnsupportedSqlShape;
            if (binder.relationalColumnForField(options.schema, field, null) == null) return error.InvalidSqlCatalog;
            try grammar.consumeProjectionAlias(alloc, tokens, pos, field);
            try outputs.append(alloc, .{ .kind = .field, .index = fields.items.len });
            try fields.append(alloc, field);
            field_transferred = true;
        }
        if (parser.matchToken(tokens, pos, .comma) == null) break;
    }

    try validateWindowSelectListOutputs(fields.items, windows.items);

    const owned_fields = try fields.toOwnedSlice(alloc);
    var fields_transferred = false;
    errdefer if (!fields_transferred) strings.freeStringSlice(alloc, owned_fields);
    const owned_windows = try windows.toOwnedSlice(alloc);
    var windows_transferred = false;
    errdefer if (!windows_transferred) {
        plan_mod.freeWindowSpecs(alloc, owned_windows);
        if (owned_windows.len > 0) alloc.free(owned_windows);
    };
    const owned_outputs = try outputs.toOwnedSlice(alloc);

    fields_transferred = true;
    windows_transferred = true;
    return .{
        .fields = owned_fields,
        .windows = owned_windows,
        .outputs = owned_outputs,
        .select_all = false,
    };
}

pub fn parseSelectItemAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    params: []const value_mod.SqlValue,
    schema: runtime_schema.TableSchema,
    function_bindings: SqlFunctionBindings,
    field_expression_qualifiers: []const []const u8,
    returning_expression_qualifiers: []const []const u8,
    defer_row_expression_field_validation: bool,
    field_source: db_mod.types.RelationalRowsExpressionFieldSource,
    type_context: RowExpressionTypeContext,
    options: SelectItemParserOptions,
) !plan_mod.SelectItem {
    if (selectItemStartWithFunctionBindingsAt(tokens, pos.*, function_bindings)) |start| {
        try validateGeneratedSelectItemStartForExpression(start, options.generated_expression_ast);
        switch (start) {
            .pipe_concat => return .{ .expression = try parseTextExpressionProjectionAlloc(alloc, tokens, pos, type_context, options.expression) },
            .unary_negative => return .{ .expression = try parseGenericExpressionProjectionAlloc(alloc, tokens, pos, type_context, options.expression) },
            .boolean_not => return .{ .expression = try parseBooleanExpressionProjectionAlloc(alloc, tokens, pos, type_context, options.expression) },
            .extension_function => return .{ .expression = try parseExtensionFunctionExpressionProjectionAlloc(alloc, tokens, pos, function_bindings.extension_functions, options.extension_function) },
            .routine_expression => return .{ .expression = try parseRoutineExpressionProjectionAlloc(alloc, tokens, pos, function_bindings.routine_expressions, options.routine_expression) },
            .uuid_v4 => return .{ .expression = try parseUuidV4ExpressionProjectionAlloc(alloc, tokens, pos) },
            .now => return .{ .expression = try parseNowExpressionProjectionAlloc(alloc, tokens, pos) },
            .current_date => return .{ .expression = try parseCurrentDateExpressionProjectionAlloc(alloc, tokens, pos) },
            .typed_datetime_literal => return .{ .expression = try parseTypedDatetimeLiteralExpressionProjectionAlloc(alloc, tokens, pos) },
            .json_extract_path => return .{ .expression = try parseJsonExtractPathExpressionProjectionAlloc(alloc, tokens, pos, options.expression) },
            .json_typeof => return .{ .expression = try parseFixedOutputExpressionProjectionAlloc(alloc, tokens, pos, "json_typeof", options.expression) },
            .json_array_length => return .{ .expression = try parseFixedOutputExpressionProjectionAlloc(alloc, tokens, pos, "json_array_length", options.expression) },
            .json_build_object => return .{ .expression = try parseFixedOutputExpressionProjectionAlloc(alloc, tokens, pos, "jsonb_build_object", options.expression) },
            .convert_from => return .{ .expression = try parseJsonValueExpressionProjectionAlloc(alloc, tokens, pos, "convert_from", options.json_value_expression) },
            .to_jsonb => return .{ .expression = try parseFixedOutputExpressionProjectionAlloc(alloc, tokens, pos, "to_jsonb", options.expression) },
            .array_length => return .{ .expression = try parseArrayLengthExpressionProjectionAlloc(alloc, tokens, pos, params, schema, field_expression_qualifiers, returning_expression_qualifiers, defer_row_expression_field_validation, field_source) },
            .array_position => return .{ .expression = try parseOpOutputExpressionProjectionAlloc(alloc, tokens, pos, options.expression) },
            .array_element_transform => return .{ .expression = try parseOpOutputExpressionProjectionAlloc(alloc, tokens, pos, options.expression) },
            .array_to_string => return .{ .expression = try parseFixedOutputExpressionProjectionAlloc(alloc, tokens, pos, "array_to_string", options.expression) },
            .string_to_array => return .{ .expression = try parseFixedOutputExpressionProjectionAlloc(alloc, tokens, pos, "string_to_array", options.expression) },
            .coalesce => return .{ .expression = try parseFixedOutputExpressionProjectionAlloc(alloc, tokens, pos, "coalesce", options.expression) },
            .case_fold => return .{ .expression = try parseDefaultOutputExpressionProjectionAlloc(alloc, tokens, pos, options.expression) },
            .replace => return .{ .expression = try parseFixedOutputExpressionProjectionAlloc(alloc, tokens, pos, "replace", options.expression) },
            .regexp_replace => return .{ .expression = try parseFixedOutputExpressionProjectionAlloc(alloc, tokens, pos, "regexp_replace", options.expression) },
            .regexp_substr => return .{ .expression = try parseFixedOutputExpressionProjectionAlloc(alloc, tokens, pos, "regexp_substr", options.expression) },
            .regexp_match => return .{ .expression = try parseRegexpMatchExpressionProjectionAlloc(alloc, tokens, pos, options.expression) },
            .regexp_count => return .{ .expression = try parseFixedOutputExpressionProjectionAlloc(alloc, tokens, pos, "regexp_count", options.expression) },
            .regexp_instr => return .{ .expression = try parseFixedOutputExpressionProjectionAlloc(alloc, tokens, pos, "regexp_instr", options.expression) },
            .translate => return .{ .expression = try parseFixedOutputExpressionProjectionAlloc(alloc, tokens, pos, "translate", options.expression) },
            .concat => return .{ .expression = try parseOpOutputExpressionProjectionAlloc(alloc, tokens, pos, options.expression) },
            .nullif => return .{ .expression = try parseFixedOutputExpressionProjectionAlloc(alloc, tokens, pos, "nullif", options.expression) },
            .text_length => return .{ .expression = try parseFixedOutputExpressionProjectionAlloc(alloc, tokens, pos, "length", options.expression) },
            .ascii => return .{ .expression = try parseOpOutputExpressionProjectionAlloc(alloc, tokens, pos, options.expression) },
            .chr => return .{ .expression = try parseOpOutputExpressionProjectionAlloc(alloc, tokens, pos, options.expression) },
            .substring => return .{ .expression = try parseOpOutputExpressionProjectionAlloc(alloc, tokens, pos, options.expression) },
            .overlay => return .{ .expression = try parseOpOutputExpressionProjectionAlloc(alloc, tokens, pos, options.expression) },
            .split_part => return .{ .expression = try parseOpOutputExpressionProjectionAlloc(alloc, tokens, pos, options.expression) },
            .strpos => return .{ .expression = try parseOpOutputExpressionProjectionAlloc(alloc, tokens, pos, options.expression) },
            .left_right => return .{ .expression = try parseOpOutputExpressionProjectionAlloc(alloc, tokens, pos, options.expression) },
            .pad => return .{ .expression = try parseOpOutputExpressionProjectionAlloc(alloc, tokens, pos, options.expression) },
            .repeat => return .{ .expression = try parseOpOutputExpressionProjectionAlloc(alloc, tokens, pos, options.expression) },
            .reverse => return .{ .expression = try parseOpOutputExpressionProjectionAlloc(alloc, tokens, pos, options.expression) },
            .md5 => return .{ .expression = try parseOpOutputExpressionProjectionAlloc(alloc, tokens, pos, options.expression) },
            .starts_with => return .{ .expression = try parseOpOutputExpressionProjectionAlloc(alloc, tokens, pos, options.expression) },
            .ends_with => return .{ .expression = try parseOpOutputExpressionProjectionAlloc(alloc, tokens, pos, options.expression) },
            .date_trunc => return .{ .expression = try parseOpOutputExpressionProjectionAlloc(alloc, tokens, pos, options.expression) },
            .date_bin => return .{ .expression = try parseOpOutputExpressionProjectionAlloc(alloc, tokens, pos, options.expression) },
            .date_part => return .{ .expression = try parseOpOutputExpressionProjectionAlloc(alloc, tokens, pos, options.expression) },
            .abs => return .{ .expression = try parseFixedOutputExpressionProjectionAlloc(alloc, tokens, pos, "abs", options.expression) },
            .round => return .{ .expression = try parseFixedOutputExpressionProjectionAlloc(alloc, tokens, pos, "round", options.expression) },
            .trunc, .floor, .ceil, .sqrt, .sign => return .{ .expression = try parseOpOutputExpressionProjectionAlloc(alloc, tokens, pos, options.expression) },
            .mod => return .{ .expression = try parseFixedOutputExpressionProjectionAlloc(alloc, tokens, pos, "mod", options.expression) },
            .power => return .{ .expression = try parseFixedOutputExpressionProjectionAlloc(alloc, tokens, pos, "power", options.expression) },
            .greatest_least => return .{ .expression = try parseOpOutputExpressionProjectionAlloc(alloc, tokens, pos, options.expression) },
            .case => return .{ .expression = try parseFixedOutputExpressionProjectionAlloc(alloc, tokens, pos, "case", options.expression) },
            .cast => return .{ .expression = try parseFixedOutputExpressionProjectionAlloc(alloc, tokens, pos, "cast", options.expression) },
            .parenthesized => {
                if (peekParenthesizedNullTestProjection(tokens, pos.*)) {
                    return .{ .expression = try parseParenthesizedNullTestExpressionProjectionAlloc(alloc, tokens, pos, schema, field_expression_qualifiers, returning_expression_qualifiers, defer_row_expression_field_validation, field_source) };
                }
                return .{ .expression = try parseParenthesizedExpressionProjectionAlloc(alloc, tokens, pos, options.expression) };
            },
        }
    }

    return try parseSelectFieldItemAlloc(
        alloc,
        tokens,
        pos,
        schema,
        params,
        field_expression_qualifiers,
        returning_expression_qualifiers,
        defer_row_expression_field_validation,
        field_source,
        options.select_field,
    );
}

pub fn parseSelectFieldItemAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    schema: runtime_schema.TableSchema,
    params: []const value_mod.SqlValue,
    field_expression_qualifiers: []const []const u8,
    returning_expression_qualifiers: []const []const u8,
    defer_row_expression_field_validation: bool,
    field_source: db_mod.types.RelationalRowsExpressionFieldSource,
    options: SelectFieldItemParserOptions,
) !plan_mod.SelectItem {
    const parsed_field = try parseRowExpressionFieldOwnedAlloc(alloc, tokens, pos, schema, field_expression_qualifiers, returning_expression_qualifiers, defer_row_expression_field_validation);
    defer alloc.free(parsed_field);
    const field = try binder.normalizeRowExpressionFieldAlloc(alloc, schema, parsed_field, field_expression_qualifiers, returning_expression_qualifiers, defer_row_expression_field_validation);
    var field_owned = true;
    errdefer if (field_owned) alloc.free(field);
    if (parser.peekKind(tokens, pos.*, .lparen)) return error.UnsupportedSqlShape;
    if (matchJsonExtractOperator(tokens, pos)) |operator| {
        const as_text = tokenKindIsJsonExtractTextOperator(operator);
        if (binder.relationalColumnForField(schema, field, .json) == null) return error.InvalidSqlCatalog;
        const path = try value_mod.parseJsonExtractOperatorPathOwnedAlloc(alloc, tokens, pos, params, operator);
        var path_owned = true;
        errdefer if (path_owned) alloc.free(path);
        const output = try grammar.parseProjectionOutputOwnedAlloc(alloc, tokens, pos, path);
        var output_owned = true;
        errdefer if (output_owned) alloc.free(output);
        const expression = try buildJsonExtractExpressionAlloc(
            alloc,
            .{ .kind = .field, .field = field, .field_source = field_source },
            path,
            as_text,
        );
        errdefer freeExpression(alloc, expression);
        field_owned = false;
        path_owned = false;
        output_owned = false;
        return .{ .expression = buildExpressionProjection(output, expression) };
    }
    if (parser.matchToken(tokens, pos, .question) != null) {
        if (binder.relationalColumnForField(schema, field, .json) == null) return error.InvalidSqlCatalog;
        const path = try value_mod.parseJsonPathOwnedAlloc(alloc, tokens, pos, params);
        var path_owned = true;
        errdefer if (path_owned) alloc.free(path);
        const output = try grammar.parseProjectionOutputOwnedAlloc(alloc, tokens, pos, path);
        var output_owned = true;
        errdefer if (output_owned) alloc.free(output);
        const expression = try buildJsonPathExistsExpressionAlloc(
            alloc,
            .{ .kind = .field, .field = field, .field_source = field_source },
            path,
        );
        errdefer freeExpression(alloc, expression);
        field_owned = false;
        path_owned = false;
        output_owned = false;
        return .{ .expression = buildExpressionProjection(output, expression) };
    }
    if (parser.matchToken(tokens, pos, .question_any) != null or parser.matchToken(tokens, pos, .question_all) != null) {
        const match_all = tokens[pos.* - 1].kind == .question_all;
        if (binder.relationalColumnForField(schema, field, .json) == null) return error.InvalidSqlCatalog;
        const values_json = try value_mod.parseJsonArrayValueAlloc(alloc, tokens, pos, params);
        defer alloc.free(values_json);
        const expression = try buildJsonKeySetExistsExpressionAlloc(alloc, field, field_source, match_all, values_json);
        errdefer freeExpression(alloc, expression);
        const output = try grammar.parseProjectionOutputOwnedAlloc(alloc, tokens, pos, if (match_all) "json_keys_all" else "json_keys_any");
        var output_owned = true;
        errdefer if (output_owned) alloc.free(output);
        output_owned = false;
        alloc.free(field);
        field_owned = false;
        return .{ .expression = buildExpressionProjection(output, expression) };
    }
    const column = binder.relationalColumnForField(schema, field, null) orelse return error.InvalidSqlCatalog;
    if (peekArithmeticOperator(tokens, pos.*)) |_| {
        if (column.field_type != .numeric and column.field_type != .datetime) return error.InvalidSqlCatalog;
        field_owned = false;
        return .{ .expression = try parseArithmeticExpressionProjectionFromFieldAlloc(alloc, tokens, pos, field, field_source, options.type_context, options.arithmetic_hooks) };
    }
    if (peekBooleanOperator(tokens, pos.*)) |_| {
        if (column.field_type != .boolean) return error.InvalidSqlCatalog;
        field_owned = false;
        return .{ .expression = try parseBooleanExpressionProjectionFromFieldAlloc(alloc, tokens, pos, field, field_source, options.type_context, options.boolean_hooks) };
    }
    const alias = try grammar.parseOptionalProjectionAliasAlloc(alloc, tokens, pos);
    var alias_transferred = false;
    errdefer if (!alias_transferred) if (alias) |owned| alloc.free(owned);
    if (alias) |output| {
        if (!std.mem.eql(u8, output, field)) {
            alias_transferred = true;
            field_owned = false;
            return .{ .expression = .{
                .output = output,
                .expression = .{
                    .kind = .field,
                    .field = field,
                    .field_source = field_source,
                },
            } };
        }
        alloc.free(output);
        alias_transferred = true;
    }
    field_owned = false;
    return .{ .field = field };
}

pub const RowExpressionOperandStart = enum {
    parenthesized,
    unary_negative,
    boolean_not,
    extension_function,
    routine_expression,
    cast,
    case,
    now,
    current_date,
    typed_datetime_literal,
    uuid_v4,
    interval,
    case_fold,
    replace,
    regexp_replace,
    regexp_substr,
    regexp_match,
    regexp_count,
    regexp_instr,
    translate,
    concat,
    coalesce,
    nullif,
    text_length,
    ascii,
    chr,
    substring,
    overlay,
    split_part,
    strpos,
    left_right,
    pad,
    repeat,
    reverse,
    md5,
    starts_with,
    ends_with,
    date_trunc,
    date_bin,
    date_part,
    abs,
    round,
    trunc,
    floor,
    ceil,
    sqrt,
    sign,
    mod,
    power,
    greatest_least,
    json_extract_path,
    json_typeof,
    json_array_length,
    json_build_object,
    to_jsonb,
    convert_from,
    array_length,
    array_position,
    array_element_transform,
    array_to_string,
    string_to_array,
};

pub const RowExpressionOperandParserOptions = struct {
    extension_function: ExtensionFunctionRowExpressionParserOptions,
    routine_expression: RoutineExpressionRowExpressionParserOptions,
    parenthesized: ParenthesizedRowExpressionParserOptions,
    cast: CastRowExpressionParserOptions,
    case_expression: CaseExpressionParserHooks,
    case_fold: CaseFoldRowExpressionParserOptions,
    coalesce: CoalesceRowExpressionParserOptions,
    fixed_unary: FixedUnaryRowExpressionParserOptions,
    fixed_binary: FixedBinaryRowExpressionParserOptions,
    variadic: VariadicRowExpressionParserHooks,
    json_build_object: JsonBuildObjectRowExpressionParserOptions,
};

pub fn rowExpressionOperandStartAt(tokens: []const Token, pos: usize) ?RowExpressionOperandStart {
    if (peekParenthesizedExpressionSyntax(tokens, pos)) return .parenthesized;
    if (peekUnaryNegativeExpressionSyntax(tokens, pos)) return .unary_negative;
    if (peekBooleanNotExpressionSyntax(tokens, pos)) return .boolean_not;
    if (peekCastExpressionSyntax(tokens, pos)) return .cast;
    if (peekCaseExpressionSyntax(tokens, pos)) return .case;
    if (peekSqlNowExpressionSyntax(tokens, pos)) return .now;
    if (peekSqlCurrentDateExpressionSyntax(tokens, pos)) return .current_date;
    if (peekSqlTypedDatetimeLiteral(tokens, pos)) return .typed_datetime_literal;
    if (peekFunctionCallTokenIf(tokens, pos, sqlTokenIsUuidV4Function)) return .uuid_v4;
    if (peekSqlIntervalExpressionSyntax(tokens, pos)) return .interval;
    if (peekCaseFoldFunctionCall(tokens, pos)) return .case_fold;
    if (peekReplaceFunctionCall(tokens, pos)) return .replace;
    if (peekRegexpReplaceFunctionCall(tokens, pos)) return .regexp_replace;
    if (peekFunctionCallTokenIf(tokens, pos, sqlTokenIsRegexpSubstrFunction)) return .regexp_substr;
    if (peekFunctionCallTokenIf(tokens, pos, sqlTokenIsRegexpMatchFunction)) return .regexp_match;
    if (peekFunctionCallTokenIf(tokens, pos, sqlTokenIsRegexpCountFunction)) return .regexp_count;
    if (peekFunctionCallTokenIf(tokens, pos, sqlTokenIsRegexpInstrFunction)) return .regexp_instr;
    if (peekFunctionCallTokenIf(tokens, pos, sqlTokenIsTranslateFunction)) return .translate;
    if (peekConcatFunctionCall(tokens, pos)) return .concat;
    if (peekCoalesceFunctionCall(tokens, pos)) return .coalesce;
    if (peekNullifFunctionCall(tokens, pos)) return .nullif;
    if (peekTextLengthFunctionKeyword(tokens, pos)) return .text_length;
    if (peekFunctionCallTokenIf(tokens, pos, sqlTokenIsAsciiFunction)) return .ascii;
    if (peekFunctionCallTokenIf(tokens, pos, sqlTokenIsChrFunction)) return .chr;
    if (peekSubstringFunctionKeyword(tokens, pos)) return .substring;
    if (peekFunctionCallTokenIf(tokens, pos, sqlTokenIsOverlayFunction)) return .overlay;
    if (peekSplitPartFunctionKeyword(tokens, pos)) return .split_part;
    if (peekStrposFunctionKeyword(tokens, pos) or peekPositionFunctionSyntax(tokens, pos)) return .strpos;
    if (peekFunctionCallTokenIf(tokens, pos, sqlTokenIsLeftRightFunction)) return .left_right;
    if (peekFunctionCallTokenIf(tokens, pos, sqlTokenIsPadFunction)) return .pad;
    if (peekFunctionCallTokenIf(tokens, pos, sqlTokenIsRepeatFunction)) return .repeat;
    if (peekFunctionCallTokenIf(tokens, pos, sqlTokenIsReverseFunction)) return .reverse;
    if (peekFunctionCallTokenIf(tokens, pos, sqlTokenIsMd5Function)) return .md5;
    if (peekFunctionCallTokenIf(tokens, pos, sqlTokenIsStartsWithFunction)) return .starts_with;
    if (peekFunctionCallTokenIf(tokens, pos, sqlTokenIsEndsWithFunction)) return .ends_with;
    if (peekFunctionCallTokenIf(tokens, pos, sqlTokenIsDateTruncFunction)) return .date_trunc;
    if (peekFunctionCallTokenIf(tokens, pos, sqlTokenIsDateBinFunction)) return .date_bin;
    if (peekFunctionCallTokenIf(tokens, pos, sqlTokenIsDatePartFunction)) return .date_part;
    if (peekFixedUnaryFunctionCall(tokens, pos, .abs)) return .abs;
    if (peekFixedUnaryFunctionCall(tokens, pos, .round)) return .round;
    if (peekFixedUnaryFunctionCall(tokens, pos, .trunc)) return .trunc;
    if (peekFixedUnaryFunctionCall(tokens, pos, .floor)) return .floor;
    if (peekFixedUnaryFunctionCall(tokens, pos, .ceil)) return .ceil;
    if (peekFixedUnaryFunctionCall(tokens, pos, .sqrt)) return .sqrt;
    if (peekFixedUnaryFunctionCall(tokens, pos, .sign)) return .sign;
    if (peekFixedBinaryFunctionCall(tokens, pos, .mod)) return .mod;
    if (peekFixedBinaryFunctionCall(tokens, pos, .power)) return .power;
    if (peekGreatestLeastFunctionCall(tokens, pos)) return .greatest_least;
    if (peekFunctionCallTokenIf(tokens, pos, sqlTokenIsJsonExtractPathFunction)) return .json_extract_path;
    if (peekFunctionCallTokenIf(tokens, pos, sqlTokenIsJsonTypeofFunction)) return .json_typeof;
    if (peekFunctionCallTokenIf(tokens, pos, sqlTokenIsJsonArrayLengthFunction)) return .json_array_length;
    if (peekFunctionCallTokenIf(tokens, pos, sqlTokenIsJsonBuildObjectFunction)) return .json_build_object;
    if (value_mod.peekToJsonbFunctionCall(tokens, pos)) return .to_jsonb;
    if (value_mod.peekConvertFromFunctionCall(tokens, pos)) return .convert_from;
    if (functionCallStartsAtTokenIf(tokens, pos, sqlTokenIsArrayLengthFunction)) return .array_length;
    if (functionCallStartsAtTokenIf(tokens, pos, sqlTokenIsArrayPositionFunction)) return .array_position;
    if (peekArrayElementTransformFunctionCall(tokens, pos)) return .array_element_transform;
    if (peekArrayToStringFunctionCall(tokens, pos)) return .array_to_string;
    if (peekStringToArrayFunctionCall(tokens, pos)) return .string_to_array;
    return null;
}

pub fn rowExpressionOperandStartWithFunctionBindingsAt(tokens: []const Token, pos: usize, bindings: SqlFunctionBindings) ?RowExpressionOperandStart {
    if (rowExpressionOperandStartAt(tokens, pos)) |start| return start;
    if (peekExtensionFunctionCall(tokens, pos, bindings.extension_functions)) return .extension_function;
    if (peekRoutineExpressionCall(tokens, pos, bindings.routine_expressions)) return .routine_expression;
    return null;
}

pub fn parseRowExpressionOperandAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    params: []const value_mod.SqlValue,
    schema: runtime_schema.TableSchema,
    joined_source_schema: ?runtime_schema.TableSchema,
    function_bindings: SqlFunctionBindings,
    field_expression_qualifiers: []const []const u8,
    returning_expression_qualifiers: []const []const u8,
    joined_source_expression_qualifiers: []const []const u8,
    joined_target_expression_qualifiers: []const []const u8,
    defer_row_expression_field_validation: bool,
    field_source: db_mod.types.RelationalRowsExpressionFieldSource,
    type_context: RowExpressionTypeContext,
    hooks: RowExpressionOperandParserOptions,
) !db_mod.types.RelationalRowsExpression {
    if (rowExpressionOperandStartWithFunctionBindingsAt(tokens, pos.*, function_bindings)) |start| {
        switch (start) {
            .parenthesized => return try parseParenthesizedRowExpressionAlloc(alloc, tokens, pos, hooks.parenthesized),
            .unary_negative => return try parseUnaryNegativeRowExpressionAlloc(alloc, tokens, pos, params, schema, joined_source_schema, function_bindings, field_expression_qualifiers, returning_expression_qualifiers, joined_source_expression_qualifiers, joined_target_expression_qualifiers, defer_row_expression_field_validation, field_source, type_context, hooks),
            .boolean_not => return try parseBooleanNotRowExpressionAlloc(alloc, tokens, pos, params, schema, joined_source_schema, function_bindings, field_expression_qualifiers, returning_expression_qualifiers, joined_source_expression_qualifiers, joined_target_expression_qualifiers, defer_row_expression_field_validation, field_source, type_context, hooks),
            .extension_function => return (try parseExtensionFunctionRowExpressionOrNullAlloc(alloc, tokens, pos, function_bindings.extension_functions, hooks.extension_function)) orelse unreachable,
            .routine_expression => return (try parseRoutineExpressionRowExpressionOrNullAlloc(alloc, tokens, pos, function_bindings.routine_expressions, hooks.routine_expression)) orelse unreachable,
            .cast => return try parseCastRowExpressionAlloc(alloc, tokens, pos, hooks.cast),
            .case => return try parseCaseRowExpressionAlloc(alloc, tokens, pos, type_context, defer_row_expression_field_validation, hooks.case_expression),
            .now => return try parseSqlNowRowExpressionAlloc(alloc, tokens, pos),
            .current_date => return try parseSqlCurrentDateRowExpressionAlloc(alloc, tokens, pos),
            .typed_datetime_literal => return try parseSqlTypedDatetimeLiteralRowExpressionAlloc(alloc, tokens, pos),
            .uuid_v4 => return try parseSqlUuidV4RowExpression(tokens, pos),
            .interval => return try parseSqlIntervalRowExpressionAlloc(alloc, tokens, pos),
            .case_fold => return try parseCaseFoldRowExpressionAlloc(alloc, tokens, pos, schema, field_expression_qualifiers, returning_expression_qualifiers, defer_row_expression_field_validation, field_source, type_context, hooks.case_fold),
            .replace => return try parseTextTernaryRowExpressionAlloc(alloc, tokens, pos, .replace, type_context, hooks.variadic),
            .regexp_replace => return try parseRegexpListRowExpressionAlloc(alloc, tokens, pos, .regexp_replace, type_context, hooks.variadic),
            .regexp_substr => return try parseTextBinaryRowExpressionAlloc(alloc, tokens, pos, .regexp_substr, type_context, hooks.fixed_binary),
            .regexp_match => return try parseRegexpListRowExpressionAlloc(alloc, tokens, pos, .regexp_match, type_context, hooks.variadic),
            .regexp_count => return try parseTextBinaryRowExpressionAlloc(alloc, tokens, pos, .regexp_count, type_context, hooks.fixed_binary),
            .regexp_instr => return try parseTextBinaryRowExpressionAlloc(alloc, tokens, pos, .regexp_instr, type_context, hooks.fixed_binary),
            .translate => return try parseTextTernaryRowExpressionAlloc(alloc, tokens, pos, .translate, type_context, hooks.variadic),
            .concat => return try parseConcatRowExpressionAlloc(alloc, tokens, pos, type_context, hooks.variadic),
            .coalesce => return try parseCoalesceRowExpressionAlloc(alloc, tokens, pos, type_context, hooks.coalesce),
            .nullif => return try parseNullifRowExpressionAlloc(alloc, tokens, pos, params, schema, joined_source_schema, function_bindings, field_expression_qualifiers, returning_expression_qualifiers, joined_source_expression_qualifiers, joined_target_expression_qualifiers, defer_row_expression_field_validation, field_source, type_context, hooks),
            .text_length => return try parseTextLengthRowExpressionAlloc(alloc, tokens, pos, type_context, hooks.fixed_unary),
            .ascii => return try parseFixedUnaryRowExpressionAlloc(alloc, tokens, pos, .ascii, type_context, .text, hooks.fixed_unary),
            .chr => return try parseFixedUnaryRowExpressionAlloc(alloc, tokens, pos, .chr, type_context, .numeric, hooks.fixed_unary),
            .substring => return try parseSubstringRowExpressionAlloc(alloc, tokens, pos, type_context, hooks.variadic),
            .overlay => return try parseOverlayRowExpressionAlloc(alloc, tokens, pos, type_context, hooks.variadic),
            .split_part => return try parseSplitPartRowExpressionAlloc(alloc, tokens, pos, type_context, hooks.variadic),
            .strpos => return try parseStrposRowExpressionAlloc(alloc, tokens, pos, type_context, hooks.variadic),
            .left_right => return try parseLeftRightRowExpressionAlloc(alloc, tokens, pos, type_context, hooks.fixed_binary),
            .pad => return try parsePadRowExpressionAlloc(alloc, tokens, pos, type_context, hooks.variadic),
            .repeat => return try parseRepeatRowExpressionAlloc(alloc, tokens, pos, type_context, hooks.fixed_binary),
            .reverse => return try parseFixedUnaryRowExpressionAlloc(alloc, tokens, pos, .reverse, type_context, .text, hooks.fixed_unary),
            .md5 => return try parseFixedUnaryRowExpressionAlloc(alloc, tokens, pos, .md5, type_context, .text, hooks.fixed_unary),
            .starts_with => return try parseTextBinaryRowExpressionAlloc(alloc, tokens, pos, .starts_with, type_context, hooks.fixed_binary),
            .ends_with => return try parseTextBinaryRowExpressionAlloc(alloc, tokens, pos, .ends_with, type_context, hooks.fixed_binary),
            .date_trunc => return try parseDateTruncRowExpressionAlloc(alloc, tokens, pos, type_context, hooks.fixed_binary),
            .date_bin => return try parseDateBinRowExpressionAlloc(alloc, tokens, pos, type_context, hooks.variadic),
            .date_part => return try parseDatePartRowExpressionAlloc(alloc, tokens, pos, type_context, hooks.variadic),
            .abs => return try parseFixedUnaryRowExpressionAlloc(alloc, tokens, pos, .abs, type_context, .numeric, hooks.fixed_unary),
            .round => return try parseFixedUnaryRowExpressionAlloc(alloc, tokens, pos, .round, type_context, .numeric, hooks.fixed_unary),
            .trunc => return try parseFixedUnaryRowExpressionAlloc(alloc, tokens, pos, .trunc, type_context, .numeric, hooks.fixed_unary),
            .floor => return try parseFixedUnaryRowExpressionAlloc(alloc, tokens, pos, .floor, type_context, .numeric, hooks.fixed_unary),
            .ceil => return try parseFixedUnaryRowExpressionAlloc(alloc, tokens, pos, .ceil, type_context, .numeric, hooks.fixed_unary),
            .sqrt => return try parseFixedUnaryRowExpressionAlloc(alloc, tokens, pos, .sqrt, type_context, .numeric, hooks.fixed_unary),
            .sign => return try parseFixedUnaryRowExpressionAlloc(alloc, tokens, pos, .sign, type_context, .numeric, hooks.fixed_unary),
            .mod => return try parseFixedNumericBinaryRowExpressionAlloc(alloc, tokens, pos, .mod, type_context, hooks.fixed_binary),
            .power => return try parseFixedNumericBinaryRowExpressionAlloc(alloc, tokens, pos, .power, type_context, hooks.fixed_binary),
            .greatest_least => return try parseGreatestLeastRowExpressionAlloc(alloc, tokens, pos, type_context, hooks.variadic),
            .json_extract_path => return try parseJsonExtractPathRowExpressionAlloc(alloc, tokens, pos, params, type_context, hooks.fixed_unary),
            .json_typeof => return try parseJsonUnaryRowExpressionAlloc(alloc, tokens, pos, .json_typeof, type_context, hooks.fixed_unary),
            .json_array_length => return try parseJsonUnaryRowExpressionAlloc(alloc, tokens, pos, .json_array_length, type_context, hooks.fixed_unary),
            .json_build_object => return try parseJsonBuildObjectRowExpressionAlloc(alloc, tokens, pos, type_context, hooks.json_build_object),
            .to_jsonb => return try parseFixedUnaryRowExpressionAlloc(alloc, tokens, pos, .to_jsonb, type_context, .any, hooks.fixed_unary),
            .convert_from => {
                const value_json = try value_mod.parseJsonValueAlloc(alloc, tokens, pos, params);
                errdefer alloc.free(value_json);
                return .{ .kind = .value, .value_json = value_json };
            },
            .array_length => return try parseArrayLengthRowExpressionAlloc(alloc, tokens, pos, params, schema, field_expression_qualifiers, returning_expression_qualifiers, defer_row_expression_field_validation, field_source),
            .array_position => return try parseArrayPositionRowExpressionAlloc(alloc, tokens, pos, type_context, hooks.fixed_binary),
            .array_element_transform => return try parseArrayElementTransformRowExpressionAlloc(alloc, tokens, pos, type_context, hooks.variadic),
            .array_to_string => return try parseArrayToStringRowExpressionAlloc(alloc, tokens, pos, type_context, hooks.variadic),
            .string_to_array => return try parseStringToArrayRowExpressionAlloc(alloc, tokens, pos, type_context, hooks.fixed_binary),
        }
    }
    if (try parseRowExpressionFieldOperandOrNullAlloc(
        alloc,
        tokens,
        pos,
        schema,
        joined_source_schema,
        params,
        field_expression_qualifiers,
        returning_expression_qualifiers,
        joined_source_expression_qualifiers,
        joined_target_expression_qualifiers,
        defer_row_expression_field_validation,
        field_source,
    )) |expression| return expression;

    const value_json = try value_mod.parseJsonValueAlloc(alloc, tokens, pos, params);
    errdefer alloc.free(value_json);
    return .{ .kind = .value, .value_json = value_json };
}

pub fn parseRowExpressionOperandFromContextAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    params: []const value_mod.SqlValue,
    joined_source_schema: ?runtime_schema.TableSchema,
    function_bindings: SqlFunctionBindings,
    field_source: db_mod.types.RelationalRowsExpressionFieldSource,
    select_context_hooks: SelectParserContextHooks,
    joined_context_hooks: JoinedExpressionParserContextHooks,
    options: RowExpressionOperandParserOptions,
) !db_mod.types.RelationalRowsExpression {
    const select_context = select_context_hooks.get_context(select_context_hooks.ptr);
    const joined_context = joined_context_hooks.get_context(joined_context_hooks.ptr);
    const defer_field_validation =
        select_context.defer_row_expression_field_validation or
        joined_context.defer_row_expression_field_validation or
        joined_context.joined_source_expression_qualifiers.len != 0 or
        joined_context.joined_target_expression_qualifiers.len != 0;
    var type_context = select_context_hooks.row_expression_type_context(select_context_hooks.ptr);
    type_context.defer_row_expression_field_validation = defer_field_validation;
    return try parseRowExpressionOperandAlloc(
        alloc,
        tokens,
        pos,
        params,
        select_context.schema,
        joined_source_schema,
        function_bindings,
        select_context.field_expression_qualifiers,
        select_context.returning_expression_qualifiers,
        joined_context.joined_source_expression_qualifiers,
        joined_context.joined_target_expression_qualifiers,
        defer_field_validation,
        field_source,
        type_context,
        options,
    );
}

pub fn parseRowExpressionFieldOperandOrNullAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    schema: runtime_schema.TableSchema,
    joined_source_schema: ?runtime_schema.TableSchema,
    params: []const value_mod.SqlValue,
    field_expression_qualifiers: []const []const u8,
    returning_expression_qualifiers: []const []const u8,
    joined_source_expression_qualifiers: []const []const u8,
    joined_target_expression_qualifiers: []const []const u8,
    defer_row_expression_field_validation: bool,
    field_source: db_mod.types.RelationalRowsExpressionFieldSource,
) !?db_mod.types.RelationalRowsExpression {
    if (!parser.peekKind(tokens, pos.*, .identifier) or
        parser.peekKeywordTag(tokens, pos.*, .null) or
        parser.peekKeywordTag(tokens, pos.*, .true) or
        parser.peekKeywordTag(tokens, pos.*, .false))
    {
        return null;
    }
    if (pos.* + 1 < tokens.len and tokens[pos.* + 1].kind == .lparen) return error.UnsupportedSqlShape;
    const parsed_field = if (joined_source_expression_qualifiers.len != 0 or joined_target_expression_qualifiers.len != 0)
        try parseIdentifierOwnedAlloc(alloc, tokens, pos)
    else
        try parseRowExpressionFieldOwnedAlloc(
            alloc,
            tokens,
            pos,
            schema,
            field_expression_qualifiers,
            returning_expression_qualifiers,
            defer_row_expression_field_validation,
        );
    defer alloc.free(parsed_field);
    const resolved = try binder.resolveRowExpressionFieldAlloc(
        alloc,
        schema,
        joined_source_schema,
        parsed_field,
        field_expression_qualifiers,
        returning_expression_qualifiers,
        joined_source_expression_qualifiers,
        joined_target_expression_qualifiers,
        defer_row_expression_field_validation,
        field_source,
    );
    var field_transferred = false;
    errdefer if (!field_transferred) alloc.free(resolved.field);
    if (matchJsonExtractOperator(tokens, pos)) |operator| {
        const as_text = tokenKindIsJsonExtractTextOperator(operator);
        if (!defer_row_expression_field_validation and binder.relationalColumnForField(resolved.schema, resolved.field, .json) == null) return error.InvalidSqlCatalog;
        const path = try value_mod.parseJsonExtractOperatorPathOwnedAlloc(alloc, tokens, pos, params, operator);
        var path_transferred = false;
        errdefer if (!path_transferred) alloc.free(path);
        const expression = try buildJsonExtractExpressionAlloc(
            alloc,
            .{ .kind = .field, .field = resolved.field, .field_source = resolved.source },
            path,
            as_text,
        );
        field_transferred = true;
        path_transferred = true;
        return expression;
    }
    if (parser.matchToken(tokens, pos, .question) != null) {
        if (!defer_row_expression_field_validation and binder.relationalColumnForField(resolved.schema, resolved.field, .json) == null) return error.InvalidSqlCatalog;
        const path = try value_mod.parseJsonPathOwnedAlloc(alloc, tokens, pos, params);
        var path_transferred = false;
        errdefer if (!path_transferred) alloc.free(path);
        const expression = try buildJsonPathExistsExpressionAlloc(
            alloc,
            .{ .kind = .field, .field = resolved.field, .field_source = resolved.source },
            path,
        );
        field_transferred = true;
        path_transferred = true;
        return expression;
    }
    if (parser.matchToken(tokens, pos, .question_any) != null or parser.matchToken(tokens, pos, .question_all) != null) {
        const match_all = tokens[pos.* - 1].kind == .question_all;
        if (!defer_row_expression_field_validation and binder.relationalColumnForField(resolved.schema, resolved.field, .json) == null) return error.InvalidSqlCatalog;
        const values_json = try value_mod.parseJsonArrayValueAlloc(alloc, tokens, pos, params);
        defer alloc.free(values_json);
        const expression = try buildJsonKeySetExistsExpressionAlloc(alloc, resolved.field, resolved.source, match_all, values_json);
        field_transferred = true;
        alloc.free(resolved.field);
        return expression;
    }
    if (!defer_row_expression_field_validation and binder.relationalColumnForField(resolved.schema, resolved.field, null) == null) return error.InvalidSqlCatalog;
    field_transferred = true;
    return .{ .kind = .field, .field = resolved.field, .field_source = resolved.source };
}

pub fn peekWindowOutputOrderExpression(tokens: []const Token, pos: usize) bool {
    return peekAggregateOutputOrderExpression(tokens, pos);
}

pub fn peekAggregateHavingExpression(tokens: []const Token, pos: usize) bool {
    if (nextIsAggregateFunction(tokens, pos)) return false;
    if (pos >= tokens.len) return false;
    const token = tokens[pos];
    if (peekParenthesizedExpressionCondition(tokens, pos)) return true;
    if (token.kind == .identifier) {
        if (pos + 1 >= tokens.len) return false;
        const next = tokens[pos + 1];
        if (next.kind == .eq or next.kind == .neq or next.kind == .gt or next.kind == .gte or next.kind == .lt or next.kind == .lte) return false;
        if (next.matchesKeywordTag(.is)) return false;
        return true;
    }
    return token.kind == .minus or
        token.kind == .number or
        parser.peekKeyword(tokens, pos, "lower") or
        parser.peekKeyword(tokens, pos, "upper") or
        parser.peekKeyword(tokens, pos, "trim") or
        peekFunctionCallTokenIf(tokens, pos, sqlTokenIsTrimVariantFunction) or
        parser.peekKeyword(tokens, pos, "replace") or
        parser.peekKeyword(tokens, pos, "regexp_replace") or
        peekFunctionCallTokenIf(tokens, pos, sqlTokenIsRegexpSubstrFunction) or
        peekFunctionCallTokenIf(tokens, pos, sqlTokenIsRegexpMatchFunction) or
        peekFunctionCallTokenIf(tokens, pos, sqlTokenIsRegexpCountFunction) or
        peekFunctionCallTokenIf(tokens, pos, sqlTokenIsRegexpInstrFunction) or
        peekFunctionCallTokenIf(tokens, pos, sqlTokenIsTranslateFunction) or
        parser.peekKeyword(tokens, pos, "case") or
        parser.peekKeyword(tokens, pos, "cast") or
        parser.peekKeyword(tokens, pos, "coalesce") or
        parser.peekKeyword(tokens, pos, "nullif") or
        peekTextLengthFunctionKeyword(tokens, pos) or
        peekFunctionCallTokenIf(tokens, pos, sqlTokenIsAsciiFunction) or
        peekFunctionCallTokenIf(tokens, pos, sqlTokenIsChrFunction) or
        peekSubstringFunctionKeyword(tokens, pos) or
        peekFunctionCallTokenIf(tokens, pos, sqlTokenIsOverlayFunction) or
        peekSplitPartFunctionKeyword(tokens, pos) or
        peekStrposFunctionKeyword(tokens, pos) or
        peekFunctionCallTokenIf(tokens, pos, sqlTokenIsLeftRightFunction) or
        peekFunctionCallTokenIf(tokens, pos, sqlTokenIsPadFunction) or
        peekFunctionCallTokenIf(tokens, pos, sqlTokenIsRepeatFunction) or
        peekFunctionCallTokenIf(tokens, pos, sqlTokenIsReverseFunction) or
        peekFunctionCallTokenIf(tokens, pos, sqlTokenIsMd5Function) or
        peekFunctionCallTokenIf(tokens, pos, sqlTokenIsStartsWithFunction) or
        peekFunctionCallTokenIf(tokens, pos, sqlTokenIsEndsWithFunction) or
        peekFunctionCallTokenIf(tokens, pos, sqlTokenIsDateTruncFunction) or
        peekFunctionCallTokenIf(tokens, pos, sqlTokenIsDateBinFunction) or
        peekFunctionCallTokenIf(tokens, pos, sqlTokenIsDatePartFunction) or
        parser.peekKeyword(tokens, pos, "position") or
        parser.peekKeyword(tokens, pos, "abs") or
        parser.peekKeyword(tokens, pos, "round") or
        peekFunctionCallTag(tokens, pos, .trunc) or
        peekFunctionCallTag(tokens, pos, .floor) or
        peekFunctionCallTag(tokens, pos, .ceil) or
        peekFunctionCallTag(tokens, pos, .sqrt) or
        peekFunctionCallTag(tokens, pos, .sign) or
        peekFunctionCallTag(tokens, pos, .mod) or
        peekFunctionCallTag(tokens, pos, .power) or
        parser.peekKeyword(tokens, pos, "greatest") or
        parser.peekKeyword(tokens, pos, "least");
}

pub fn appendExpressionValuesJsonConjunction(
    alloc: std.mem.Allocator,
    type_context: RowExpressionTypeContext,
    expression_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition),
    lhs: db_mod.types.RelationalRowsExpression,
    values_json: []const u8,
) !void {
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, values_json, .{}) catch return error.UnsupportedSqlShape;
    defer parsed.deinit();
    if (parsed.value != .array or parsed.value.array.items.len == 0 or parsed.value.array.items.len > max_scalar_or_expanded_branches) return error.UnsupportedSqlShape;
    try validateExpressionScalarMembershipValues(type_context, lhs, parsed.value);

    for (parsed.value.array.items) |value| {
        const lhs_clone = try cloneExpressionAlloc(alloc, lhs);
        var lhs_transferred = false;
        errdefer if (!lhs_transferred) freeExpression(alloc, lhs_clone);

        const value_json = try std.json.Stringify.valueAlloc(alloc, value, .{});
        var value_transferred = false;
        errdefer if (!value_transferred) alloc.free(value_json);

        const rhs = try alloc.alloc(db_mod.types.RelationalRowsExpression, 1);
        var rhs_transferred = false;
        errdefer if (!rhs_transferred) alloc.free(rhs);
        rhs[0] = .{
            .kind = .value,
            .value_json = value_json,
        };
        value_transferred = true;

        try expression_predicates.append(alloc, .{
            .lhs = lhs_clone,
            .op = .eq,
            .rhs = rhs,
        });
        lhs_transferred = true;
        rhs_transferred = true;
    }
}

pub fn appendExpressionValuesJsonOrGroups(
    alloc: std.mem.Allocator,
    type_context: RowExpressionTypeContext,
    expression_or_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
    lhs: db_mod.types.RelationalRowsExpression,
    values_json: []const u8,
) !void {
    try appendExpressionValuesJsonComparisonGroups(alloc, type_context, expression_or_predicates, lhs, values_json, .eq);
}

pub fn appendExpressionValuesJsonConjunctionGroup(
    alloc: std.mem.Allocator,
    type_context: RowExpressionTypeContext,
    expression_or_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
    lhs: db_mod.types.RelationalRowsExpression,
    values_json: []const u8,
    op: runtime_schema.RelationalCheckOp,
) !void {
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, values_json, .{}) catch return error.UnsupportedSqlShape;
    defer parsed.deinit();
    if (parsed.value != .array or parsed.value.array.items.len == 0 or parsed.value.array.items.len > max_scalar_or_expanded_branches) return error.UnsupportedSqlShape;
    try validateExpressionScalarMembershipValues(type_context, lhs, parsed.value);

    const conditions = try alloc.alloc(db_mod.types.RelationalRowsExpressionCondition, parsed.value.array.items.len);
    var condition_count: usize = 0;
    errdefer {
        for (conditions[0..condition_count]) |condition| freeExpressionCondition(alloc, condition);
        alloc.free(conditions);
    }

    for (parsed.value.array.items) |value| {
        if (op == .ne and value == .null) return error.UnsupportedSqlShape;

        const lhs_clone = try cloneExpressionAlloc(alloc, lhs);
        var lhs_transferred = false;
        errdefer if (!lhs_transferred) freeExpression(alloc, lhs_clone);

        const value_json = try std.json.Stringify.valueAlloc(alloc, value, .{});
        var value_transferred = false;
        errdefer if (!value_transferred) alloc.free(value_json);

        const rhs = try alloc.alloc(db_mod.types.RelationalRowsExpression, 1);
        var rhs_transferred = false;
        errdefer if (!rhs_transferred) alloc.free(rhs);
        rhs[0] = .{
            .kind = .value,
            .value_json = value_json,
        };
        value_transferred = true;

        conditions[condition_count] = .{
            .lhs = lhs_clone,
            .op = op,
            .rhs = rhs,
        };
        condition_count += 1;
        lhs_transferred = true;
        rhs_transferred = true;
    }

    try expression_or_predicates.append(alloc, .{ .conditions = conditions });
}

pub fn appendExpressionValuesJsonComparisonGroups(
    alloc: std.mem.Allocator,
    type_context: RowExpressionTypeContext,
    expression_or_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
    lhs: db_mod.types.RelationalRowsExpression,
    values_json: []const u8,
    op: runtime_schema.RelationalCheckOp,
) !void {
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, values_json, .{}) catch return error.UnsupportedSqlShape;
    defer parsed.deinit();
    if (parsed.value != .array or parsed.value.array.items.len == 0 or parsed.value.array.items.len > max_scalar_or_expanded_branches) return error.UnsupportedSqlShape;
    try validateExpressionScalarMembershipValues(type_context, lhs, parsed.value);

    for (parsed.value.array.items) |value| {
        const lhs_clone = try cloneExpressionAlloc(alloc, lhs);
        var lhs_transferred = false;
        errdefer if (!lhs_transferred) freeExpression(alloc, lhs_clone);

        const value_json = try std.json.Stringify.valueAlloc(alloc, value, .{});
        var value_transferred = false;
        errdefer if (!value_transferred) alloc.free(value_json);

        const rhs = try alloc.alloc(db_mod.types.RelationalRowsExpression, 1);
        var rhs_transferred = false;
        errdefer if (!rhs_transferred) alloc.free(rhs);
        rhs[0] = .{
            .kind = .value,
            .value_json = value_json,
        };
        value_transferred = true;

        const condition: db_mod.types.RelationalRowsExpressionCondition = .{
            .lhs = lhs_clone,
            .op = op,
            .rhs = rhs,
        };
        var condition_transferred = false;
        errdefer if (!condition_transferred) freeExpressionCondition(alloc, condition);
        lhs_transferred = true;
        rhs_transferred = true;

        const conditions = try alloc.alloc(db_mod.types.RelationalRowsExpressionCondition, 1);
        var conditions_transferred = false;
        errdefer if (!conditions_transferred) alloc.free(conditions);
        conditions[0] = condition;
        condition_transferred = true;

        try expression_or_predicates.append(alloc, .{ .conditions = conditions });
        conditions_transferred = true;
    }
}

pub fn validateExpressionScalarMembershipValues(
    type_context: RowExpressionTypeContext,
    lhs: db_mod.types.RelationalRowsExpression,
    values: std.json.Value,
) !void {
    if (values != .array) return error.UnsupportedSqlShape;
    const lhs_type = try type_context.rowExpressionOutputType(lhs);
    if (lhs_type == .array or lhs_type == .json or lhs_type == .embedding) return error.UnsupportedSqlShape;
    for (values.array.items) |value| {
        if (!value_mod.sqlScalarValueMatches(lhs_type, value)) return error.UnsupportedSqlShape;
    }
}

pub fn validateExpressionConditionTypes(
    type_context: RowExpressionTypeContext,
    defer_row_expression_field_validation: bool,
    lhs: db_mod.types.RelationalRowsExpression,
    op: runtime_schema.RelationalCheckOp,
    rhs: []const db_mod.types.RelationalRowsExpression,
) !void {
    if (defer_row_expression_field_validation) {
        switch (op) {
            .is_null, .is_not_null => if (rhs.len != 0) return error.UnsupportedSqlShape,
            .eq, .ne, .is_distinct, .is_not_distinct, .gt, .gte, .lt, .lte => if (rhs.len != 1) return error.UnsupportedSqlShape,
        }
        return;
    }
    switch (op) {
        .is_null, .is_not_null => {
            if (rhs.len != 0) return error.UnsupportedSqlShape;
            return;
        },
        .eq, .ne, .is_distinct, .is_not_distinct, .gt, .gte, .lt, .lte => {
            if (rhs.len != 1) return error.UnsupportedSqlShape;
        },
    }
    const lhs_type = try type_context.rowExpressionOutputType(lhs);
    const rhs_expression = rhs[0];
    if (try type_context.rowExpressionIsNullLiteral(rhs_expression)) return;
    const rhs_type = try type_context.rowExpressionOutputType(rhs_expression);
    if (!sqlExpressionTypesComparable(lhs_type, rhs_type)) return error.UnsupportedSqlShape;
    switch (op) {
        .gt, .gte, .lt, .lte => if (!sqlExpressionTypeIsOrderable(lhs_type) or !sqlExpressionTypeIsOrderable(rhs_type)) return error.UnsupportedSqlShape,
        else => {},
    }
}

