    ));

    var null_first = try lowerQueryPlanForLowerExprTestAlloc(
        alloc,
        "SELECT greatest(NULL, amount, 0) AS max_amount FROM invoices WHERE id = $1",
        schema,
        &.{.{ .string = "u1" }},
